:root {
  --bg-app: #030712;
  --bg-glass: rgba(17, 24, 39, 0.65);
  --bg-glass-hover: rgba(31, 41, 55, 0.8);
  --border-glass: rgba(255, 255, 255, 0.08);
  --border-light: rgba(255, 255, 255, 0.15);
  --text-main: #f9fafb;
  --text-primary: #f9fafb;
  --text-secondary: #d1d5db;
  --text-muted: #9ca3af;
  --accent-primary: #f58220;
  --accent-primary-hover: #e06f0f;
  --accent-primary-light: #ff9a3c;
  --accent-red: #ef4444;
  --sidebar-width: 220px;
  --sidebar-collapsed: 64px;
  --header-height: 72px;
  --products-search-height: 3.35rem;
  --shadow-glass: 0 8px 32px rgba(0, 0, 0, 0.37);
  --blur-glass: blur(16px);
  --transition-smooth: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Outfit', sans-serif;
  background: var(--bg-app);
  color: var(--text-main);
  line-height: 1.6;
  overflow-x: hidden;
  background-image:
    radial-gradient(circle at 15% 50%, rgba(245, 130, 32, 0.12), transparent 25%),
    radial-gradient(circle at 85% 30%, rgba(224, 111, 15, 0.08), transparent 25%);
  background-attachment: fixed;
}

html {
  color-scheme: dark;
  scrollbar-gutter: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

html::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.fade-in { animation: fadeIn 0.45s ease-out forwards; }

@media (max-width: 768px) {
  .fade-in { animation-duration: 0.16s; }
}

.glass {
  background: var(--bg-glass);
  backdrop-filter: var(--blur-glass);
  -webkit-backdrop-filter: var(--blur-glass);
  border: 1px solid var(--border-glass);
  box-shadow: var(--shadow-glass);
}

.flex { display: flex; }
.flex-wrap { flex-wrap: wrap; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-end { justify-content: flex-end; }
.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 0.75rem; }
.mt-2 { margin-top: 0.5rem; }
.mt-4 { margin-top: 1rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-6 { margin-bottom: 1.5rem; }
.mx-auto { margin-left: auto; margin-right: auto; }
.p-4 { padding: 1rem; }
.w-full { width: 100%; }
.text-muted { color: var(--text-muted); }
.text-sm { font-size: 0.875rem; }
.text-red { color: var(--accent-red); }
.text-right { text-align: right !important; }
.text-center { text-align: center; }
.col-span-all { grid-column: 1 / -1; }
.max-w-4xl { max-width: 56rem; }

.full-screen-loader-container,
.login-container {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ——— Main /login hero (compact, no-scroll target) ——— */
.login-hero {
  --login-bg: #0b1219;
  --login-panel: #151d28;
  --login-border: #2a3441;
  --login-muted: #8b95a5;
  --login-orange: #f58220;
  --login-link: #7eb6e8;
  --login-input-bg: #0f1620;
  min-height: 100vh;
  min-height: 100dvh;
  max-height: 100dvh;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.65rem 1rem;
  background: var(--login-bg);
  color: #fff;
}

.login-hero.login-hero--flow {
  overflow: auto;
  max-height: none;
  min-height: 100dvh;
  align-items: stretch;
  padding-top: 1.25rem;
  padding-bottom: 1.5rem;
}

.login-hero--flow .login-hero__inner {
  min-height: calc(100dvh - 2.75rem);
  justify-content: flex-start;
}

.login-hero__dock {
  width: 100%;
  margin-top: auto;
  padding-top: 1.75rem;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.login-hero .dealer-login-info,
.login-hero .dealer-login-panel,
.login-hero .dealer-login-picker__option {
  background: var(--login-input-bg);
  border-color: var(--login-border);
  color: #e8eef5;
}

.login-hero .dealer-login-back {
  color: var(--login-muted);
}

.login-hero__form > .login-hero__forgot {
  display: block;
  width: 100%;
  margin-top: 0.65rem;
  text-align: center;
}

.dealer-login-registered {
  width: 100%;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.85rem;
  text-align: center;
}

.dealer-login-registered__label {
  margin: 0;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--login-muted);
}

.dealer-login-registered__name {
  margin: 0;
  width: 80%;
  max-width: 80%;
}

.dealer-login-registered__name-text {
  display: block;
  width: 100%;
  font-size: 1.2rem;
  font-weight: 700;
  line-height: 1.2;
  color: #fff;
  letter-spacing: -0.02em;
  white-space: nowrap;
  overflow: hidden;
}

.dealer-login-registered .login-hero__submit {
  margin-top: 0;
}

.dealer-login-registered__forgot {
  margin-top: 0.15rem;
}

.login-hero__inner {
  width: min(100%, 440px);
  max-height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.login-hero__brand {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  margin-bottom: 0.7rem;
}

.login-hero__logo {
  margin-bottom: 0.45rem;
}

.login-hero__logo .brand-logo {
  height: 48px;
}

.login-hero__welcome {
  margin: 0;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #fff;
  line-height: 1.15;
}

.login-hero__tagline {
  margin: 0.25rem 0 0;
  font-size: 0.82rem;
  font-weight: 400;
  color: var(--login-muted);
  letter-spacing: 0.01em;
}

.login-hero__features {
  list-style: none;
  margin: 0 0 0.75rem;
  padding: 0.55rem 0.25rem;
  width: 100%;
  display: flex;
  flex-wrap: nowrap;
  align-items: stretch;
  justify-content: space-between;
  gap: 0;
  background: var(--login-panel);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
}

.login-hero__feature {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 0.28rem;
  padding: 0.1rem 0.25rem;
  text-align: center;
  color: var(--login-orange);
}

.login-hero__feature svg {
  color: var(--login-orange);
  flex-shrink: 0;
}

.login-hero__feature span:last-child {
  font-size: 0.58rem;
  font-weight: 500;
  line-height: 1.2;
  color: #dfe6f0;
  max-width: 100%;
}

.login-hero__feature-rule {
  position: absolute;
  left: 0;
  top: 14%;
  bottom: 14%;
  width: 1px;
  background: rgba(255, 255, 255, 0.1);
}

.login-hero__form-wrap {
  width: 100%;
}

.login-hero--flow .login-hero__form-wrap {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.login-hero__signin-title {
  margin: 0 0 0.7rem;
  text-align: center;
  font-size: 0.92rem;
  font-weight: 500;
  color: #fff;
  line-height: 1.3;
}

.login-hero__signin-accent {
  display: inline;
  padding-bottom: 0.12rem;
  border-bottom: 2px solid var(--login-orange);
  font-weight: 500;
}

.login-hero__form {
  text-align: left;
}

.login-hero__form--signup-phone {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.login-hero__form--signup-phone .form-group {
  width: 80%;
}

.login-hero__form--signup-phone .login-hero__submit {
  width: 50%;
}

.login-hero__form--set-password {
  gap: 0.55rem;
}

.login-hero__form--set-password .form-group {
  margin-bottom: 0;
}

.login-hero__form--set-password .login-hero__submit {
  margin-top: 0.15rem;
  min-height: 38px;
  padding: 0.4rem 0.9rem;
  font-size: 0.88rem;
}

.dealer-login-setpw-head {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 80%;
  margin-bottom: 0.1rem;
  text-align: left;
  color: var(--login-orange);
}

.dealer-login-setpw-copy {
  min-width: 0;
  flex: 1;
}

.dealer-login-setpw-head strong {
  display: block;
  font-size: 0.95rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.dealer-login-setpw-name {
  display: block;
  width: 100%;
  margin-top: 0.12rem;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--login-muted);
  white-space: nowrap;
  overflow: hidden;
}

.login-dev-quick {
  margin: 0 0 0.85rem;
  padding: 0.7rem 0.75rem 0.8rem;
  border: 1px dashed rgba(245, 130, 32, 0.45);
  border-radius: 10px;
  background: rgba(245, 130, 32, 0.08);
}

.login-dev-quick__badge {
  display: inline-flex;
  align-items: center;
  margin-bottom: 0.4rem;
  padding: 0.12rem 0.45rem;
  border-radius: 999px;
  background: rgba(245, 130, 32, 0.2);
  color: #ffd5a8;
  font-size: 0.625rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.login-dev-quick__label {
  display: block;
  margin-bottom: 0.28rem;
  font-size: 0.84rem;
  font-weight: 500;
  color: #fff;
}

.login-dev-quick__select {
  width: 100%;
  min-height: 42px;
  padding: 0.45rem 0.7rem;
  border: 1px solid var(--login-border);
  border-radius: 9px;
  background: var(--login-input-bg);
  color: #fff;
  font: inherit;
  font-size: 0.9rem;
  cursor: pointer;
}

.login-dev-quick__select:focus {
  border-color: var(--login-orange);
  outline: none;
  box-shadow: 0 0 0 1px rgba(245, 130, 32, 0.25);
}

.login-dev-quick__select:disabled {
  opacity: 0.6;
  cursor: wait;
}

.login-dev-quick__select option {
  color: #0f172a;
  background: #fff;
}

.login-hero__form .form-group {
  margin-bottom: 0.65rem;
}

.login-hero__form .form-group label {
  display: block;
  margin-bottom: 0.28rem;
  font-size: 0.84rem;
  font-weight: 500;
  color: #fff;
}

.login-hero__input.input-field {
  background: var(--login-input-bg);
  border: 1px solid var(--login-border);
  border-radius: 9px;
  color: #fff;
  min-height: 42px;
  font-size: 0.9rem;
}

.login-hero__input.input-field::placeholder {
  color: #6b7585;
}

.login-hero__input.input-field:focus {
  border-color: var(--login-orange);
  outline: none;
  box-shadow: 0 0 0 1px rgba(245, 130, 32, 0.25);
}

.login-hero__form .input-icon {
  color: #6b7585;
}

.login-hero__form .input-icon-right {
  color: #6b7585;
}

.login-hero__form .input-icon-wrap:has(.input-icon-right) .input-with-icon {
  padding-right: 2.5rem;
}

.login-hero__hint {
  margin: 0.28rem 0 0;
  font-size: 0.7rem;
  color: var(--login-muted);
  line-height: 1.3;
}

.login-hero__password-group {
  margin-bottom: 0.2rem;
}

.login-hero__forgot-row {
  display: flex;
  justify-content: flex-end;
  margin-top: 0.28rem;
}

.login-hero__forgot {
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--login-link);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.login-hero__forgot:hover {
  color: #a8d0f5;
}

button.login-hero__forgot {
  display: inline;
  padding: 0;
  border: none;
  background: none;
  font: inherit;
  font-size: inherit;
  font-weight: inherit;
  cursor: pointer;
}

.login-hero__submit {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  width: 100%;
  margin-top: 0.7rem;
  min-height: 44px;
  padding: 0.65rem 1rem;
  border: none;
  border-radius: 9px;
  background: var(--login-orange);
  color: #0b1219;
  font-family: inherit;
  font-size: 0.98rem;
  font-weight: 700;
  cursor: pointer;
  transition: filter 0.15s ease, transform 0.1s ease;
}

.login-hero__submit:hover:not(:disabled) {
  filter: brightness(1.06);
}

.login-hero__submit:active:not(:disabled) {
  transform: translateY(1px);
}

.login-hero__submit:disabled {
  opacity: 0.7;
  cursor: wait;
}

.login-hero__spinner {
  border-color: rgba(11, 18, 25, 0.25);
  border-top-color: #0b1219;
}

.login-hero__bottom-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  width: 100%;
  margin-top: 0.7rem;
  padding: 0.55rem 0.75rem;
  background: var(--login-panel);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
}

.login-hero__bottom-title {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--login-orange);
  letter-spacing: 0.02em;
}

.login-hero__bottom-title::after {
  content: '·';
  margin-left: 0.5rem;
  color: rgba(255, 255, 255, 0.25);
  font-weight: 400;
}

.login-hero__bottom-link {
  font-size: 0.8rem;
  font-weight: 500;
  color: #e8edf4;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.login-hero__bottom-link:hover {
  color: #fff;
}

.login-hero__help {
  width: 100%;
  margin-top: 0.55rem;
  padding: 0.65rem 0.65rem 0.6rem;
  background: var(--login-panel);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
}

.login-hero__help-title {
  margin: 0 0 0.5rem;
  text-align: center;
  font-size: 0.85rem;
  font-weight: 500;
  color: #fff;
}

.login-hero__help-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.45rem;
}

.login-hero__help-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 48px;
  padding: 0.45rem 0.6rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  background: transparent;
  color: #fff;
  text-decoration: none;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.login-hero__help-btn:hover {
  background: rgba(255, 255, 255, 0.04);
  border-color: rgba(255, 255, 255, 0.16);
}

.login-hero__help-btn--call {
  color: var(--login-orange);
}

.login-hero__help-btn--whatsapp {
  color: #25d366;
}

.login-hero__whatsapp-icon {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
}

.login-hero__help-btn-text {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.06rem;
  min-width: 0;
}

.login-hero__help-btn-text strong {
  font-size: 0.84rem;
  font-weight: 700;
  color: #fff;
  line-height: 1.15;
}

.login-hero__help-btn-text span {
  font-size: 0.68rem;
  font-weight: 400;
  color: var(--login-muted);
  line-height: 1.15;
}

.login-hero__trust {
  width: 100%;
  margin-top: 0.55rem;
  padding-top: 0.55rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  text-align: center;
}

.login-hero__trust-safe {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.3rem;
  margin: 0 0 0.2rem;
  font-size: 0.74rem;
  font-weight: 500;
  color: #c5ceda;
}

.login-hero__trust-safe svg {
  color: var(--login-muted);
  flex-shrink: 0;
}

.login-hero__trust-copy {
  margin: 0;
  font-size: 0.68rem;
  font-weight: 400;
  color: var(--login-muted);
  letter-spacing: 0.02em;
}

@media (max-height: 760px) {
  .login-hero {
    padding: 0.4rem 0.85rem;
  }

  .login-hero__logo .brand-logo {
    height: 40px;
  }

  .login-hero__welcome {
    font-size: 1.2rem;
  }

  .login-hero__tagline {
    font-size: 0.75rem;
  }

  .login-hero__hint {
    display: none;
  }

  .login-hero__help-btn {
    min-height: 42px;
  }
}

@media (max-width: 560px) {
  .login-hero {
    padding: 0.5rem 0.75rem;
    align-items: center;
  }

  .login-hero__feature span:last-child {
    font-size: 0.54rem;
  }
}

.loader-ring {
  width: 42px;
  height: 42px;
  border: 3px solid rgba(255, 255, 255, 0.12);
  border-top-color: var(--accent-primary);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

.spinner-inline {
  width: 18px;
  height: 18px;
  border: 2px solid rgba(255, 255, 255, 0.25);
  border-top-color: white;
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
  display: inline-block;
}

.fetching-loader {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.85rem;
  padding: 1.75rem 1rem;
  text-align: center;
}

.fetching-loader__visual {
  position: relative;
  width: 4.25rem;
  height: 4.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.fetching-loader__ring {
  position: absolute;
  inset: 0;
  border: 3px solid rgba(255, 255, 255, 0.1);
  border-top-color: var(--accent-primary);
  border-right-color: color-mix(in srgb, var(--accent-primary) 45%, transparent);
  border-radius: 50%;
  animation: spin 0.85s linear infinite;
}

.fetching-loader__logo {
  position: relative;
  z-index: 1;
}

.fetching-loader__logo .brand-logo {
  height: 1.65rem;
}

.fetching-loader__label {
  margin: 0;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.02em;
}

.dealers-tiles__loading {
  width: 100%;
  padding: 2rem 1rem;
}

.app-wrapper {
  display: flex;
  min-height: 100vh;
  width: 100%;
  max-width: 100%;
  overflow-x: hidden;
}

.sidebar {
  --nav-item-min-h: 1.95rem;
  --nav-item-max-h: 2.4rem;
  width: var(--sidebar-width);
  background: rgba(10, 15, 28, 0.85);
  backdrop-filter: var(--blur-glass);
  border-right: 1px solid var(--border-glass);
  display: flex;
  flex-direction: column;
  position: fixed;
  inset: 0 auto 0 0;
  height: 100dvh;
  z-index: 50;
  transition: var(--transition-smooth);
  overflow: hidden;
}

.sidebar.collapsed { width: var(--sidebar-collapsed); }

.sidebar.mobile-open { transform: translateX(0); }

/* Invoice-access (and similar): keep main + profile menus stacked under the logo. */
.sidebar.sidebar--nav-top .nav-menu {
  flex: 0 1 auto;
  justify-content: flex-start;
}

.sidebar.sidebar--nav-top .sidebar-profile {
  border-top: none;
  padding-top: 0;
}

.sidebar-header {
  height: var(--header-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1rem;
  border-bottom: 1px solid var(--border-glass);
  flex-shrink: 0;
}

.sidebar-header--compact {
  height: 2.75rem;
  justify-content: flex-end;
  padding: 0 0.45rem;
}

.logo-area {
  display: flex;
  align-items: center;
  align-self: stretch;
  gap: 0.75rem;
  min-height: 0;
}

.brand-logo-wrap {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  min-width: 0;
  height: 100%;
}

.brand-logo {
  display: block;
  width: auto;
  object-fit: contain;
  object-position: left center;
  flex-shrink: 0;
}

.brand-tagline {
  font-size: 0.8rem;
  line-height: 1.45;
  color: var(--text-muted);
  max-width: 28ch;
  margin: 0;
}

.logo-text {
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1;
  margin: 0;
  white-space: nowrap;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.collapse-btn,
.mobile-menu-btn {
  position: relative;
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  width: 36px;
  height: 36px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-unread--menu {
  position: absolute;
  top: -0.15rem;
  right: -0.2rem;
  min-width: 1rem;
  height: 1rem;
  padding: 0 0.22rem;
  border-radius: 999px;
  background: #ef4444;
  color: white;
  font-size: 0.62rem;
  font-weight: 700;
  line-height: 1rem;
  text-align: center;
}

.collapse-btn:hover,
.mobile-menu-btn:hover {
  background: var(--bg-glass-hover);
  color: white;
}

.sidebar.collapsed .logo-text,
.sidebar.collapsed .nav-label { display: none; }

.nav-icon--whatsapp {
  display: block;
  color: #fff;
}

.nav-menu {
  flex: 1;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0.4rem 0.55rem;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: 0.12rem;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: rgba(148, 163, 184, 0.35) transparent;
}

.sidebar:not(.sidebar--mobile) .nav-menu::-webkit-scrollbar {
  width: 4px;
}

.sidebar:not(.sidebar--mobile) .nav-menu::-webkit-scrollbar-thumb {
  background: rgba(148, 163, 184, 0.35);
  border-radius: 999px;
}

.sidebar:not(.sidebar--mobile) .nav-menu::-webkit-scrollbar-track {
  background: transparent;
}

.nav-menu--sectioned {
  justify-content: flex-start;
  overflow-y: auto;
  gap: 0.25rem;
}

.nav-section {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

.nav-section + .nav-section {
  margin-top: 0.5rem;
  padding-top: 0.5rem;
  border-top: 1px solid var(--border-glass);
}

.nav-section__toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 0.35rem 1rem 0.5rem;
  border: none;
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
}

.nav-section__toggle:hover {
  color: var(--text-main);
}

.nav-section__chevron {
  flex-shrink: 0;
  transition: transform 0.2s ease;
}

.nav-section__chevron--collapsed {
  transform: rotate(-90deg);
}

.sidebar.collapsed .nav-section__toggle {
  display: none;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.36rem 0.75rem;
  min-height: var(--nav-item-min-h, 1.95rem);
  max-height: var(--nav-item-max-h, 2.4rem);
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  width: 100%;
  text-align: left;
  font: inherit;
  font-size: 0.9375rem;
  line-height: 1.25;
  transition: var(--transition-smooth);
  flex: 0 0 auto;
  min-width: 0;
}

.sidebar:not(.sidebar--nav-top) > .nav-menu > .nav-item {
  flex: 1 1 0;
  max-height: none;
}

.nav-icon {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  width: 18px;
  height: 18px;
}

.nav-icon svg {
  width: 18px;
  height: 18px;
}

.nav-label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.nav-item:hover {
  background: var(--bg-glass-hover);
  color: var(--text-main);
}

.nav-item.active {
  background: linear-gradient(90deg, rgba(245, 130, 32, 0.18), transparent);
  color: var(--accent-primary);
  border-left: 3px solid var(--accent-primary);
}

.profile-actions,
.sidebar-profile {
  flex-shrink: 0;
  padding: 0.4rem 0.55rem 0.6rem;
  border-top: 1px solid var(--border-glass);
}

.sidebar-profile .nav-item {
  flex: 0 0 auto;
  min-height: var(--nav-item-min-h, 1.875rem);
  max-height: var(--nav-item-max-h, 2.75rem);
}

.profile-page {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 40rem;
  margin: 0 auto;
}

.profile-page__panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.profile-page__panel--dealer.panel {
  padding: 0;
  overflow: hidden;
}

.profile-page__panel .dealers-detail__form--readonly {
  margin-top: 0;
}

.profile-page__error {
  margin: 0.85rem 0.95rem 0;
}

.profile-page__panel--dealer .fetching-loader {
  padding: 2rem 1rem;
}

.profile-page__signout {
  margin-top: auto;
  padding-top: 1.25rem;
  border-top: 1px solid var(--border-glass);
}

.dealer-profile {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  padding: 1rem 1.05rem 1.05rem;
}

.dealer-profile__header {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  padding-bottom: 0.85rem;
  border-bottom: 1px solid var(--border-glass);
}

.dealer-profile__mark {
  flex-shrink: 0;
  width: 3rem;
  height: 3rem;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: linear-gradient(145deg, var(--accent-primary), var(--accent-primary-hover));
  color: #fff;
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  box-shadow: 0 8px 18px rgba(245, 130, 32, 0.28);
}

.dealer-profile__identity {
  min-width: 0;
}

.dealer-profile__kicker {
  margin: 0 0 0.18rem;
  font-size: 0.64rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.dealer-profile__name {
  margin: 0;
  font-size: 1.12rem;
  font-weight: 650;
  line-height: 1.25;
  color: var(--text-primary);
}

.dealer-profile__badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.4rem;
}

.dealer-profile__photo,
.dealer-profile__photo--placeholder {
  flex-shrink: 0;
  width: 3.35rem;
  height: 3.35rem;
  border-radius: 50%;
  object-fit: cover;
  background: rgba(15, 23, 42, 0.65);
}

.dealer-profile__photo--placeholder {
  display: grid;
  place-items: center;
  color: var(--text-muted);
  border: 1.5px dashed rgba(148, 163, 184, 0.38);
}

.dealer-profile__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.55rem 0.85rem;
  margin: 0;
}

.dealer-profile__grid--location {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.dealer-profile__field {
  min-width: 0;
}

.dealer-profile__field--full {
  grid-column: 1 / -1;
}

.dealer-profile__field dt {
  margin: 0 0 0.1rem;
  font-size: 0.64rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.dealer-profile__field dd {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 500;
  line-height: 1.35;
  color: var(--text-primary);
  word-break: break-word;
}

.dealer-profile__field a {
  color: inherit;
  text-decoration: none;
}

.dealer-profile__field a:hover {
  color: var(--accent-primary-light);
}

.dealer-profile__addresses {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
}

.dealer-profile__address {
  min-width: 0;
  padding: 0.65rem 0.72rem;
  border-radius: 12px;
  border: 1px solid var(--border-glass);
  background: rgba(15, 23, 42, 0.38);
}

.dealer-profile__address-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
}

.dealer-profile__edit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.7rem;
  height: 1.7rem;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: rgba(245, 130, 32, 0.14);
  color: var(--accent-primary-light);
  cursor: pointer;
}

.dealer-profile__edit:hover {
  background: var(--accent-primary);
  color: #fff;
}

.dealer-profile__address-input {
  margin-top: 0.4rem;
  min-height: 5.5rem;
  resize: vertical;
  font-size: 0.8125rem;
  line-height: 1.45;
}

.dealer-profile__address-error {
  margin: 0.4rem 0 0;
  font-size: 0.75rem;
  font-weight: 600;
  color: #fca5a5;
}

.dealer-profile__address-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.4rem;
  margin-top: 0.5rem;
}

.dealer-profile__address-actions .btn {
  min-height: 2rem;
  padding: 0.35rem 0.7rem;
  font-size: 0.78rem;
}

.dealer-profile__address h3,
.dealer-profile__map-head h3 {
  margin: 0;
  font-size: 0.64rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.dealer-profile__address p {
  margin: 0.35rem 0 0;
  font-size: 0.8125rem;
  font-weight: 500;
  line-height: 1.5;
  color: var(--text-primary);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.dealer-profile__map {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.dealer-profile__map-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.dealer-profile__map-open {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent-primary-light);
  text-decoration: none;
}

.dealer-profile__map iframe {
  display: block;
  width: 100%;
  height: 10.25rem;
  border: 0;
  border-radius: 12px;
  background: rgba(15, 23, 42, 0.45);
}

.dealer-profile__map-empty {
  margin: 0;
  padding: 0.85rem 0.75rem;
  border-radius: 12px;
  border: 1px dashed var(--border-glass);
  font-size: 0.8rem;
  color: var(--text-muted);
  text-align: center;
}

.dealer-profile__signout {
  width: 100%;
  margin-top: 0.15rem;
  padding: 0.62rem 0.85rem;
  border: 1px solid rgba(239, 68, 68, 0.22);
  border-radius: 12px;
  background: rgba(239, 68, 68, 0.08);
  color: #fca5a5;
  cursor: pointer;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
}

.dealer-profile__signout:hover {
  background: var(--accent-red);
  border-color: var(--accent-red);
  color: #fff;
}

.staff-id-card-wrap {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.staff-id-card {
  display: flex;
  flex-direction: column;
  gap: 0.95rem;
  padding: 1rem 1.05rem 1.1rem;
  border-radius: 18px;
  border: 1px solid rgba(255, 122, 0, 0.45);
  background:
    linear-gradient(180deg, rgba(255, 122, 0, 0.08) 0%, rgba(18, 18, 20, 0.92) 42%),
    #121214;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.28);
}

.staff-id-card__brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding-bottom: 0.8rem;
  border-bottom: 1px solid rgba(255, 122, 0, 0.22);
}

.staff-id-card__logo {
  width: 2.75rem;
  height: 2.75rem;
  object-fit: contain;
  flex-shrink: 0;
  border-radius: 10px;
  background: #fff;
  padding: 0.2rem;
}

.staff-id-card__brand-copy {
  min-width: 0;
}

.staff-id-card__trade {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #ff7a00;
}

.staff-id-card__firm {
  margin: 0.12rem 0 0;
  font-size: 0.92rem;
  font-weight: 750;
  color: #f8fafc;
  line-height: 1.25;
}

.staff-id-card__identity {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.staff-id-card__photo,
.staff-id-card__photo--placeholder {
  width: 4.4rem;
  height: 4.4rem;
  flex-shrink: 0;
  border-radius: 14px;
  object-fit: cover;
}

.staff-id-card__photo--placeholder {
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.06);
  color: #94a3b8;
}

.staff-id-card__who {
  min-width: 0;
}

.staff-id-card__name {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 800;
  color: #fff;
  line-height: 1.2;
}

.staff-id-card__badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.4rem;
}

.staff-id-card__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.7rem 0.85rem;
  margin: 0;
}

.staff-id-card__field {
  min-width: 0;
}

.staff-id-card__field dt {
  margin: 0 0 0.18rem;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #94a3b8;
}

.staff-id-card__field dd {
  margin: 0;
  font-size: 0.88rem;
  font-weight: 650;
  color: #f1f5f9;
  word-break: break-word;
}

.staff-id-card__field a {
  color: inherit;
  text-decoration: none;
}

.staff-id-card__field a:hover {
  color: #ff7a00;
}

@media (max-width: 640px) {
  .dealer-profile {
    gap: 0.8rem;
    padding: 0.9rem 0.9rem 1rem;
  }

  .dealer-profile__addresses {
    grid-template-columns: 1fr;
  }

  .dealer-profile__address--editing {
    grid-column: 1 / -1;
  }

  .dealer-profile__map iframe {
    height: 9.25rem;
  }

  .staff-id-card__grid {
    grid-template-columns: 1fr;
  }
}


.main-content {
  flex: 1;
  margin-left: var(--sidebar-width);
  min-height: 100vh;
  min-width: 0;
  padding-top: var(--header-height);
  transition: var(--transition-smooth);
}

.main-content:has(.dealer-dashboard),
.main-content:has(.sales-map-page) {
  overscroll-behavior-x: none;
}

.main-content.expanded { margin-left: var(--sidebar-collapsed); }

.top-bar {
  position: fixed;
  top: 0;
  left: var(--sidebar-width);
  right: 0;
  height: var(--header-height);
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0 1.5rem;
  z-index: 40;
  border-radius: 0;
  border-top: none;
  border-left: none;
  border-right: none;
  background: var(--bg-app);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.2);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  transition: var(--transition-smooth);
}

.main-content.expanded .top-bar {
  left: var(--sidebar-collapsed);
}

.page-title {
  font-size: 1.35rem;
  font-weight: 600;
  flex: 1;
  min-width: 0;
  margin: 0;
  line-height: 1.15;
}

.top-bar__title-block {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  gap: 0.1rem;
}

.top-bar__title-block--with-meta {
  flex-direction: row;
  align-items: stretch;
  gap: 0.5rem;
  min-height: 2.25rem;
}

.top-bar__title-block .page-title {
  flex: none;
  width: auto;
  display: block;
  font-size: inherit;
  line-height: 1;
  margin: 0;
}

.top-bar__title-block.page-title--nav-back {
  text-align: left;
}

.page-title__copy {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  gap: 0.08rem;
}

.page-title__heading {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 0.5rem;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  line-height: 1;
}

.page-title__text {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 1.35rem;
  font-weight: 600;
  line-height: 1.2;
  min-width: 0;
  max-width: 100%;
}

.page-title__text--accent {
  color: var(--accent-primary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 700;
}

.page-title__meta {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: stretch;
  gap: 0.2rem;
  flex: 0 0 auto;
  align-self: stretch;
  min-width: 4.75rem;
}

.page-title__meta:has(.page-title__salesperson) {
  flex-direction: row;
  align-items: center;
  align-self: flex-start;
  min-width: 0;
  padding-top: 0.2rem;
}

.page-title__meta .invoices-category,
.page-title__meta .invoices-status {
  flex: 1 1 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  min-height: 0;
  width: 100%;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  padding: 0.15rem 0.55rem;
  line-height: 1;
  border-radius: 0.4rem;
}

.page-title__below {
  display: flex;
  align-items: center;
  margin-top: 0.12rem;
  min-width: 0;
  max-width: 100%;
}

.page-title__salesperson {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.22rem;
  width: auto;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  margin: 0;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.03em;
  padding: 0.16rem 0.5rem;
  line-height: 1.15;
  border-radius: 999px;
  text-transform: uppercase;
  color: #93c5fd;
  background: rgba(59, 130, 246, 0.12);
  border: 1px solid rgba(59, 130, 246, 0.28);
  cursor: pointer;
}

.page-title__salesperson span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.page-title__salesperson.is-missing {
  color: #fca5a5;
  background: rgba(127, 29, 29, 0.32);
  border-color: rgba(248, 113, 113, 0.4);
}

.page-title__salesperson.is-open {
  color: #fff;
  background: rgba(59, 130, 246, 0.32);
  border-color: rgba(96, 165, 250, 0.55);
}

@media (max-width: 768px) {
  .page-title__text {
    font-size: 1.1rem;
  }

  .top-bar__primary:has(.top-bar__back-btn) {
    gap: 0.45rem;
  }

  .top-bar__title-block--with-meta {
    gap: 0.4rem;
    min-height: 2.35rem;
  }

  .page-title__meta {
    min-width: 4.5rem;
    gap: 0.16rem;
  }

  .page-title__meta .invoices-category,
  .page-title__meta .invoices-status {
    font-size: 0.58rem;
    padding: 0.12rem 0.45rem;
  }

  .top-bar:has(.page-subtitle) .page-title__copy {
    gap: 0.04rem;
  }
}

.page-subtitle {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-muted);
  line-height: 1.2;
}

.page-title--nav-back {
  margin: 0;
  padding: 0;
  border: none;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.page-title--nav-back:hover {
  color: var(--accent);
}

.page-title--nav-back:active {
  opacity: 0.85;
}

.top-bar__back-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 2.25rem;
  height: 2.25rem;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: rgba(245, 130, 32, 0.12);
  color: var(--accent-primary-light);
  cursor: pointer;
}

.top-bar__back-btn:hover {
  background: rgba(245, 130, 32, 0.22);
  color: var(--accent-primary);
}

.top-bar__action-btn {
  flex-shrink: 0;
  margin-left: auto;
  padding: 0.45rem 0.9rem;
  border: none;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-muted);
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1;
  cursor: pointer;
  transition: var(--transition-smooth);
}

.top-bar__action-btn--primary {
  color: var(--accent-primary-light);
  background: rgba(245, 130, 32, 0.12);
}

.top-bar__action-btn--primary:hover:not(:disabled) {
  background: rgba(245, 130, 32, 0.22);
  color: var(--accent-primary);
}

.top-bar__action-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.top-bar:has(.mobile-menu-btn):has(.top-bar__back-btn) {
  gap: 0.35rem;
}

.top-bar__primary {
  display: flex;
  align-items: center;
  gap: 1rem;
  width: 100%;
  min-width: 0;
}

.top-bar__trailing {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  margin-left: auto;
  flex-shrink: 0;
}

.top-bar-period {
  position: relative;
  flex-shrink: 0;
}

.top-bar-period__trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  max-width: 12.5rem;
  padding: 0.4rem 0.65rem;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.55);
  color: var(--text-primary);
  font-size: 0.78rem;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
}

.top-bar-period__trigger:hover,
.top-bar-period.is-open .top-bar-period__trigger {
  border-color: rgba(245, 130, 32, 0.5);
  color: #fdba74;
}

.top-bar-period__value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.top-bar-period__chevron {
  flex-shrink: 0;
  opacity: 0.8;
}

.top-bar-period.is-open .top-bar-period__chevron {
  transform: rotate(180deg);
}

.top-bar-period__menu-label {
  margin: 0 0.75rem 0.35rem;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted, #94a3b8);
}

.top-bar-period__list {
  list-style: none;
  margin: 0;
  padding: 0.15rem 0;
}

.top-bar-period__custom {
  display: grid;
  gap: 0.55rem;
  padding: 0.5rem 0.75rem 0.65rem;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
}

.top-bar-period__range {
  margin: 0;
  padding: 0.45rem 0.75rem 0.7rem;
  font-size: 0.72rem;
  color: var(--text-muted, #94a3b8);
}

.top-bar__version-group {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.top-bar__sync-btn {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 1px solid var(--accent-primary);
  border-radius: 999px;
  background: var(--accent-primary);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.top-bar__sync-btn:hover:not(:disabled) {
  color: #fff;
  border-color: var(--accent-primary-hover, #ff9a3d);
  background: var(--accent-primary-hover, #ff9a3d);
}

.top-bar__sync-btn:disabled {
  opacity: 0.7;
  cursor: wait;
}

.top-bar__version {
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(248, 250, 252, 0.95);
  line-height: 1;
  white-space: nowrap;
  user-select: all;
}

.top-bar--with-slot {
  flex-direction: column;
  align-items: stretch;
  height: auto;
  min-height: var(--header-height);
  gap: 0.35rem;
}

.top-bar--with-slot .top-bar__primary {
  gap: 0.5rem;
  min-height: 2.25rem;
}

.top-bar--compact-search {
  flex-direction: row;
  align-items: center;
  height: auto;
  min-height: 52px;
  padding-top: 0.32rem;
  padding-bottom: 0.32rem;
  gap: 0.4rem;
  overflow: hidden;
}

.top-bar--compact-search .top-bar__primary {
  flex: 1;
  width: 100%;
  min-width: 0;
  gap: 0.4rem;
  overflow: hidden;
}

.top-bar--compact-search .top-bar__slot--compact {
  flex: 1 1 0;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
}

.top-bar--compact-search .catalog-search,
.top-bar--compact-search .invoices-header-search {
  min-width: 0;
  width: 100%;
  max-width: 100%;
  padding: 0.38rem 0.55rem;
  box-sizing: border-box;
}

.top-bar--compact-search .invoices-header-search input,
.top-bar--compact-search .catalog-search input {
  font-size: 0.8125rem;
  min-width: 0;
  width: 100%;
}

.top-bar--compact-search .invoices-header-tools {
  width: 100%;
  min-width: 0;
}

/* Invoices: search + filter replace the page title in the top bar. */
.top-bar:has(.invoices-header-tools) .top-bar__title-block {
  display: none;
}

.top-bar:has(.dealers-header-tools) .top-bar__slot--inline {
  flex: 1 1 auto;
  min-width: 0;
  max-width: none;
}

.top-bar:has(.dealers-header-tools) .top-bar__primary {
  gap: 0.45rem;
}

.top-bar:has(.invoices-header-tools) .top-bar__slot--inline {
  flex: 1 1 auto;
  min-width: 0;
  max-width: none;
}

.top-bar:has(.invoices-header-tools) .top-bar__primary {
  gap: 0.45rem;
}

.top-bar--compact-search .catalog-header-actions {
  flex: 0 0 auto;
  gap: 0.28rem;
}

.top-bar--compact-search .catalog-header-filter-btn {
  width: 2.15rem;
  height: 2.15rem;
}

.catalog-header-filter-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 2.35rem;
  height: 2.35rem;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-main, #fff);
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
  position: relative;
}

.catalog-header-filter-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.18);
}

.catalog-header-filter-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.catalog-header-filter-btn:has(.support-request-list__filter-pill)::after {
  display: none;
}

.catalog-header-filter-btn .support-request-list__filter-pill {
  position: absolute;
  top: -0.2rem;
  right: -0.2rem;
  min-width: 0.95rem;
  height: 0.95rem;
  padding: 0 0.2rem;
  font-size: 0.58rem;
  line-height: 0.95rem;
}

.catalog-header-filter-btn--open,
.catalog-header-filter-btn--active {
  border-color: rgba(245, 130, 32, 0.55);
  background: rgba(245, 130, 32, 0.14);
  color: var(--accent-primary-light);
}

.catalog-header-filter-btn--active:not(.catalog-header-filter-btn--open)::after {
  content: '';
  position: absolute;
  top: 0.32rem;
  right: 0.32rem;
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 999px;
  background: var(--accent-primary);
}

.catalog-header-actions {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  flex-shrink: 0;
}

.catalog-header-filter-btn--pressed {
  border-color: rgba(245, 130, 32, 0.55);
  background: rgba(245, 130, 32, 0.14);
  color: var(--accent-primary-light);
}

/* Spare parts rack view (location-first) */
.spare-parts-rack-view {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0.15rem 0 1rem;
}

.spare-parts-rack-view__empty {
  margin: 0.75rem 0 0;
  font-size: 0.875rem;
}

.spare-rack-label-filter {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  min-width: 0;
}

.spare-rack-label-filter__chips {
  display: flex;
  flex: 1;
  flex-wrap: wrap;
  gap: 0.4rem;
  min-width: 0;
}

.spare-rack-label-filter__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0;
  padding: 0.35rem 0.65rem;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: #161b22;
  color: #94a3b8;
  font: inherit;
  font-size: 0.6875rem;
  font-weight: 750;
  cursor: pointer;
  transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}

.spare-rack-label-filter__chip:hover {
  color: #e2e8f0;
  border-color: rgba(148, 163, 184, 0.45);
}

.spare-rack-label-filter__chip--needs.is-active {
  color: #facc15;
  border-color: rgba(250, 204, 21, 0.65);
  background: rgba(250, 204, 21, 0.1);
}

.spare-rack-label-filter__chip--printed.is-active {
  color: #4ade80;
  border-color: rgba(74, 222, 128, 0.65);
  background: rgba(74, 222, 128, 0.1);
}

.spare-rack-label-filter__count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.25rem;
  padding: 0.05rem 0.35rem;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.18);
  color: inherit;
  font-size: 0.625rem;
  font-weight: 800;
}

/* Rack letter selector */
.spare-rack-selector {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  min-width: 0;
}

.spare-rack-selector__label {
  flex-shrink: 0;
  font-size: 0.6875rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #f8fafc;
}

.spare-rack-selector__chips {
  display: flex;
  flex: 1;
  flex-wrap: nowrap;
  gap: 0.4rem;
  min-width: 0;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0.15rem 0.05rem;
}

.spare-rack-selector__chips::-webkit-scrollbar {
  display: none;
}

.spare-rack-selector__chip {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.35rem;
  height: 2.35rem;
  margin: 0;
  padding: 0;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: #161b22;
  color: #94a3b8;
  font: inherit;
  font-size: 0.8125rem;
  font-weight: 700;
  cursor: pointer;
  transition: color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.spare-rack-selector__chip:hover {
  color: #e2e8f0;
  border-color: rgba(148, 163, 184, 0.4);
}

.spare-rack-selector__chip.is-active {
  color: #f58220;
  border-color: #f58220;
  background: rgba(245, 130, 32, 0.08);
  box-shadow: 0 0 0 2px rgba(245, 130, 32, 0.22);
}

.spare-rack-selector__more {
  flex-shrink: 0;
  display: inline-flex;
  color: #64748b;
}

/* Mobile carousel */
.spare-parts-rack-view__carousel {
  display: flex;
  flex-flow: row nowrap;
  overflow-x: auto;
  overflow-y: visible;
  scroll-snap-type: x mandatory;
  scroll-behavior: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
  margin: 0 -0.5rem;
  padding: 0;
}

.spare-parts-rack-view__carousel::-webkit-scrollbar {
  display: none;
}

.spare-parts-rack-view__carousel-page {
  flex: 0 0 100%;
  width: 100%;
  min-width: 100%;
  max-width: 100%;
  box-sizing: border-box;
  scroll-snap-align: start;
  scroll-snap-stop: always;
  padding: 0 0.5rem;
}

.spare-parts-rack-view__desktop {
  display: none;
}

.spare-rack-rows {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.spare-rack-row {
  position: relative;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 14px;
  background: linear-gradient(180deg, #141b27 0%, #0f1520 100%);
  padding: 0.7rem 0.75rem 0.8rem;
  overflow: hidden;
}

.spare-rack-row::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.7rem;
  bottom: 0.7rem;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: #3b82f6;
}

.spare-rack-row--blue::before { background: #3b82f6; }
.spare-rack-row--green::before { background: #22c55e; }
.spare-rack-row--amber::before { background: #f59e0b; }
.spare-rack-row--cyan::before { background: #06b6d4; }

.spare-rack-row--empty {
  border-style: dashed;
  border-color: rgba(248, 113, 113, 0.38);
  background: rgba(127, 29, 29, 0.18);
  box-shadow: inset 0 -12px 22px -16px rgba(248, 113, 113, 0.22);
}

.spare-rack-row--empty::before {
  background: #f87171;
}

.spare-rack-row--empty .spare-rack-row__title {
  color: #fca5a5;
}

.spare-rack-row--empty .spare-rack-row__icon {
  color: #f87171;
}

.spare-rack-row--empty .spare-rack-row__meta {
  color: #fca5a5;
}

.spare-rack-row__empty-body {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  padding: 0.15rem 0.35rem 0.1rem;
  position: relative;
}

.spare-rack-row__empty-icon {
  flex-shrink: 0;
  color: #f87171;
}

.spare-rack-row__empty-label {
  flex: 1;
  min-width: 0;
  font-size: 0.75rem;
  font-weight: 600;
  color: #fca5a5;
}

.spare-rack-row__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin: 0 0 0.55rem;
  padding-left: 0.35rem;
}

.spare-rack-row__title {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.8125rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #f8fafc;
}

.spare-rack-row__icon {
  color: #60a5fa;
  flex-shrink: 0;
}

.spare-rack-row--green .spare-rack-row__icon { color: #4ade80; }
.spare-rack-row--amber .spare-rack-row__icon { color: #fbbf24; }
.spare-rack-row--cyan .spare-rack-row__icon { color: #22d3ee; }

.spare-rack-row__meta {
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #64748b;
  white-space: nowrap;
}

.spare-rack-row__cells {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.4rem;
  padding-left: 0.15rem;
}

.spare-rack-cell {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  position: relative;
  min-width: 0;
  min-height: 4.25rem;
  margin: 0;
  padding: 0.4rem 0.4rem 0.45rem;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.12);
  background: #0d121c;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: default;
  -webkit-tap-highlight-color: transparent;
  box-sizing: border-box;
}

.spare-rack-cell--wide {
  grid-column: 1 / -1;
  min-height: 0;
}

.spare-rack-cell--sku {
  cursor: pointer;
  box-shadow: inset 0 -10px 18px -14px rgba(34, 197, 94, 0.35);
}

.spare-rack-cell--sku:hover .spare-rack-cell__sku,
.spare-rack-cell--sku:active .spare-rack-cell__sku {
  color: #fff;
}

.spare-rack-cell--sku:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
}

.spare-rack-cell--sku.is-focus {
  background: rgba(56, 189, 248, 0.12);
  box-shadow:
    inset 0 -10px 18px -14px rgba(34, 197, 94, 0.28),
    0 0 0 1px rgba(56, 189, 248, 0.45);
  animation: spare-rack-sku-focus-pulse 1.6s ease-out 2;
}

.spare-rack-cell--unlinked {
  cursor: pointer;
  border-color: rgba(251, 146, 60, 0.38);
  background: rgba(251, 146, 60, 0.08);
  box-shadow: inset 0 -10px 18px -14px rgba(251, 146, 60, 0.28);
}

.spare-rack-cell--unlinked:hover .spare-rack-cell__sku--unlinked,
.spare-rack-cell--unlinked:active .spare-rack-cell__sku--unlinked {
  color: #ffedd5;
}

.spare-rack-cell--unlinked:focus-visible {
  outline: 2px solid #fb923c;
  outline-offset: 2px;
}

.spare-rack-cell--unlinked.is-focus {
  background: rgba(251, 146, 60, 0.16);
  box-shadow:
    inset 0 -10px 18px -14px rgba(251, 146, 60, 0.3),
    0 0 0 1px rgba(251, 146, 60, 0.55);
  animation: spare-rack-sku-focus-pulse 1.6s ease-out 2;
}

.spare-rack-cell__body--unlinked {
  gap: 0.4rem;
}

.spare-rack-cell__thumb {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.65rem;
  height: 1.65rem;
  border-radius: 6px;
  overflow: hidden;
  flex-shrink: 0;
  background: rgba(15, 23, 42, 0.65);
  border: 1px solid rgba(148, 163, 184, 0.25);
}

.spare-rack-cell__thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.spare-rack-cell__thumb-empty {
  font-size: 0.6rem;
  color: #64748b;
}

.spare-rack-cell__icon--unlinked {
  color: #fb923c;
}

.spare-rack-cell__sku--unlinked {
  color: #fdba74;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.spare-rack-cell--empty {
  border-style: dashed;
  border-color: rgba(248, 113, 113, 0.38);
  background: rgba(127, 29, 29, 0.18);
  box-shadow: inset 0 -10px 18px -14px rgba(248, 113, 113, 0.22);
}

.spare-rack-cell--empty .spare-rack-cell__label {
  color: #fca5a5;
}

.spare-rack-cell--empty .spare-rack-cell__icon {
  color: #f87171;
}

.spare-rack-cell--empty .spare-rack-cell__sku--empty {
  color: #fca5a5;
}

.spare-rack-cell__meta {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.spare-rack-cell__label {
  font-size: 0.5625rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #94a3b8;
}

.spare-rack-cell__dot {
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: #22c55e;
  box-shadow: 0 0 0 2px rgba(34, 197, 94, 0.18);
}

.spare-rack-cell__qty {
  margin-left: auto;
  font-size: 0.625rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #86efac;
  font-variant-numeric: tabular-nums;
}

.spare-rack-cell__body {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 0.35rem;
  min-width: 0;
  padding-right: 1rem;
}

.spare-rack-cell--wide .spare-rack-cell__body {
  padding-right: 0;
}

.spare-rack-cell__icon {
  flex-shrink: 0;
  color: #64748b;
}

.spare-rack-cell__icon--live {
  color: #4ade80;
}

.spare-rack-cell__sku {
  flex: 1;
  min-width: 0;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1.25;
  color: #f8fafc;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.spare-rack-cell--wide .spare-rack-cell__sku {
  font-size: 0.875rem;
}

.spare-rack-cell__sku--empty {
  color: #64748b;
  font-weight: 600;
}

.spare-rack-cell__sku--changed {
  color: #facc15;
}

.spare-rack-cell__sku--relabel-printed {
  color: #4ade80;
}

.spare-rack-cell--sku:hover .spare-rack-cell__sku--changed,
.spare-rack-cell--sku:active .spare-rack-cell__sku--changed {
  color: #fde047;
}

.spare-rack-cell--sku:hover .spare-rack-cell__sku--relabel-printed,
.spare-rack-cell--sku:active .spare-rack-cell__sku--relabel-printed {
  color: #86efac;
}

.spare-label-update-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 0.25rem 0.15rem 0.5rem;
}

.spare-label-update-list__section {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.spare-label-update-list__section-title {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0;
  font-size: 0.8125rem;
  font-weight: 800;
  color: #0f172a;
}

.spare-label-update-list__section-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.35rem;
  padding: 0.1rem 0.4rem;
  border-radius: 999px;
  background: #e2e8f0;
  color: #334155;
  font-size: 0.6875rem;
  font-weight: 800;
}

.spare-label-update-list__rows {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.spare-label-update-list__row {
  display: grid;
  grid-template-columns: auto minmax(4.5rem, 0.9fr) minmax(0, 1.4fr) auto;
  gap: 0.55rem 0.65rem;
  align-items: center;
  width: 100%;
  margin: 0;
