}

.catalog-page .catalog-filters--sticky {
  top: calc(var(--header-height) + var(--catalog-section-bar-height));
}

.spares-page .catalog-browse {
  padding-top: calc(var(--products-search-height) + var(--catalog-section-bar-height));
}

.catalog-page .catalog-browse {
  padding-top: calc(var(--products-search-height) + var(--catalog-section-bar-height));
}

.catalog-page.catalog-page--flat .catalog-browse {
  padding-top: calc(var(--catalog-section-bar-height) + var(--spares-all-spares-scroll-gap, 0.5rem));
}

.products-page .catalog-filters--sticky {
  position: fixed;
  top: var(--header-height);
  left: var(--sidebar-width);
  right: 0;
  z-index: 35;
