  border-radius: 10px;
  font-size: 0.88rem;
  line-height: 1.35;
}

.zoho-api-quota-banner--warn {
  color: #fde68a;
  background: rgba(245, 158, 11, 0.12);
  border: 1px solid rgba(245, 158, 11, 0.35);
}

.zoho-api-quota-banner--critical {
  color: #fecaca;
  background: rgba(239, 68, 68, 0.12);
