.products-group-card {
  padding: 1rem;
  border-radius: 16px;
  text-align: left;
}

.products-group-card-header {
  display: flex;
  align-items: flex-start;
  gap: 0.85rem;
  width: 100%;
  border: none;
  background: transparent;
  color: inherit;
  cursor: pointer;
  text-align: left;
  padding: 0;
}

.products-group-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: rgba(245, 130, 32, 0.12);
