.products-table td strong {
  font-weight: 600;
}

.spin-icon {
  animation: spin 0.8s linear infinite;
}

.stat-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1.25rem;
  border-radius: 16px;
}

.stat-icon {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  background: rgba(245, 130, 32, 0.12);
  color: var(--accent-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.stat-content h3 { font-size: 0.85rem; color: var(--text-muted); font-weight: 500; }

.stat-value { font-size: 1.75rem; font-weight: 700; line-height: 1.1; }

.config-box {
  background: rgba(0, 0, 0, 0.2);
