  padding: 0.2rem 0.65rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
}

.status-badge.active {
  background: rgba(245, 130, 32, 0.15);
  color: var(--accent-primary-light);
}

.status-badge.inactive {
  background: rgba(239, 68, 68, 0.12);
  color: #fca5a5;
}

