}

.confirm-inline-bar-content {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.confirm-dialog-title { font-size: 1rem; margin-bottom: 0.35rem; }

.confirm-dialog-message { font-size: 0.875rem; color: var(--text-muted); }

.confirm-dialog-actions { display: flex; gap: 0.5rem; }

/* -- Catalog (themed for YesOne Platform) -- */
.open-catalog-page {
  min-height: 100vh;
  padding: 0;
  display: flex;
  flex-direction: column;
}

.catalog-browse {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  flex: 1;
