@media (max-width: 768px) {
  .catalog-filters__back-btn span {
    display: none;
  }

  .catalog-filters__back-btn {
    padding: 0.5rem;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.06);
  }

  .catalog-row {
    grid-template-columns: 72px 1fr;
  }

  .catalog-row__price {
    grid-column: 1 / -1;
    justify-content: flex-end;
  }

  .open-catalog-page {
    padding: 0.75rem;
  }

  .sidebar {
    transform: translateX(-100%);
    width: max-content;
    max-width: 88vw;
    align-items: stretch;
    inset: 0 auto 0 0;
    height: 100dvh;
    max-height: 100dvh;
    padding-bottom: env(safe-area-inset-bottom, 0px);
    background: #0a0f1c;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    transition: transform 0.22s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .sidebar.mobile-open { transform: translateX(0); }

  .sidebar--mobile .sidebar-header {
    height: auto;
    min-height: 0;
    padding: 0.2rem 0.3rem 0;
    border-bottom: none;
    flex-shrink: 0;
  }

  .sidebar--mobile .logo-text {
    font-size: 1rem;
    letter-spacing: 0.04em;
  }

  .sidebar--mobile .brand-logo {
    transform: translateY(-4px);
  }

  .sidebar--mobile .nav-menu {
    --nav-item-min-h: 1.9rem;
    --nav-item-max-h: none;
    flex: 1 1 auto;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 0.2rem 0.6rem 0.3rem;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 0.12rem;
  }

  .sidebar--mobile .nav-item {
    gap: 0.65rem;
    width: 100%;
    padding: 0.36rem 0.75rem;
    border-radius: 8px;
    font-size: 0.9375rem;
    line-height: 1.25;
    white-space: nowrap;
  }

  .sidebar--mobile .nav-label {
    white-space: nowrap;
  }

  .sidebar--mobile .nav-icon {
    display: inline-flex;
    flex-shrink: 0;
    width: 18px;
    height: 18px;
  }

  .sidebar--mobile .nav-icon svg {
    width: 18px;
    height: 18px;
  }

  .sidebar--mobile .nav-item.active {
    border-left-width: 2px;
  }

  .sidebar--mobile .sidebar-profile {
    padding: 0.35rem 0.6rem 0.5rem;
  }

  .main-content,
  .main-content.expanded {
    margin-left: 0;
    width: 100%;
    max-width: 100%;
    overflow-x: hidden;
  }

  /* Nested category pager needs a non-hidden overflow ancestor to accept horizontal swipes. */
  .main-content:has(.catalog-category-pager),
  .main-content.expanded:has(.catalog-category-pager) {
    overflow-x: visible;
  }

  .top-bar,
  .main-content.expanded .top-bar {
    left: 0;
  }

  .main-content:has(.spares-page),
  .main-content:has(.catalog-page) {
    --header-height: 58px;
  }

  .content-area { padding: 1rem; }

  .content-area:has(.dealers-detail-page) {
    padding: 0.3rem 0.55rem 0.7rem;
  }

  .content-area:has(.support-detail-page--chat) {
    padding: 0;
