/* Amazon / Flipkart style product detail page */
.product-detail-page-wrap {
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.product-detail-page {
  width: 100%;
  max-width: 1080px;
  margin: 0 auto;
}

.product-detail-page__back {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0 0 0.85rem;
  padding: 0.35rem 0;
  border: none;
  background: transparent;
  color: var(--accent-primary-light);
  font-size: 0.875rem;
  font-weight: 700;
  cursor: pointer;
}

.product-detail-page__back:hover {
  color: var(--accent-primary);
  text-decoration: underline;
}

.product-detail-page__layout {
  display: flex;
  flex-direction: column;
  gap: 0;
  background: #ffffff;
  color: #0f172a;
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
}

.product-detail-page__hero {
  display: flex;
  flex-direction: column;
  gap: 0;
  background: transparent;
}

.product-detail-page__gallery {
  background: #ffffff;
  min-width: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
}

.product-detail-page__basics {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  min-width: 0;
  padding: 0.85rem 1.1rem 0.95rem;
  background: transparent;
}

.product-detail-page__main {
  padding: 0.65rem 0.85rem 1.15rem;
}

.product-detail-page__tabbed-area {
  margin-top: 1rem;
  padding-top: 1rem;
  border-top: 1px solid #e2e8f0;
  min-width: 0;
}

.product-detail-page__tabbed-area .product-detail-tabs {
  margin-top: 0.85rem;
}

.product-detail-page__tabbed-area .product-detail-page__package-info {
  margin-top: 0;
}

.product-media-panel {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.product-media-panel--embedded {
  margin: 0;
}

.product-media-panel__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.product-media-panel__title {
  margin: 0;
  font-size: 1rem;
  font-weight: 650;
  color: #0f172a;
}

.product-media-panel__subtitle {
  margin: 0.2rem 0 0;
}

.product-media-panel__head-actions {
  display: flex;
  gap: 0.4rem;
  flex-shrink: 0;
}

.product-media-panel__upload-compose {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 0.75rem 0.8rem;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #f8fafc;
}

.product-media-panel__upload-file-row {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  flex-wrap: wrap;
}

.product-media-panel__pending-file {
  margin: 0;
  color: #0f172a;
  font-weight: 600;
  min-width: 0;
  word-break: break-word;
}

.product-media-panel__caption-edit {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin-top: 0.35rem;
}

.product-media-panel__error {
  margin: 0;
  color: #b91c1c;
}

.product-media-panel__section {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.product-media-panel__section-head {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.product-media-panel__add-btn {
  margin-left: auto;
  width: 2rem;
  height: 2rem;
  padding: 0;
  border-radius: 999px;
  border: 1px solid #e2e8f0;
  background: #fff;
  color: #0f172a;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.product-media-panel__add-btn:hover {
  border-color: #fdba74;
  color: var(--accent-primary);
}

.product-media-panel__add-btn.is-active {
  border-color: var(--accent-primary);
  background: rgba(245, 130, 32, 0.1);
  color: var(--accent-primary);
}

.product-media-panel__section-head h4 {
  margin: 0;
  font-size: 0.92rem;
  font-weight: 650;
  color: #334155;
}

.product-media-panel__section-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.35rem;
  height: 1.35rem;
  padding: 0 0.35rem;
  border-radius: 999px;
