.unified-so-stage-blocks {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.3rem;
  width: 100%;
  margin: 0 0 0.45rem;
  padding: 0.3rem;
  border-radius: 0.85rem;
  background: rgba(245, 158, 66, 0.06);
  border: 1px solid rgba(245, 158, 66, 0.14);
}

.unified-so-stage-block {
  overflow: visible;
  background: rgba(17, 24, 39, 0.55);
  border-color: rgba(245, 158, 66, 0.16);
}

.unified-so-stage-block:hover {
  border-color: rgba(251, 191, 36, 0.55);
  background: rgba(245, 158, 66, 0.1);
}

.unified-so-stage-block.is-active {
  border-color: rgba(251, 191, 36, 0.85);
  background: linear-gradient(
    180deg,
    rgba(251, 191, 36, 0.28) 0%,
    rgba(245, 130, 32, 0.16) 100%
  );
  box-shadow: inset 0 0 0 1px rgba(251, 191, 36, 0.2);
