.unified-so-stage-block__icon--all {
  background: rgba(148, 163, 184, 0.16);
  color: #94a3b8;
}

.unified-so-stage-block__icon--review {
  background: rgba(251, 191, 36, 0.18);
  color: #fbbf24;
}

.unified-so-stage-block__icon--ready_for_payment {
