.dealer-order-detail section h3 {
  margin: 0 0 0.55rem;
  font-size: 0.95rem;
}

.dealer-order-detail__history {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.dealer-order-detail__history li {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.dealer-order-detail__diff-summary {
  margin: 0 0 0.75rem;
  font-size: 0.8125rem;
  font-weight: 700;
  color: #fdba74;
}

.dealer-order-detail__lines {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.dealer-order-detail__line {
  display: grid;
  grid-template-columns: 44px 1fr auto auto;
  gap: 0.65rem;
  align-items: center;
  padding: 0.55rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.dealer-order-detail__line--added {
  background: rgba(34, 197, 94, 0.08);
  border-radius: 0.5rem;
  padding-inline: 0.4rem;
}

.dealer-order-detail__line--removed {
  opacity: 0.55;
  text-decoration: line-through;
}

.dealer-order-detail__line--qty_changed {
  background: rgba(56, 189, 248, 0.08);
  border-radius: 0.5rem;
  padding-inline: 0.4rem;
}

.dealer-order-detail__line-icon {
  width: 44px;
  height: 44px;
  border-radius: 0.5rem;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-muted);
}

.dealer-order-detail__line-icon img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.dealer-order-detail__line-body {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  min-width: 0;
}

.dealer-order-detail__removed {
  margin-top: 0.75rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.dealer-order-detail__payment,
.dealer-order-detail__timeline,
.dealer-order-detail__diff {
  padding: 1rem;
}

.dealer-order-detail__proof {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.55rem;
  margin: 0.75rem 0;
}

.dealer-order-detail__proof img {
  max-width: min(100%, 320px);
  border-radius: 0.65rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.dealer-order-detail__field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin: 0.75rem 0;
  font-size: 0.8125rem;
  font-weight: 600;
}

.dealer-order-detail__field input,
.dealer-order-detail__field textarea {
  width: 100%;
  box-sizing: border-box;
  border-radius: 0.55rem;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(0, 0, 0, 0.25);
  color: inherit;
  padding: 0.55rem 0.7rem;
  font: inherit;
}

.dealer-order-detail__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  margin-top: 0.25rem;
}

.dealer-order-picker {
  max-width: min(100vw - 1.5rem, 28rem);
}

.dealer-order-picker__search {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.45rem 0.65rem;
  border-radius: 0.55rem;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(0, 0, 0, 0.25);
}

.dealer-order-picker__search input {
  flex: 1;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  outline: none;
}

.dealer-order-picker__list {
  list-style: none;
  margin: 0.75rem 0 0;
  padding: 0;
  max-height: 50vh;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.dealer-order-picker__list button {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.65rem 0.7rem;
  border-radius: 0.55rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.dealer-order-picker__list button span {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}

/* -- Dealer dashboard ----------------------------------------- */
.dealer-dashboard {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  max-width: 1280px;
  margin: 0 auto;
  min-height: 100%;
  touch-action: pan-y;
  transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.dealer-dashboard.is-swiping {
  touch-action: none;
  transition: none;
}

.dealer-dash__hero {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem 1.25rem;
}

.dealer-dash__eyebrow {
  margin: 0 0 0.35rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent-primary-light);
}

.dealer-dash__title {
  margin: 0;
  font-size: clamp(1.35rem, 4vw, 1.75rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.2;
}

.dealer-dash__wave {
  margin-left: 0.25rem;
}

.dealer-dash__subtitle {
  margin: 0.45rem 0 0;
  max-width: 36rem;
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.dealer-dash__date-pill,
.dealer-dash__select-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 0.85rem;
  border-radius: 999px;
  border: 1px solid var(--border-glass);
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-secondary);
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: var(--transition-smooth);
}

.dealer-dash__range-tile {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  width: 100%;
  max-width: 20rem;
  padding: 0.85rem 1rem !important;
  border-radius: 16px;
  overflow: visible;
}

.dealer-dash__range-tile::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: var(--accent-primary);
  border-radius: 16px 0 0 16px;
}

.dealer-dash__range-icon {
  flex-shrink: 0;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(245, 130, 32, 0.14);
  color: var(--accent-primary-light);
}

.dealer-dash__range-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.dealer-dash__range-label {
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.dealer-dash-range-select {
  position: relative;
  width: 100%;
}

.dealer-dash-range-select__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.55rem 0.75rem;
  border-radius: 12px;
  border: 1px solid var(--border-glass);
  background: rgba(0, 0, 0, 0.28);
  color: var(--text-primary);
  font-size: 0.8125rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.dealer-dash-range-select__trigger:hover {
  border-color: rgba(245, 130, 32, 0.4);
  background: rgba(0, 0, 0, 0.34);
}

.dealer-dash-range-select--open .dealer-dash-range-select__trigger {
  border-color: rgba(245, 130, 32, 0.55);
  box-shadow: 0 0 0 3px rgba(245, 130, 32, 0.14);
}

.dealer-dash-range-select__trigger:focus-visible {
  outline: none;
  border-color: var(--accent-primary);
  box-shadow: 0 0 0 3px rgba(245, 130, 32, 0.22);
}

.dealer-dash-range-select__value {
  flex: 1;
  min-width: 0;
  text-align: left;
}

.dealer-dash-range-select__chevron {
  flex-shrink: 0;
  color: var(--accent-primary-light);
  transition: transform 0.2s ease;
}

.dealer-dash-range-select--open .dealer-dash-range-select__chevron {
  transform: rotate(180deg);
}

.dealer-dash-range-select__menu {
  list-style: none;
  margin: 0;
  padding: 0.35rem !important;
  border-radius: 14px;
  border: 1px solid rgba(245, 130, 32, 0.22);
  background: linear-gradient(160deg, rgba(17, 24, 39, 0.98), rgba(15, 23, 42, 0.96));
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.48);
  backdrop-filter: blur(16px);
  animation: dealer-dash-range-fade-in 0.16s ease;
}

.dealer-dash-range-select__menu--portal {
  overflow: visible;
}

@keyframes dealer-dash-range-fade-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.dealer-dash-range-select__option {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  min-height: 44px;
  padding: 0.7rem 0.85rem;
  border: none;
  border-radius: 10px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 0.8125rem;
  font-weight: 600;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 0.12s ease, color 0.12s ease;
}

.dealer-dash-range-select__option:hover {
  background: rgba(245, 130, 32, 0.1);
  color: var(--text-primary);
}

.dealer-dash-range-select__option.is-active {
  background: rgba(245, 130, 32, 0.18);
  color: var(--accent-primary-light);
}

.dealer-dash-range-select__option.is-active::before {
  content: '';
  flex-shrink: 0;
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 999px;
  background: var(--accent-primary);
}

.dealer-dash__range-custom {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.dealer-dash__range-date.catalog-select {
  flex: 1;
  min-width: 0;
  width: auto;
  padding: 0.45rem 0.55rem;
  font-size: 0.75rem;
  font-weight: 600;
  color-scheme: dark;
}

.dealer-dash__range-date::-webkit-calendar-picker-indicator {
  filter: invert(0.75) sepia(0.4) saturate(4) hue-rotate(350deg);
  cursor: pointer;
  opacity: 0.85;
}

.dealer-dash__range-sep {
  flex-shrink: 0;
  color: var(--text-muted);
  font-size: 0.75rem;
  font-weight: 600;
}

.dealer-dash__range-display {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent-primary-light);
  line-height: 1.35;
}

@media (max-width: 767px) {
  .dealer-dash__hero {
    flex-direction: column;
  }

  .dealer-dash__range-tile {
    max-width: none;
  }
}

.dealer-dash__date-pill:hover,
.dealer-dash__select-pill:hover {
  border-color: rgba(245, 130, 32, 0.35);
  color: var(--text-primary);
}

.dealer-dash-period-panel {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.dealer-dash-period {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 0.75rem 0.85rem;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.16);
  background: rgba(15, 23, 42, 0.28);
}

.dealer-dash-period__row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.55rem 0.75rem;
}

.dealer-dash-period__label {
  margin: 0;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--text-muted, #94a3b8);
}

.dealer-dash-period__options {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.dealer-dash-period__option {
  padding: 0.4rem 0.7rem;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  background: transparent;
  color: var(--text-muted, #94a3b8);
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
}

.dealer-dash-period__option:hover {
  color: #fdba74;
  border-color: rgba(245, 130, 32, 0.35);
}

.dealer-dash-period__option.is-active {
  background: rgba(245, 130, 32, 0.16);
  border-color: transparent;
  color: #fdba74;
}

.dealer-dash-period__custom {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.dealer-dash-period__date {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 9.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted, #94a3b8);
}

.dealer-dash-period__date input {
  padding: 0.4rem 0.55rem;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.45);
  color: inherit;
  font: inherit;
  font-weight: 600;
}

.dealer-dash-period__range {
  margin: 0;
}

.dealer-dash__kpis-layout {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.dealer-dash__kpis-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.dealer-dash__kpis-grid--four,
.dealer-dash__kpis-grid--pairs,
.dealer-dash__kpis-grid--dealer-stages {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.dealer-dash-kpi--featured {
  --featured-metric-size: clamp(2.25rem, 11vw, 2.75rem);
  --featured-price-size: calc(var(--featured-metric-size) * 1.5);
  padding: 1.15rem 1rem;
  cursor: default;
  align-items: center;
  gap: 0.5rem 0.65rem;
}

.dealer-dash-kpi__featured-main {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
  flex: 1;
}

.dealer-dash-kpi__body--featured {
  gap: 0.2rem;
}

.dealer-dash-kpi__period {
  display: block;
  font-weight: 600;
}

.dealer-dash-kpi--featured .dealer-dash-range-select {
  max-width: 10.5rem;
}

.dealer-dash-kpi--featured .dealer-dash-range-select__trigger {
  padding: 0.35rem 0.55rem;
  font-size: 0.75rem;
  border-radius: 8px;
}

.dealer-dash-kpi--featured .dealer-dash-kpi__icon {
  width: var(--featured-metric-size);
  height: var(--featured-metric-size);
  border-radius: calc(var(--featured-metric-size) * 0.5);
}

.dealer-dash-kpi--featured .dealer-dash-kpi__icon svg {
  width: calc(var(--featured-metric-size) * 0.58);
  height: calc(var(--featured-metric-size) * 0.58);
}

.dealer-dash-kpi__value--featured {
  margin-left: auto;
  flex-shrink: 1;
  min-width: 0;
  font-size: clamp(1.85rem, 14vw, var(--featured-price-size));
  letter-spacing: -0.03em;
  line-height: 1;
  font-weight: 800;
  text-align: right;
}

.dealer-dash__kpis {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.dealer-dash-kpi {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  width: 100%;
  padding: 1rem 0.85rem;
  border-radius: 16px;
  border: 1px solid var(--border-glass);
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02));
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.dealer-dash-kpi::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: var(--kpi-accent, var(--accent-primary));
  border-radius: 16px 0 0 16px;
}

.dealer-dash-kpi:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.22);
  border-color: color-mix(in srgb, var(--kpi-accent, var(--accent-primary)) 35%, transparent);
}

.dealer-dash-kpi--blue { --kpi-accent: #3b82f6; }
.dealer-dash-kpi--green { --kpi-accent: #10b981; }
.dealer-dash-kpi--red { --kpi-accent: #ef4444; }
.dealer-dash-kpi--orange { --kpi-accent: #f58220; }
.dealer-dash-kpi--purple { --kpi-accent: #a855f7; }

.dealer-dash-kpi__icon {
  flex-shrink: 0;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--kpi-accent) 16%, transparent);
  color: var(--kpi-accent);
}

.dealer-dash-kpi__body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.dealer-dash-kpi__label {
  font-size: 0.6875rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.dealer-dash-kpi__value {
  font-size: clamp(1rem, 3.5vw, 1.35rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  line-height: 1.15;
}

.dealer-dash-kpi__trend {
  display: inline-flex;
  align-items: center;
  gap: 0.15rem;
  font-size: 0.625rem;
  font-weight: 700;
}

.dealer-dash-kpi__trend--up { color: #6ee7b7; }
.dealer-dash-kpi__trend--down { color: #fca5a5; }

.dealer-dash-kpi__chevron {
  flex-shrink: 0;
  color: var(--text-muted);
  opacity: 0.7;
}

.dealer-dash-kpi__chevron-btn {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.25rem;
  margin: 0;
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  opacity: 0.7;
  transition: opacity 0.15s ease, color 0.15s ease;
}

.dealer-dash-kpi__chevron-btn:hover {
  opacity: 1;
  color: var(--text-primary);
}

.dealer-dash-kpi--kotak-tile {
  --kpi-accent: #ed1c24;
  overflow: visible;
}

.dealer-dash-kpi--kotak-tile:disabled {
  cursor: wait;
  opacity: 0.85;
}

.dealer-dash-kpi--kotak-tile.is-ok {
  --kpi-accent: #059669;
}

.dealer-dash-kpi--kotak-tile.is-fail {
  --kpi-accent: #ef4444;
}

.dealer-dash-kpi__kotak-logo-wrap {
  position: relative;
  flex-shrink: 0;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 14px;
  overflow: visible;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #ed1c24;
  color: #fff;
}

.dealer-dash-kpi--kotak-tile.is-ok .dealer-dash-kpi__kotak-logo-wrap {
  background: #059669;
}

.dealer-dash-kpi__kotak-logo {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: 14px;
}

.dealer-dash-kpi__kotak-badge {
  position: absolute;
  top: -0.32rem;
  right: -0.38rem;
  z-index: 1;
  min-width: 1.15rem;
  height: 1.15rem;
  padding: 0 0.28rem;
  border-radius: 999px;
  background: #ed1c24;
  color: #fff;
  font-size: 0.62rem;
  font-weight: 800;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 0 2px rgba(10, 15, 28, 0.95);
}

.dealer-dash-kpi__value--sub {
  font-size: 0.92rem;
  font-weight: 700;
}

.dealer-dash__kotak-status {
  margin: 0;
  font-size: 0.75rem;
  color: var(--text-muted);
}

.dealer-dash__kotak-status.is-ok {
  color: #6ee7b7;
}

.dealer-dash__kotak-status.is-fail {
  color: #fca5a5;
}

.dealer-dash__chart-panel,
.dealer-dash__activities {
  padding: 1.1rem 1rem 1.15rem;
  border-radius: 18px;
  border: 1px solid var(--border-glass);
  background: linear-gradient(160deg, rgba(17, 24, 39, 0.92), rgba(10, 15, 28, 0.88));
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.2);
}

.dealer-dash__chart-head,
.dealer-dash__activities-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.65rem 1rem;
  margin-bottom: 0.85rem;
}

.dealer-dash__section-title {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.dealer-dash__section-sub {
  margin: 0.2rem 0 0;
  font-size: 0.75rem;
  color: var(--text-muted);
}

.dealer-dash__error {
  margin: 0;
  padding: 0.65rem 0.85rem;
  border-radius: 0.65rem;
  font-size: 0.8125rem;
  color: #fca5a5;
  background: rgba(239, 68, 68, 0.1);
  border: 1px solid rgba(239, 68, 68, 0.25);
}

.dealer-dash__empty-note {
  margin: 0;
  padding: 0.5rem 0;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.dealer-dash__placeholder-badge {
  padding: 0.2rem 0.55rem;
  border-radius: 999px;
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--accent-primary-light);
  background: rgba(245, 130, 32, 0.12);
  border: 1px solid rgba(245, 130, 32, 0.25);
}

.dealer-dash-chart {
  width: 100%;
  overflow: hidden;
}

.dealer-dash-chart--empty {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 10rem;
}

.dealer-dash-chart__empty,
.dealer-dash-chart__empty-inline {
  margin: 0;
  font-size: 0.8125rem;
  color: var(--text-muted);
  text-align: center;
}

.dealer-dash-chart__empty-inline {
  padding: 0.35rem 0 0.15rem;
}

.dealer-dash-chart__svg {
  width: 100%;
  height: auto;
  display: block;
}

.dealer-dash-chart__grid {
  stroke: rgba(255, 255, 255, 0.06);
  stroke-width: 1;
}

.dealer-dash-chart__dot {
  fill: #60a5fa;
  stroke: #0f172a;
  stroke-width: 2;
}

.dealer-dash-chart__dot-glow {
  fill: rgba(96, 165, 250, 0.22);
}

.dealer-dash-chart__label,
.dealer-dash-chart__axis {
  fill: var(--text-muted);
  font-size: 10px;
  font-family: 'Outfit', sans-serif;
}

.dealer-dash__quick-actions {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.dealer-dash__quick-scroll {
  display: flex;
  gap: 0.65rem;
  overflow-x: auto;
  padding-bottom: 0.15rem;
  scrollbar-width: none;
}

.dealer-dash__quick-scroll::-webkit-scrollbar {
  display: none;
}

.dealer-dash-quick {
  position: relative;
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.55rem;
  min-width: 5.5rem;
  padding: 0.85rem 0.65rem 0.75rem;
  border-radius: 16px;
  border: 1px solid var(--border-glass);
  background: rgba(255, 255, 255, 0.03);
  color: var(--text-secondary);
  cursor: pointer;
  transition: var(--transition-smooth);
}

.dealer-dash-quick:hover {
  border-color: rgba(245, 130, 32, 0.4);
  color: var(--text-primary);
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.18);
}

.dealer-dash-quick__icon {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(245, 130, 32, 0.12);
  color: var(--accent-primary-light);
  border: 1px solid rgba(245, 130, 32, 0.2);
}

.dealer-dash-quick__plus {
  position: absolute;
  top: 0.55rem;
  right: 0.55rem;
  width: 1rem;
  height: 1rem;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--accent-primary);
  color: #fff;
}

.dealer-dash-quick__label {
  font-size: 0.6875rem;
  font-weight: 700;
  text-align: center;
  line-height: 1.25;
}

.dealer-dash-activity-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.dealer-dash-activity {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  width: 100%;
  padding: 0.75rem 0.8rem;
  border-radius: 14px;
  border: 1px solid var(--border-glass);
  background: rgba(255, 255, 255, 0.02);
  text-align: left;
  cursor: pointer;
  transition: var(--transition-smooth);
}

.dealer-dash-activity:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: color-mix(in srgb, var(--act-accent, var(--accent-primary)) 30%, transparent);
}

.dealer-dash-activity--blue { --act-accent: #3b82f6; }
.dealer-dash-activity--green { --act-accent: #10b981; }
.dealer-dash-activity--red { --act-accent: #ef4444; }
.dealer-dash-activity--orange { --act-accent: #f58220; }
.dealer-dash-activity--purple { --act-accent: #a855f7; }

.dealer-dash-activity__icon {
  flex-shrink: 0;
  width: 2rem;
  height: 2rem;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--act-accent) 14%, transparent);
  color: var(--act-accent);
}

.dealer-dash-activity__main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.dealer-dash-activity__main strong {
  font-size: 0.8125rem;
  font-weight: 800;
  color: var(--text-primary);
}

.dealer-dash-activity__main span {
  font-size: 0.75rem;
  color: var(--text-muted);
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.dealer-dash-activity__time {
  flex-shrink: 0;
  font-size: 0.6875rem;
  font-weight: 600;
  color: var(--text-muted);
  white-space: nowrap;
}

.dealer-dash__view-all {
  width: 100%;
  margin-top: 0.75rem;
  padding: 0.7rem 1rem;
  border-radius: 12px;
  border: 1px solid rgba(245, 130, 32, 0.35);
  background: rgba(245, 130, 32, 0.08);
  color: var(--accent-primary-light);
  font-size: 0.8125rem;
  font-weight: 800;
  cursor: pointer;
  transition: var(--transition-smooth);
}

.dealer-dash__view-all:hover {
  background: rgba(245, 130, 32, 0.16);
  color: #fff;
}

.dealer-dash__mini-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.dealer-dash-mini {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  padding: 0.9rem 0.85rem;
  border-radius: 14px;
  border: 1px solid var(--border-glass);
  background: rgba(255, 255, 255, 0.03);
}

.dealer-dash-mini--blue { --mini-accent: #3b82f6; }
.dealer-dash-mini--green { --mini-accent: #10b981; }
.dealer-dash-mini--orange { --mini-accent: #f58220; }
.dealer-dash-mini--purple { --mini-accent: #a855f7; }

.dealer-dash-mini__icon {
  flex-shrink: 0;
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--mini-accent) 14%, transparent);
  color: var(--mini-accent);
}

.dealer-dash-mini__body {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  min-width: 0;
}

.dealer-dash-mini__label {
  font-size: 0.625rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.dealer-dash-mini__value {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.dealer-dash-mini__trend {
  font-size: 0.625rem;
  font-weight: 600;
  color: var(--text-muted);
}

.dealer-dash-mini__link {
  margin-top: 0.2rem;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--mini-accent);
  font-size: 0.6875rem;
  font-weight: 700;
  cursor: pointer;
  text-align: left;
}

.dealer-dash-mini__link:hover {
  text-decoration: underline;
}

@media (min-width: 768px) {
  .dealer-dashboard {
    gap: 1.5rem;
  }

  .dealer-dash__kpis-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 1rem;
  }

  .dealer-dash__kpis-grid--four {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .dealer-dash__kpis-grid--pairs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .dealer-dash-kpi--featured {
    padding: 1.25rem 1.1rem;
  }

  .dealer-dash-kpi {
    padding: 1.1rem 1rem;
  }

  .dealer-dash__mini-stats {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 1rem;
  }

  .dealer-dash__chart-panel,
  .dealer-dash__activities {
    padding: 1.25rem 1.2rem 1.3rem;
  }
}

@media (min-width: 1100px) {
  .dealer-dashboard {
    display: grid;
    grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
    grid-template-areas:
      "hero hero"
      "kpis kpis"
      "chart chart"
      "quick quick"
      "activities activities"
      "mini mini";
    align-items: start;
  }

  .dealer-dash__hero { grid-area: hero; }
  .dealer-dash__kpis-layout { grid-area: kpis; }
  .dealer-dash__kpis { grid-area: kpis; }
  .dealer-dash__chart-panel { grid-area: chart; }
  .dealer-dash__quick-actions { grid-area: quick; }
  .dealer-dash__activities { grid-area: activities; }
  .dealer-dash__mini-stats { grid-area: mini; }
}

@keyframes sales-map-slide-in {
  from {
    transform: translate3d(-14%, 0, 0);
    opacity: 0.62;
  }
  to {
    transform: none;
    opacity: 1;
  }
}

.sales-map-page {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding-bottom: 1.5rem;
  min-height: 100%;
  touch-action: pan-y;
  animation: sales-map-slide-in 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}

.sales-map-page.is-swiping {
  touch-action: none;
}

.sales-map-page.is-swiping .sales-map__svg {
  pointer-events: none;
}

.sales-map__hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.55rem;
  align-items: start;
  margin-top: 0;
}

.sales-map__hero-map {
  min-width: 0;
}

.sales-map__viewport {
  overflow: hidden;
  width: 100%;
}

.sales-map__deck {
  display: flex;
  width: 200%;
  will-change: transform;
  transition: transform 0.34s cubic-bezier(0.22, 1, 0.36, 1);
}

.sales-map__deck.is-dragging {
  transition: none;
}

.sales-map__pane {
  flex: 0 0 50%;
  width: 50%;
  min-width: 0;
}

.sales-map__hero-map .sales-map__canvas {
  margin-top: 0;
}

.sales-map__hero-map .sales-map__stage {
  width: 100%;
}

.sales-map__kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.45rem;
  align-items: stretch;
}

.sales-map__refreshing {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.sales-map-kpi {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.2rem;
  min-width: 0;
  padding: 0.42rem 0.3rem 0.4rem;
  border-radius: 10px;
  text-align: center;
  background: linear-gradient(180deg, rgba(30, 41, 59, 0.92), rgba(15, 23, 42, 0.88));
  border: 1px solid rgba(148, 163, 184, 0.14);
  box-shadow: 0 8px 18px rgba(2, 6, 23, 0.18);
}

.sales-map-kpi__body {
  min-width: 0;
  width: 100%;
}

.sales-map-kpi strong {
  display: block;
  font-size: 0.9rem;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.sales-map-kpi__label {
  display: block;
  margin-bottom: 0.08rem;
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--text-muted);
  white-space: nowrap;
}

.sales-map-kpi__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.35rem;
  height: 1.35rem;
  border-radius: 999px;
  flex-shrink: 0;
}

.sales-map-kpi--blue .sales-map-kpi__icon {
  background: rgba(59, 130, 246, 0.18);
  color: #93c5fd;
}

.sales-map-kpi--green .sales-map-kpi__icon {
  background: rgba(34, 197, 94, 0.16);
  color: #86efac;
}

.sales-map-kpi--purple .sales-map-kpi__icon {
  background: rgba(168, 85, 247, 0.16);
  color: #d8b4fe;
}

.sales-map-kpi--rose .sales-map-kpi__icon {
  background: rgba(244, 63, 94, 0.16);
  color: #fb7185;
}

.sales-map__panel {
  padding: 0.9rem 0.85rem 1rem;
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(30, 41, 59, 0.78), rgba(15, 23, 42, 0.86));
  border: 1px solid rgba(148, 163, 184, 0.14);
  box-shadow: 0 12px 28px rgba(2, 6, 23, 0.2);
}

.sales-map__panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
}

.sales-map__panel-head .dealer-dash__section-title {
  margin: 0;
  min-width: 0;
}

.sales-map__period {
  flex: 0 0 auto;
}

.sales-map-period-popover {
  margin: 0;
}

.sales-map-period-popover__list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.sales-map-period-popover__custom {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 0.35rem 0.5rem 0.55rem;
}

.sales-map-period-popover__range {
  margin: 0;
  padding: 0.15rem 0.85rem 0.55rem;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-muted);
}

.sales-map__canvas {
  display: flex;
  justify-content: center;
  margin-top: 0.65rem;
}

.sales-map__stage {
  position: relative;
  width: min(100%, 26rem);
}

.sales-map__svg {
  display: block;
  width: 100%;
  height: auto;
  max-height: min(68vh, 34rem);
  touch-action: manipulation;
}

.sales-map__stage--kerala {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  width: 100%;
}

.sales-map__svg--kerala {
  flex: 1 1 auto;
  min-width: 0;
  max-height: min(74vh, 40rem);
}

.sales-map__stage--kerala .sales-map__hover-card {
  position: relative;
  right: auto;
  bottom: auto;
  flex: 0 0 7.4rem;
}

.sales-map__district-label {
  fill: #f8fafc;
  font-family: 'Fraunces', 'Times New Roman', serif;
  font-size: 7.4px;
  font-weight: 600;
  font-style: italic;
  letter-spacing: 0.01em;
  pointer-events: none;
  paint-order: stroke;
  stroke: rgba(15, 23, 42, 0.42);
  stroke-width: 0.55px;
}

.sales-map__district-label.is-hot {
  fill: #0f172a;
  stroke: rgba(255, 255, 255, 0.55);
}

.sales-map__state {
  cursor: pointer;
  transition: fill 0.28s ease, stroke 0.28s ease, stroke-width 0.28s ease, filter 0.28s ease;
}

.sales-map__state.is-hot {
  filter: drop-shadow(0 0 2.4px rgba(255, 255, 255, 0.95))
    drop-shadow(0 0 8px rgba(255, 255, 255, 0.38));
  animation: sales-map-state-glow 0.48s ease-out;
}

@keyframes sales-map-state-glow {
  0% {
    filter: drop-shadow(0 0 0 rgba(255, 255, 255, 0));
  }
  42% {
    filter: drop-shadow(0 0 5px rgba(255, 255, 255, 1))
      drop-shadow(0 0 14px rgba(255, 255, 255, 0.55));
  }
  100% {
    filter: drop-shadow(0 0 2.4px rgba(255, 255, 255, 0.95))
      drop-shadow(0 0 8px rgba(255, 255, 255, 0.38));
  }
}

.sales-map__hover-card {
  position: absolute;
  right: 0;
  bottom: 1.5%;
  width: 7.4rem;
  padding: 0.32rem 0.4rem 0.34rem;
  border-radius: 9px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: linear-gradient(165deg, rgba(17, 24, 39, 0.94), rgba(15, 23, 42, 0.88));
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(16px);
  pointer-events: none;
  animation: sales-map-card-in 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes sales-map-card-in {
  from {
    opacity: 0;
    transform: translateX(12px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
}

.sales-map__hover-card-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.28rem;
  margin: 0 0 0.16rem;
  font-size: 0.62rem;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.01em;
  color: #fff;
}

.sales-map__hover-card-stats {
  display: grid;
  gap: 0.04rem;
  margin: 0;
}

.sales-map__hover-card-stats > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.3rem;
  line-height: 1.2;
}

.sales-map__hover-card-stats dt {
  font-size: 0.48rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.sales-map__hover-card-stats dd,
.sales-map__hover-card-value {
  margin: 0;
  font-size: 0.6rem;
  font-weight: 800;
  line-height: 1.2;
}

.sales-map__hover-card-value--sales {
  color: #4ade80;
}

.sales-map__hover-card-value--dealers {
  color: #60a5fa;
}

.sales-map__hover-card-value--inactive {
  color: #fb7185;
}

.sales-map__hover-card-value--total {
  color: #e2e8f0;
}

.sales-map__hover-card-value--gold {
  color: #fbbf24;
}

.sales-map__hover-card-value--silver {
  color: #cbd5e1;
}

.sales-map__hover-card-value--bronze {
  color: #fb923c;
}

.sales-map__hover-card-value--slate {
  color: #c084fc;
}

.sales-map__legend {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin-top: 0.45rem;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.sales-map__legend-bar {
  flex: 1;
  height: 0.4rem;
  border-radius: 999px;
  background: linear-gradient(90deg, #1e4069, #3b82f6);
}

.sales-map__hint {
  margin: 0.45rem 0 0;
  font-size: 0.8125rem;
}

.sales-map__table-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.sales-map__rank-list {
  list-style: none;
  margin: 0.75rem 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.sales-map__rank-row {
  display: grid;
  grid-template-columns: 2rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.7rem;
  width: 100%;
  padding: 0.75rem 0.8rem;
  border: 1px solid rgba(148, 163, 184, 0.1);
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.55), rgba(2, 6, 23, 0.42));
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.15s ease;
}

.sales-map__rank-row:hover {
  border-color: rgba(148, 163, 184, 0.22);
}

.sales-map__rank-row.is-active {
  border-color: rgba(245, 130, 32, 0.55);
  background: linear-gradient(180deg, rgba(245, 130, 32, 0.16), rgba(15, 23, 42, 0.5));
}

.sales-map__rank {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.85rem;
  height: 1.85rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0;
  color: #cbd5e1;
  background: rgba(148, 163, 184, 0.14);
}

.sales-map__rank--gold {
  color: #1c1403;
  background: linear-gradient(180deg, #fde68a, #f59e0b);
}

.sales-map__rank--silver {
  color: #111827;
  background: linear-gradient(180deg, #f1f5f9, #94a3b8);
}

.sales-map__rank--bronze {
  color: #1c1008;
  background: linear-gradient(180deg, #fdba74, #c2410c);
}

.sales-map__rank-row--gold .sales-map__bar > span {
