/* Book courier wizard */
.book-courier {
  max-height: min(96dvh, 820px);
}

.book-courier__progress {
  display: flex;
  align-items: flex-start;
  list-style: none;
  margin: 0 0.15rem 1rem;
  padding: 0 0.1rem;
  z-index: 1;
  position: relative;
}

.book-courier__progress-item {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.5625rem;
  font-weight: 600;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  text-align: center;
}

/* Dashed connector running to the previous step, behind the dots. */
.book-courier__progress-item::before {
  content: '';
  position: absolute;
  top: 0.85rem;
  right: 50%;
  left: -50%;
  height: 0;
  border-top: 2px dashed #334155;
  z-index: 0;
}

.book-courier__progress-item:first-child::before {
  display: none;
}

.book-courier__progress-item.is-done::before,
.book-courier__progress-item.is-current::before {
  border-top-color: #ff7a00;
}

.book-courier__progress-item.is-done,
.book-courier__progress-item.is-current {
  color: #f1f5f9;
}

.book-courier__progress-dot {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 999px;
  border: 2px solid #334155;
  background: #0f172a;
  font-size: 0.75rem;
  font-weight: 700;
  transition: background 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease, color 0.2s ease;
}

.book-courier__progress-item.is-done .book-courier__progress-dot {
  background: #ff7a00;
  border-color: #ff7a00;
  color: #fff;
}

.book-courier__progress-item.is-current .book-courier__progress-dot {
  background: #ff7a00;
  border-color: #ff7a00;
  color: #fff;
  box-shadow: 0 0 0 4px rgba(255, 122, 0, 0.18);
}

.book-courier__progress-label {
  display: block;
  line-height: 1.2;
}

.book-courier__club-list {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  margin: 0.75rem 0;
}

.book-courier__club-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 0.6rem;
  align-items: center;
  padding: 0.65rem 0.75rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  cursor: pointer;
}

.book-courier__club-row.is-primary {
  cursor: default;
  opacity: 0.95;
}

