/* Camera barcode scanner */
.barcode-scanner {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.barcode-scanner__viewport {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  border-radius: 12px;
  overflow: hidden;
  background: #000;
  border: 1px solid #1f2937;
}

.barcode-scanner__video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  background: #000;
  transform: translateZ(0);
  backface-visibility: hidden;
}

.barcode-scanner__frame {
  position: absolute;
  inset: 18% 12%;
  border: 2px solid rgba(255, 122, 0, 0.9);
  border-radius: 10px;
  box-shadow: 0 0 0 100vmax rgba(0, 0, 0, 0.35);
  pointer-events: none;
}

.barcode-scanner__laser {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 2px;
  background: #ff7a00;
  box-shadow: 0 0 8px 1px rgba(255, 122, 0, 0.8);
  animation: barcode-laser 1.8s ease-in-out infinite;
}

@keyframes barcode-laser {
  0%, 100% { top: 12%; }
  50% { top: 88%; }
}

.barcode-scanner__overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 1rem;
  text-align: center;
  color: #cbd5e1;
  font-size: 0.8125rem;
  background: rgba(2, 6, 23, 0.75);
}

.barcode-scanner__overlay--error {
  color: #fca5a5;
}

.barcode-scanner__spin {
  animation: spin 1s linear infinite;
}

.barcode-scanner__close {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 999px;
  border: none;
  background: rgba(2, 6, 23, 0.7);
  color: #fff;
  cursor: pointer;
}

.barcode-scanner__hint {
  margin: 0;
  text-align: center;
}

.book-courier__actions {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.book-courier__actions .btn {
  justify-content: center;
}

.book-courier__next {
  margin-top: 0.35rem;
  width: 100%;
}

.book-courier__address-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.book-courier__address-card {
  display: flex;
  gap: 0.65rem;
  align-items: flex-start;
  padding: 0.75rem;
  border: 1px solid #1f2937;
  border-radius: 12px;
  background: rgba(15, 23, 42, 0.55);
  cursor: pointer;
}

.book-courier__address-card input {
  margin-top: 0.2rem;
  accent-color: #ff7a00;
}

.book-courier__address-card.is-selected {
  border-color: #ff7a00;
  background: rgba(255, 122, 0, 0.08);
}

.book-courier__address-copy {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  font-size: 0.8125rem;
  color: #cbd5e1;
}

.book-courier__address-copy strong {
  color: #f1f5f9;
  font-size: 0.875rem;
}

.book-courier__dims {
  grid-template-columns: repeat(3, 1fr);
}

/* YESONE wizard accents & new screens */
.book-courier__section-title .accent {
  color: #ff7a00;
}

.book-courier__section select,
.book-courier__manual input {
  color-scheme: dark;
}

/* Dealer search + list (Screen 2) */
.book-courier__search {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0 0.7rem;
  border: 1px solid #262626;
  border-radius: 12px;
  background: #171717;
  color: #64748b;
}

.book-courier__search input {
  flex: 1;
  border: none;
  background: transparent;
  color: #f1f5f9;
  padding: 0.6rem 0;
  font-size: 0.8125rem;
  outline: none;
}

.book-courier__autosuggest {
  position: relative;
}

.book-courier__suggest {
  display: flex;
  flex-direction: column;
  margin-top: 0.4rem;
  border: 1px solid #262626;
  border-radius: 12px;
  background: #131313;
  overflow: hidden;
  max-height: 22rem;
  overflow-y: auto;
}

.book-courier__suggest-item {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  align-items: flex-start;
  text-align: left;
  padding: 0.65rem 0.75rem;
  border: none;
  border-bottom: 1px solid #1f1f1f;
  background: transparent;
  color: #e2e8f0;
  font-size: 0.78rem;
  cursor: pointer;
}

.book-courier__suggest-item:last-child {
  border-bottom: none;
}

.book-courier__suggest-item:hover,
.book-courier__suggest-item:focus-visible {
  background: rgba(255, 122, 0, 0.1);
  outline: none;
}

.book-courier__suggest-item strong {
  font-size: 0.85rem;
}

.book-courier__suggest-address {
  margin-top: 0.15rem;
  white-space: pre-line;
  line-height: 1.35;
  color: #94a3b8;
  font-size: 0.75rem;
}

.book-courier__suggest-address--empty {
  font-style: italic;
  color: #64748b;
}

.book-courier__suggest-empty {
  padding: 0.7rem 0.75rem;
  margin: 0;
}

.book-courier__selected-dealer {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.book-courier__selected-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.75rem;
  border: 1px solid #262626;
  border-radius: 14px;
  background: #171717;
}

.book-courier__selected-copy {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  font-size: 0.78rem;
  color: #cbd5e1;
  min-width: 0;
}

.book-courier__selected-copy strong {
  font-size: 0.9rem;
  color: #f1f5f9;
}

.book-courier__change {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  flex-shrink: 0;
  padding: 0.35rem 0.6rem;
  border: 1px solid #333;
  border-radius: 999px;
  background: transparent;
  color: #ff9a3d;
  font-size: 0.72rem;
  font-weight: 700;
  cursor: pointer;
}

.book-courier__change:hover {
  border-color: #ff7a00;
  color: #ffb066;
}

.book-courier__address-heading {
  margin: 0;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #94a3b8;
}

.book-courier__address-tiles {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.book-courier__address-tile {
  border: 1px solid #262626;
  border-radius: 14px;
  background: #171717;
  overflow: hidden;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.book-courier__address-tile.is-selected {
  border-color: #ff7a00;
  background: rgba(255, 122, 0, 0.07);
}

.book-courier__address-tile-main {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  width: 100%;
  text-align: left;
  padding: 0.8rem;
  border: none;
  background: transparent;
  color: #cbd5e1;
  cursor: pointer;
}

.book-courier__address-tile-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.book-courier__address-tile-label {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: #f1f5f9;
}

.book-courier__address-tile.is-selected .book-courier__address-tile-head svg {
  color: #ff7a00;
}

.book-courier__address-tile-body {
  font-size: 0.78rem;
  line-height: 1.4;
  color: #94a3b8;
}

.book-courier__address-next {
  width: calc(100% - 1.6rem);
  margin: 0 0.8rem 0.8rem;
}

.book-courier__dealer-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.book-courier__dealer-card {
  display: flex;
  gap: 0.65rem;
  align-items: flex-start;
  padding: 0.75rem;
  border: 1px solid #262626;
  border-radius: 14px;
  background: #171717;
  cursor: pointer;
}

.book-courier__dealer-card input {
  margin-top: 0.15rem;
  accent-color: #ff7a00;
}

.book-courier__dealer-card.is-selected {
  border-color: #ff7a00;
  background: rgba(255, 122, 0, 0.07);
}

.book-courier__dealer-copy {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  font-size: 0.75rem;
  color: #cbd5e1;
  min-width: 0;
}

.book-courier__dealer-copy strong {
  color: #f1f5f9;
  font-size: 0.875rem;
}

.book-courier__dealer-code {
  color: #ff7a00;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.03em;
}

/* Box stepper (Screen 3) */
.book-courier__mode {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
  margin-bottom: 0.85rem;
}

.book-courier__mode-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.7rem 0.5rem;
  border: 1px solid #262626;
  border-radius: 12px;
  background: #171717;
  color: #cbd5e1;
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, color 0.15s ease;
}

.book-courier__mode-btn:hover {
  border-color: #ff7a00;
}

.book-courier__mode-btn.is-selected {
  border-color: #ff7a00;
  background: rgba(255, 122, 0, 0.12);
  color: #fff;
}

.book-courier__field {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 0.35rem;
  font-size: 0.75rem;
  font-weight: 700;
  color: #e2e8f0;
}

.book-courier__field > span {
  letter-spacing: 0.01em;
}

.book-courier__site-trigger {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.65rem;
  width: 100%;
  margin: 0;
  padding: 0.7rem 0.85rem;
  border: 1px solid #262626;
  border-radius: 12px;
  background: #171717;
  color: #f8fafc;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
}

.book-courier__site-trigger:hover {
  border-color: rgba(255, 122, 0, 0.55);
}

.book-courier__site-trigger.is-open,
.book-courier__site-trigger:focus-visible {
  outline: none;
  border-color: #ff7a00;
  box-shadow: 0 0 0 3px rgba(255, 122, 0, 0.18);
  background: #1a1a1a;
}

.book-courier__site-trigger svg {
  flex-shrink: 0;
  margin-top: 0.1rem;
  color: #94a3b8;
}

.book-courier__site-trigger-copy {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

.book-courier__site-trigger-copy strong {
  font-size: 0.875rem;
  font-weight: 700;
}

.book-courier__site-trigger-address {
  white-space: pre-line;
  line-height: 1.35;
  font-size: 0.72rem;
  font-weight: 500;
  color: #94a3b8;
}

.book-courier__site-menu {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(100% + 0.35rem);
  z-index: 20;
  display: flex;
  flex-direction: column;
  border: 1px solid #262626;
  border-radius: 12px;
  background: #131313;
  overflow: hidden;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.45);
}

.book-courier__site-option {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  align-items: stretch;
  width: 100%;
  margin: 0;
  padding: 0.7rem 0.8rem;
  border: none;
  border-bottom: 1px solid #1f1f1f;
  background: transparent;
  color: #e2e8f0;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.book-courier__site-option:last-child {
  border-bottom: none;
}

.book-courier__site-option:hover,
.book-courier__site-option:focus-visible {
  background: rgba(255, 122, 0, 0.1);
  outline: none;
}

.book-courier__site-option.is-selected {
  background: rgba(255, 122, 0, 0.14);
}

.book-courier__site-option-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.book-courier__site-option-head strong {
  font-size: 0.875rem;
  font-weight: 700;
  color: #f8fafc;
}

.book-courier__site-option-head svg {
  color: #ff7a00;
  flex-shrink: 0;
}

.book-courier__site-option-address {
  white-space: pre-line;
  line-height: 1.35;
  font-size: 0.75rem;
  font-weight: 500;
  color: #94a3b8;
}

.book-courier__site-option-address--empty {
  font-style: italic;
  color: #64748b;
}

/* -- Box details (Screen 3, new box-based model) ----------------- */
.book-courier__boxes {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  margin-top: 0.5rem;
}

.book-courier__box-count-hint {
  margin: 0.65rem 0 0;
}

.book-courier__box {
  border: 1px solid #262626;
  border-radius: 16px;
  background: #121212;
  padding: 0.9rem;
}

.book-courier__box.is-selected-combine {
  border-color: #ff7a00;
  box-shadow: 0 0 0 1px rgba(255, 122, 0, 0.35);
}

.book-courier__box-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.5rem;
}

.book-courier__box-head h4,
.book-courier__box-title {
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.95rem;
  font-weight: 800;
  color: #f8fafc;
}

.book-courier__box-check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.45rem;
  height: 1.45rem;
  border-radius: 7px;
  border: 1.5px solid #525252;
  background: #0a0a0a;
  color: #0a0a0a;
  cursor: pointer;
  flex-shrink: 0;
  padding: 0;
}

.book-courier__box-check.is-checked {
  border-color: #ff7a00;
  background: #ff7a00;
  color: #0a0a0a;
}

.book-courier__box-actions {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  margin-top: 0.85rem;
}

.book-courier__box-actions .book-courier__add-box {
  margin-top: 0;
}

.book-courier__combine-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  width: 100%;
  padding: 0.7rem;
  border: 1px dashed #525252;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.03);
  color: #e2e8f0;
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
}

.book-courier__combine-toggle:hover {
  border-color: #ff7a00;
  color: #ffb066;
  background: rgba(255, 122, 0, 0.06);
}

.book-courier__combine-bar {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  padding: 0.75rem 0.85rem;
  border: 1px solid #333;
  border-radius: 12px;
  background: #171717;
}

.book-courier__combine-bar-copy {
  margin: 0;
  font-size: 0.8rem;
  line-height: 1.4;
  color: #94a3b8;
}

.book-courier__combine-bar-copy strong {
  color: #f8fafc;
}

.book-courier__combine-bar-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: flex-end;
}

.book-courier__combine-form {
  margin-top: 0.85rem;
  padding: 0.9rem;
  border: 1px solid #ff7a00;
  border-radius: 16px;
  background: #121212;
}

.book-courier__combine-form-title {
  margin: 0 0 0.35rem;
  font-size: 0.95rem;
  font-weight: 800;
  color: #f8fafc;
}

.book-courier__combine-form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  margin-top: 0.9rem;
}

.book-courier__combine-form-actions .btn {
  flex: 1;
  min-width: 8rem;
}

.book-courier__box-remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 9px;
  border: 1px solid #3f1d1d;
  background: rgba(239, 68, 68, 0.08);
  color: #f87171;
  cursor: pointer;
}

.book-courier__box-remove:hover {
  background: rgba(239, 68, 68, 0.16);
}

.book-courier__box-label {
  margin: 0.9rem 0 0.4rem;
  font-size: 0.9rem;
  font-weight: 800;
  color: #f1f5f9;
}

.book-courier__box-label:first-of-type {
  margin-top: 0.25rem;
}

.book-courier__spare-box-preset {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0 0 0.65rem;
}

.book-courier__spare-box-preset > span {
  font-size: 0.6875rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted, #64748b);
}

.book-courier__spare-box-preset select {
  width: 100%;
  margin: 0;
  padding: 0.55rem 0.7rem;
  border: 1px solid rgba(148, 163, 184, 0.25);
  border-radius: 10px;
  background: #0f172a;
  color: inherit;
  font: inherit;
  font-size: 0.8125rem;
  font-weight: 600;
}

.book-courier__spare-box-preset select:focus {
  outline: none;
  border-color: rgba(255, 122, 0, 0.55);
  box-shadow: 0 0 0 2px rgba(255, 122, 0, 0.15);
}

.book-courier__box-label--tight {
  margin-top: 0.55rem;
}

.book-courier__box-req {
  font-size: 0.68rem;
  font-weight: 700;
  color: #f87171;
  text-transform: none;
  letter-spacing: 0;
}

.book-courier__box-opt {
  font-size: 0.68rem;
  font-weight: 600;
  color: #94a3b8;
  text-transform: none;
  letter-spacing: 0;
}

.book-courier__weight-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
}

.book-courier__weight-card {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  padding: 0.7rem 0.8rem;
  border: 1px solid #262626;
  border-radius: 12px;
  background: #171717;
}

.book-courier__weight-card-title {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.72rem;
  font-weight: 700;
  color: #94a3b8;
}

.book-courier__weight-card-value {
  display: flex;
  align-items: baseline;
  gap: 0.3rem;
}

.book-courier__weight-card-value input {
  width: 100%;
  min-width: 0;
  border: none;
  background: transparent;
  padding: 0;
  color: #f8fafc;
  font-size: 1.35rem;
  font-weight: 800;
}

.book-courier__weight-card-value input:focus {
  outline: none;
}

.book-courier__weight-card-value strong {
  font-size: 1.35rem;
  font-weight: 800;
  color: #f8fafc;
}

.book-courier__weight-card-value em {
  font-style: normal;
  font-size: 0.8rem;
  font-weight: 700;
  color: #94a3b8;
}

.book-courier__dim-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
}

.book-courier__dim-card {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  padding: 0.6rem 0.65rem;
  border: 1px solid #262626;
  border-radius: 12px;
  background: #171717;
}

.book-courier__dim-card-title {
  font-size: 0.68rem;
  font-weight: 700;
  color: #94a3b8;
}

.book-courier__dim-card-value {
  display: flex;
  align-items: baseline;
  gap: 0.25rem;
}

.book-courier__dim-card-value input {
  width: 100%;
  min-width: 0;
  border: none;
  background: transparent;
  padding: 0;
  color: #f8fafc;
  font-size: 1.1rem;
  font-weight: 800;
}

.book-courier__dim-card-value input:focus {
  outline: none;
}

.book-courier__dim-card-value em {
  font-style: normal;
  font-size: 0.72rem;
  font-weight: 700;
  color: #94a3b8;
}

/* Package photos grid */
.book-courier__photo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(88px, 1fr));
  gap: 0.55rem;
}

.book-courier__photo-cell {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3rem;
}

.book-courier__photo-open {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  padding: 0;
  border: 1px solid #262626;
  border-radius: 12px;
  overflow: hidden;
  background: #0d0d0d;
  cursor: pointer;
}

.book-courier__photo-open img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.book-courier__photo-del {
  position: absolute;
  top: -6px;
  right: -6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.35rem;
  height: 1.35rem;
  border-radius: 50%;
  border: 2px solid #0d0d0d;
  background: #1f2937;
  color: #f1f5f9;
  cursor: pointer;
  z-index: 2;
}

.book-courier__photo-del:hover {
  background: #ef4444;
  color: #fff;
}

.book-courier__photo-cap {
  font-size: 0.66rem;
  font-weight: 600;
  color: #94a3b8;
  text-align: center;
}

.book-courier__photo-add {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  aspect-ratio: 1 / 1;
  border: 1px dashed #3f3f46;
  border-radius: 12px;
  background: #0d0d0d;
  color: #ff9a3d;
  font-size: 0.72rem;
  font-weight: 700;
  cursor: pointer;
  text-align: center;
  padding: 0.3rem;
}

.book-courier__photo-add:hover {
  border-color: #ff7a00;
  color: #ffb066;
}

.book-courier__photo-add-opt {
  font-style: normal;
  font-size: 0.6rem;
  font-weight: 600;
  color: #64748b;
}

.book-courier__add-box {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  width: 100%;
  margin-top: 0.85rem;
  padding: 0.7rem;
  border: 1px dashed #ff7a00;
  border-radius: 12px;
  background: rgba(255, 122, 0, 0.06);
  color: #ff9a3d;
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
}

.book-courier__add-box:hover {
  background: rgba(255, 122, 0, 0.12);
  color: #ffb066;
}

.book-courier__add-item {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: end;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}

.book-courier__add-item-qty input {
  width: 4.5rem;
}

.book-courier__add-item-btn {
  white-space: nowrap;
}

.book-courier__catalog-toggle-wrap {
  margin-bottom: 0.85rem;
}

.book-courier__catalog-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.2rem 0;
  border: none;
  background: transparent;
  color: #ff9a3d;
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
}

.book-courier__catalog-toggle:hover {
  color: #ffb066;
}

.book-courier__stepper {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.6rem 0.75rem;
  border: 1px solid #262626;
  border-radius: 12px;
  background: #171717;
  font-size: 0.8125rem;
  font-weight: 600;
  color: #e2e8f0;
}

.book-courier__stepper-controls {
  display: inline-flex;
  align-items: center;
  gap: 0.85rem;
}

.book-courier__stepper-controls button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 8px;
  border: none;
  background: #ff7a00;
  color: #111;
  cursor: pointer;
}

.book-courier__stepper-controls button:hover {
  filter: brightness(1.08);
}

.book-courier__stepper-controls strong {
  min-width: 1.5rem;
  text-align: center;
  font-size: 1rem;
}

.book-courier__volumetric {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.55rem 0.75rem;
  border: 1px dashed #333;
  border-radius: 10px;
  font-size: 0.8125rem;
  color: #94a3b8;
}

.book-courier__volumetric strong {
  color: #ff7a00;
  font-size: 0.9375rem;
}

/* Shipment items (Screen 3) */
.book-courier__items {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  padding-top: 0.65rem;
  border-top: 1px solid #1f2937;
}

.book-courier__items-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin: 0;
  font-size: 0.875rem;
  font-weight: 700;
  color: #f1f5f9;
}

.book-courier__items-flag {
  font-size: 0.625rem;
  font-weight: 700;
  color: #fbbf24;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.book-courier__items-flag.is-done {
  color: #4ade80;
}

.book-courier__item-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.book-courier__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.5rem 0.65rem;
  border: 1px solid #262626;
  border-radius: 10px;
  background: #171717;
}

.book-courier__item.is-done {
  border-color: rgba(74, 222, 128, 0.4);
}

.book-courier__item-info {
  display: inline-flex;
  align-items: baseline;
  gap: 0.4rem;
  font-size: 0.8125rem;
  color: #f1f5f9;
}

.book-courier__item-upload {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.35rem 0.6rem;
  border: 1px solid #ff7a00;
  border-radius: 8px;
  background: transparent;
  color: #ff7a00;
  font-size: 0.6875rem;
  font-weight: 700;
  cursor: pointer;
}

.book-courier__item-actions {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.book-courier__item-thumb {
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 8px;
  overflow: hidden;
  border: none;
  padding: 0;
  cursor: pointer;
  background: #000;
}

.book-courier__item-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.book-courier__item-clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.8rem;
  height: 1.8rem;
  border-radius: 8px;
  border: none;
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
  cursor: pointer;
}

/* Review cards (Screen 4) */
.book-courier__review-card {
  padding: 0.75rem;
  border: 1px solid #262626;
  border-radius: 14px;
  background: #171717;
  margin-bottom: 0.6rem;
}

.book-courier__review-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}

.book-courier__review-head h4 {
  margin: 0;
  font-size: 0.8125rem;
  font-weight: 700;
  color: #f1f5f9;
}

.book-courier__edit {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  border: none;
  background: transparent;
  color: #ff7a00;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
}

.book-courier__review-edit {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.book-courier__kv {
  display: grid;
  gap: 0.35rem;
  margin: 0;
}

.book-courier__kv > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.8125rem;
}

.book-courier__kv dt {
  margin: 0;
  color: #94a3b8;
}

.book-courier__kv dd {
  margin: 0;
  color: #f1f5f9;
  font-weight: 600;
  text-align: right;
}

.book-courier__review-address {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  margin: 0;
  font-size: 0.8125rem;
  color: #cbd5e1;
}

.book-courier__review-address strong {
  color: #f1f5f9;
  font-size: 0.875rem;
}

.book-courier__gallery {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.book-courier__thumb {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.2rem;
  width: 4rem;
  font-size: 0.625rem;
  color: #94a3b8;
  text-align: center;
}

.book-courier__thumb > button:first-child,
.book-courier__thumb > img {
  width: 4rem;
  height: 4rem;
  border-radius: 10px;
  overflow: hidden;
  border: 1px solid #333;
  padding: 0;
  background: #000;
  cursor: pointer;
}

.book-courier__thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.book-courier__thumb-del {
  position: absolute;
  top: -0.4rem;
  right: -0.4rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.4rem;
  height: 1.4rem;
  border-radius: 999px;
  border: none;
  background: #ef4444;
  color: #fff;
  cursor: pointer;
}

/* Label (Screen 5) */
.book-courier__label-preview {
  border: 2px solid #ff7a00;
  border-radius: 14px;
  padding: 1rem;
  background: #171717;
}

.book-courier__label-partner {
  font-size: 1.1rem;
  font-weight: 800;
  text-transform: uppercase;
  color: #f1f5f9;
}

.book-courier__label-caption {
  font-size: 0.625rem;
  letter-spacing: 0.15em;
  color: #94a3b8;
  margin-bottom: 0.75rem;
}

.book-courier__label-track {
  border: 1px dashed #444;
  border-radius: 10px;
  padding: 0.7rem;
  text-align: center;
  margin-bottom: 0.75rem;
}

.book-courier__label-track span {
  display: block;
  font-size: 0.5625rem;
  letter-spacing: 0.1em;
  color: #94a3b8;
}

.book-courier__label-track strong {
  font-size: 1.05rem;
  letter-spacing: 0.08em;
  color: #f1f5f9;
}

.book-courier__label-bars {
  height: 44px;
  margin: 0.5rem 0 0.25rem;
  border-radius: 2px;
  background-image: repeating-linear-gradient(90deg, #fff 0, #fff 2px, transparent 2px, transparent 4px, #fff 4px, #fff 7px, transparent 7px, transparent 9px);
  background-color: #0b0b0b;
  padding: 4px;
}

.book-courier__label-num {
  font-size: 0.8125rem;
  letter-spacing: 0.25em;
  color: #cbd5e1;
}

.book-courier__label-to {
  font-size: 0.75rem;
  color: #cbd5e1;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.book-courier__label-to span:first-child {
  font-size: 0.5625rem;
  letter-spacing: 0.1em;
  color: #94a3b8;
}

.book-courier__label-to strong {
  color: #f1f5f9;
  font-size: 0.8125rem;
}

.book-courier__paste-note {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0.6rem 0 0;
  padding: 0.55rem 0.7rem;
  border-radius: 10px;
  background: rgba(74, 222, 128, 0.12);
  color: #4ade80;
  font-size: 0.75rem;
  font-weight: 600;
}

/* Final photo (Screen 6) */
.book-courier__final-photo {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  align-items: center;
}

.book-courier__final-photo img {
  width: 100%;
  max-height: 16rem;
  object-fit: cover;
  border-radius: 12px;
  border: 1px solid #333;
  cursor: pointer;
}

.book-courier__final-photo-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
  width: 100%;
}

.book-courier__label-next-row {
  margin-top: 0.85rem;
}

@media (max-width: 480px) {
  .book-courier__label-next-row {
    grid-template-columns: 1fr;
  }
}

.book-courier__label-grid {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.book-courier__label-card {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 0.75rem;
  border: 1px solid #262626;
  border-radius: 14px;
  background: #121212;
}

.book-courier__label-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
}

.book-courier__label-print-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.4rem;
}

.book-courier__label-card-head h4 {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 800;
  color: #f8fafc;
}

.book-courier__label-preview {
  overflow: auto;
  border-radius: 10px;
  background: #f8fafc;
  padding: 0.65rem;
}

.book-courier__label-preview--stack {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-height: min(70vh, 640px);
  overflow-y: auto;
}

/* Keep each preview at true 100×150 aspect — never flex-shrink into one viewport. */
.book-courier__label-preview--stack .book-courier__label-sheet {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  align-items: center;
}

.book-courier__label-sheet-caption {
  margin: 0;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #64748b;
}

.shipping-label-print-dialog__preview .book-courier__label-sheet-caption {
  color: #94a3b8;
}

.book-courier__label-preview--stack .shipping-label-bitmap-preview {
  flex: 0 0 auto;
  width: 100%;
  max-width: 100mm;
}

.shipping-label-bitmap-preview {
  position: relative;
  margin: 0 auto;
  background: #fff;
  border-radius: 2px;
  overflow: hidden;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.06);
}

.shipping-label-bitmap-preview__canvas {
  display: block;
  width: 100%;
  height: 100%;
  /* Smooth screen scale â€” pixelated made the 203 DPI preview look jagged. */
  image-rendering: auto;
}

.shipping-label-bitmap-preview__loading {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.72);
  z-index: 1;
}

.shipping-label-bitmap-preview__error {
  margin: 0;
  padding: 1rem;
  color: #b91c1c;
  background: #fff;
}

.book-courier__slip-preview {
  display: flex;
  flex-direction: column;
  height: min(65vh, 560px);
  padding: 0 !important;
  overflow: hidden;
  background: #0b1220;
  border: 2px solid #ff7a00;
}

.book-courier__slip-preview .courier-slip-pdf {
  flex: 1;
  min-height: 0;
}

.book-courier__slip-preparing {
  margin: auto;
  padding: 1.25rem;
  text-align: center;
}

.book-courier__slip-image {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
  background: #fff;
}

.book-courier__slip-error {
  margin: 0;
  padding: 0.5rem 0.65rem 0;
  color: #fca5a5;
  font-size: 0.75rem;
  flex-shrink: 0;
}

.logistics-booking__delhivery-doc-pages {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin: 0 0 0.75rem;
}

.delhivery-label-dialog .courier-slip-view-dialog__body {
  background: #0b1220;
  padding: 0.65rem;
}

.delhivery-label-dialog__stack {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-height: none;
  height: 100%;
  background: transparent;
  padding: 0.25rem 0;
  box-sizing: border-box;
}

.delhivery-label-dialog__stack .book-courier__label-sheet {
  width: 100%;
  max-width: 100mm;
  align-items: center;
  margin-left: auto;
  margin-right: auto;
}

.delhivery-label-dialog__sheet {
  width: 100%;
  max-width: 100mm;
  aspect-ratio: 100 / 150;
  margin-left: auto;
  margin-right: auto;
  padding: 3mm 4mm;
  box-sizing: border-box;
  background: #fff;
  border-radius: 2px;
  overflow: hidden;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.08);
}

.delhivery-label-dialog__img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
  background: #fff;
}

.delhivery-label-dialog .book-courier__label-sheet-caption {
  color: #94a3b8;
  text-align: center;
  width: 100%;
}

.book-courier__slip-error:is(ul) {
  padding-left: 1.25rem;
  list-style: disc;
}

.book-courier__contact-fields {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
  margin: 0.75rem 0;
}

.book-courier__contact-fields label {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0;
  min-width: 0;
}

.book-courier__contact-fields label span {
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #94a3b8;
}

.book-courier__contact-fields input {
  width: 100%;
  margin: 0;
  padding: 0.55rem 0.7rem;
  border: 1px solid #334155;
  border-radius: 10px;
  background: #0f172a;
  color: #f8fafc;
  font: inherit;
  font-size: 0.875rem;
}

.book-courier__contact-fields input:focus {
  outline: none;
  border-color: #ff7a00;
  box-shadow: 0 0 0 3px rgba(255, 122, 0, 0.18);
}

@media (max-width: 640px) {
  .book-courier__contact-fields {
    grid-template-columns: 1fr;
  }
}

.book-courier__label-preview .sheet {
  width: 100mm;
  height: 150mm;
  max-width: 100%;
  margin: 0 auto;
  border: none;
  border-radius: 0;
  padding: 2.5mm;
  background: #fff;
  color: #111;
  font-family: Arial, Helvetica, sans-serif;
  overflow: hidden;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.book-courier__label-preview .sheet__frame {
  flex: 1 1 auto;
  min-height: 0;
  border: 2.5px solid #111;
  border-radius: 3.2mm;
  padding: 2.4mm 2.4mm 2.2mm;
  background: #fff;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 0;
  overflow: hidden;
}

.book-courier__label-preview .sheet--courier {
  border-width: 3px;
}

.book-courier__label-preview .sheet__header {
  display: flex;
  align-items: center;
  gap: 2mm;
  padding: 0;
  margin: 0;
  border-bottom: none;
  min-height: 9mm;
}

.book-courier__label-preview .sheet__brand-lockup {
  display: flex;
  align-items: center;
  gap: 2mm;
  min-width: 0;
  flex: 1 1 auto;
  width: 100%;
}

.book-courier__label-preview .sheet__mark {
  height: 7mm;
  width: auto;
  display: block;
  flex-shrink: 0;
  object-fit: contain;
}

.book-courier__label-preview .sheet__firm {
  flex: 1 1 auto;
  min-width: 0;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 5.2mm;
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1.05;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #111;
}

.book-courier__label-preview .sheet__label {
  display: block;
  color: #111;
  background: none;
  font-size: 2.4mm;
  font-weight: 900;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  line-height: 1.15;
  margin-bottom: 0;
}

.book-courier__label-preview .sheet__glyph {
  width: 3.2mm;
  height: 3.2mm;
  flex-shrink: 0;
  stroke: #111;
  stroke-width: 2.5;
}

.book-courier__label-preview .sheet__metric-head .sheet__glyph {
  width: 3mm;
  height: 3mm;
}

.book-courier__label-preview .sheet__panel {
  border: 1.4px solid #111;
  border-radius: 2.2mm;
  overflow: hidden;
  background: #fff;
  margin-top: 1.2mm;
}

.book-courier__label-preview .sheet__parties {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  margin: 1.2mm 0 0;
  border: none;
  border-top: 1.5px solid #111;
  border-bottom: none;
  border-radius: 0;
  padding: 0;
  flex: 1 1 auto;
  min-height: 36mm;
  max-height: none;
  overflow: hidden;
}

.book-courier__label-preview .sheet__party {
  padding: 1.8mm 2mm;
  min-width: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.book-courier__label-preview .sheet__party .sheet__label {
  margin-bottom: 1.2mm;
  font-size: 2.6mm;
}

.book-courier__label-preview .sheet__party + .sheet__party {
  border-left: 1.5px solid #111;
}

.book-courier__label-preview .sheet__party-name {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 3.4mm;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 1.2mm;
  text-transform: none;
}

.book-courier__label-preview .sheet__party-address {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 2.9mm;
  font-weight: 700;
  line-height: 1.3;
  white-space: pre-line;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.book-courier__label-preview .sheet__party-phone {
  display: block;
  margin-top: 1.4mm;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 3mm;
  font-weight: 700;
  line-height: 1.2;
}

.book-courier__label-preview .sheet__metrics {
  display: flex;
  flex-direction: column;
  margin: 0;
  flex: 0 0 auto;
  min-height: 26mm;
}

.book-courier__label-preview .sheet__metrics-row {
  display: grid;
  flex: 1 1 0;
  min-height: 0;
}

.book-courier__label-preview .sheet__metrics-row--3 {
  grid-template-columns: repeat(3, 1fr);
}

.book-courier__label-preview .sheet__metrics-row--4 {
  grid-template-columns: repeat(4, 1fr);
}

.book-courier__label-preview .sheet__metrics-row + .sheet__metrics-row {
  border-top: 1px solid #111;
}

.book-courier__label-preview .sheet__metric {
  padding: 1.3mm 1.2mm 1.2mm;
  border-right: 1px solid #111;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
