  flex-wrap: wrap;
  gap: 0.5rem 0.85rem;
  padding: 0 0.85rem 0.65rem;
}

.dealers-status-legend__item {
  display: inline-flex;
  align-items: flex-start;
}

.dealers-status-legend__text {
  font-size: 0.6875rem;
  color: var(--text-muted);
}

/* Stage + login indicator (mockup: dot in ring + two-line label) */
.dealers-status-indicator {
  display: inline-flex;
  align-items: flex-start;
  gap: 0.4rem;
  flex-shrink: 0;
  color: var(--text-secondary);
}

.dealers-status-indicator--compact {
  align-items: center;
}

.dealers-status-indicator__ring {
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  border-radius: 50%;
  border: 2px solid currentColor;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 0.05rem;
}

.dealers-status-indicator--compact .dealers-status-indicator__ring {
  width: 1rem;
  height: 1rem;
  margin-top: 0;
}

.dealers-status-indicator__dot {
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: currentColor;
}

.dealers-status-indicator--compact .dealers-status-indicator__dot {
  width: 0.35rem;
  height: 0.35rem;
}

.dealers-status-indicator__text {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0;
  line-height: 1.15;
  text-align: right;
}

.dealers-status-indicator__stage {
  font-size: 0.8125rem;
  font-weight: 800;
  color: currentColor;
}

.dealers-status-indicator__login {
  font-size: 0.6875rem;
  font-weight: 400;
  color: rgba(226, 232, 240, 0.88);
}

.dealers-status-indicator--active-yes {
  color: #4ade80;
}

.dealers-status-indicator--active-no {
  color: #facc15;
}

.dealers-status-indicator--non-active-yes {
  color: #fb923c;
}

.dealers-status-indicator--non-active-no {
  color: #fbbf24;
}

.dealers-status-indicator--blacklisted-yes {
  color: #f87171;
}

.dealers-status-indicator--blacklisted-no {
  color: #fca5a5;
}

.dealers-status-indicator--unset-yes {
  color: #94a3b8;
}

.dealers-status-indicator--unset-no {
  color: #64748b;
}

.dealers-status-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.65rem;
  height: 1.65rem;
  border-radius: 999px;
  border: 1px solid transparent;
  flex-shrink: 0;
}

.dealers-status-badge__symbol {
  font-size: 0.95rem;
  line-height: 1;
  font-weight: 700;
}

.dealers-status-badge--active-yes {
  background: rgba(74, 222, 128, 0.12);
  color: #4ade80;
  border-color: rgba(74, 222, 128, 0.45);
}

.dealers-status-badge--active-no {
  background: rgba(250, 204, 21, 0.1);
  color: #facc15;
  border-color: rgba(250, 204, 21, 0.45);
}

.dealers-status-badge--non-active-yes {
  background: rgba(245, 158, 11, 0.18);
  color: #fcd34d;
  border-color: rgba(245, 158, 11, 0.35);
}

.dealers-status-badge--non-active-no {
  background: rgba(245, 158, 11, 0.1);
  color: #fbbf24;
  border-color: rgba(245, 158, 11, 0.22);
  border-style: dashed;
}

.dealers-status-badge--blacklisted-yes {
  background: rgba(239, 68, 68, 0.18);
  color: #fca5a5;
  border-color: rgba(239, 68, 68, 0.35);
}

.dealers-status-badge--blacklisted-no {
  background: rgba(239, 68, 68, 0.1);
  color: #f87171;
  border-color: rgba(239, 68, 68, 0.22);
  border-style: dashed;
}

.dealers-status-badge--unset-yes {
  background: rgba(148, 163, 184, 0.16);
  color: #cbd5e1;
  border-color: rgba(148, 163, 184, 0.3);
}

.dealers-status-badge--unset-no {
  background: rgba(148, 163, 184, 0.08);
  color: #94a3b8;
  border-color: rgba(148, 163, 184, 0.22);
  border-style: dashed;
}

.dealers-status-cell {
  display: flex;
  justify-content: flex-end;
  min-width: 6.5rem;
}

.dealers-status-picker {
  position: relative;
  flex-shrink: 0;
  display: inline-flex;
}

.dealers-status-picker__trigger {
  display: inline-flex;
  align-items: flex-start;
  border: none;
  background: transparent;
  padding: 0.15rem 0.2rem;
  margin: -0.15rem -0.2rem;
  border-radius: 8px;
  cursor: pointer;
  font: inherit;
  transition: background 0.15s ease;
}

.dealers-status-picker__trigger:hover {
  background: rgba(255, 255, 255, 0.06);
  filter: none;
}

.dealers-status-picker__trigger[aria-expanded='true'] {
  background: rgba(59, 130, 246, 0.12);
  box-shadow: none;
}

.dealers-status-picker__menu {
  min-width: 8.5rem;
  padding: 0.35rem;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.dealers-status-picker__option {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0.45rem;
  width: 100%;
  border: none;
  border-radius: 8px;
  background: transparent;
  padding: 0.4rem 0.5rem;
  cursor: pointer;
}

.dealers-status-picker__option:hover {
  background: rgba(255, 255, 255, 0.06);
}

.dealers-status-picker__option--selected {
  background: rgba(59, 130, 246, 0.15);
}

.dealers-table__status-col {
  text-align: right;
  min-width: 7.5rem;
}

.dealers-table__actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  white-space: nowrap;
}

.dealers-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-wrap: wrap;
  padding: 0.5rem 0.75rem;
}

.dealers-pagination--inset.dealers-pagination--top {
  border-bottom: 1px solid var(--border-glass);
}

.dealers-pagination--inset.dealers-pagination--bottom {
  position: sticky;
  bottom: 0;
  z-index: 20;
  background: var(--bg-app);
  border-top: 1px solid var(--border-glass);
}

.dealers-pagination__info {
  flex: 1;
  text-align: center;
  min-width: 8rem;
  font-size: 0.75rem;
}

.dealers-pagination__page {
  color: var(--text-muted);
  min-width: 4.5rem;
  text-align: center;
  font-size: 0.75rem;
}

.dealers-pagination__btns {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

@media (max-width: 1100px) {
  .dealers-filters {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .dealers-kpis {
    grid-template-columns: repeat(auto-fit, minmax(128px, 1fr));
  }

  .dealers-filters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 768px) {
  .main-content:has(.dealers-page) {
    display: flex;
    flex-direction: column;
    min-height: 100dvh;
  }

  .dealers-page {
    flex: 1;
    min-height: 0;
    gap: 0.3rem;
    overflow: hidden;
  }

  .content-area:has(.dealers-page) {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;
    padding: 0.35rem 0.65rem 0.5rem;
  }

  .content-area:has(.dealers-detail-page) {
    padding: 0.25rem 0.5rem 0.65rem;
  }

  .dealers-table-panel {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  .dealers-roster {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding-bottom: calc(4.25rem + env(safe-area-inset-bottom, 0px));
  }

  .dealers-kpis.dealers-kpis--roster {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    overflow: visible;
    gap: 0.3rem;
  }

  .dealers-kpi--roster {
    flex: unset;
    width: auto;
    min-width: 0;
    padding: 0.35rem 0.25rem !important;
  }

  .dealers-kpi__label-long {
    display: none;
  }

  .dealers-kpi__label-short {
    display: inline;
  }

  .dealers-kpis {
    display: flex;
    overflow-x: auto;
    gap: 0.35rem;
    scroll-snap-type: x proximity;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
  }

  .dealers-kpis::-webkit-scrollbar {
    display: none;
  }

  .dealers-kpi {
    flex: 0 0 5.1rem;
    scroll-snap-align: start;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 0.45rem 0.4rem !important;
    gap: 0.15rem;
  }

  .dealers-kpi svg {
    width: 15px;
    height: 15px;
  }

  .dealers-kpi h3 {
    font-size: 0.5625rem;
    line-height: 1.15;
  }

  .dealers-kpi .stat-value {
    font-size: 0.9375rem;
  }

  .dealers-kpis.dealers-kpis--roster {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    overflow: visible;
    gap: 0.3rem;
  }

  .dealers-kpi--roster {
    flex: unset;
    width: auto;
    min-width: 0;
    align-items: center;
    text-align: center;
    padding: 0.35rem 0.2rem !important;
  }

  .dealers-status-legend {
    display: none;
  }

  .dealers-toolbar {
    display: none;
  }

  .dealers-toolbar.panel {
    padding: 0.55rem 0.65rem;
  }

  .dealers-toolbar__row {
    flex-direction: row;
    flex-wrap: nowrap;
    gap: 0.35rem;
  }

  .dealers-toolbar__actions {
    display: none;
  }

  .dealers-search {
    flex: 1 1 100%;
    width: 100%;
  }

  .dealers-toolbar__btn-label {
    display: none;
  }

  .dealers-filters-mobile {
    display: block;
    width: 100%;
    margin-top: 0.45rem;
    padding-top: 0.45rem;
    border-top: 1px solid var(--border-glass);
  }

  .dealers-filters-mobile .dealers-multiselect {
    width: 100%;
  }

  .dealers-filters-mobile .dealers-multiselect--state-cta .dealers-multiselect__trigger {
    min-height: 2.85rem;
    padding: 0.7rem 1rem;
    font-size: 0.9375rem;
    font-weight: 700;
    border-radius: 12px;
    border: 1px solid rgba(96, 165, 250, 0.55);
    background: linear-gradient(135deg, #2563eb 0%, #3b82f6 100%);
    color: #fff;
    box-shadow: 0 4px 16px rgba(37, 99, 235, 0.38);
  }

  .dealers-filters-mobile .dealers-multiselect--state-cta .dealers-multiselect__trigger svg {
    color: #fff;
    flex-shrink: 0;
  }

  .dealers-filters-mobile .dealers-multiselect--state-cta .dealers-multiselect__clear {
    color: rgba(255, 255, 255, 0.9);
  }

  .dealers-filters-drawer {
    display: none;
  }

  .dealers-table-wrap--desktop {
    display: none;
  }

  .dealers-tiles--mobile {
    display: flex;
    flex-direction: column;
    gap: 0.45rem;
    padding: 0.45rem 0.65rem 0.65rem;
  }

  .dealers-tile {
    padding: 0.55rem;
    gap: 0.4rem;
    border-radius: 12px;
  }

  .dealers-status-legend__preview {
    display: none;
  }

  .dealers-status-legend:not([open]) .dealers-status-legend__hint,
  .dealers-status-legend:not([open]) .dealers-status-legend__items {
    display: none;
  }

  .dealers-pagination {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    padding: 0.4rem 0.75rem calc(0.45rem + env(safe-area-inset-bottom, 0px));
    gap: 0.35rem;
  }

  .dealers-pagination--inset.dealers-pagination--bottom {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 45;
    margin: 0;
    background: var(--bg-app);
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 0 -8px 24px rgba(0, 0, 0, 0.35);
  }

  .dealers-pagination--top {
    display: none;
  }

  .dealers-pagination__mode-toggle {
    display: none;
  }

  .dealers-pagination__info {
    flex: 1 1 100%;
    text-align: left;
    font-size: 0.6875rem;
  }

  .dealers-pagination__btns {
    flex: 1;
    justify-content: flex-end;
  }
}

@media (min-width: 769px) {
  .dealers-filters-drawer > .dealers-filters {
    display: grid !important;
  }

  .dealers-status-legend__preview {
    display: none;
  }
