.dealers-detail__value {
  color: var(--text-primary);
  text-align: right;
  word-break: break-word;
}

.dealers-detail__record-intro {
  margin: 0 0 1rem;
  line-height: 1.45;
}

.dealers-detail__record-section + .dealers-detail__record-section {
  margin-top: 1.15rem;
  padding-top: 1.15rem;
  border-top: 1px solid var(--border-glass);
}

.dealers-detail__record-heading {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  margin-bottom: 0.65rem;
}

.dealers-detail__record-heading h4 {
  margin: 0;
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--text-primary);
}

.dealers-detail__data-grid {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.dealers-detail__data-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr);
  gap: 0.65rem;
  align-items: start;
  padding: 0.45rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.dealers-detail__data-row:last-child {
  border-bottom: none;
}

.dealers-detail__data-head {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.25rem;
  min-width: 0;
}

.dealers-detail__source {
  display: inline-flex;
  align-items: center;
  padding: 0.08rem 0.35rem;
  border-radius: 999px;
  font-size: 0.5625rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.dealers-detail__source--zoho {
  background: rgba(59, 130, 246, 0.18);
  color: #93c5fd;
}

.dealers-detail__source--overlay {
  background: rgba(249, 115, 22, 0.18);
  color: #fdba74;
}

.dealers-detail__source--computed {
  background: rgba(16, 185, 129, 0.16);
  color: #6ee7b7;
}

.dealers-detail__source--system {
  background: rgba(148, 163, 184, 0.16);
  color: #cbd5e1;
}

.dealers-detail__data-row .dealers-detail__value {
  text-align: left;
  font-size: 0.8125rem;
}

.dealers-detail__value--code {
  margin: 0;
  padding: 0.45rem 0.55rem;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.22);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.6875rem;
  line-height: 1.45;
  white-space: pre-wrap;
  word-break: break-word;
}

.dealers-detail-page__body {
  transition: transform 0.15s ease-out;
}

.dealers-detail__pull-refresh {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  margin: -0.5rem 0 0.75rem;
  color: var(--text-muted);
  font-size: 0.8125rem;
  overflow: hidden;
}

.dealers-detail__pincode-hint {
  display: block;
  margin-top: 0.35rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}

.dealers-detail__pincode-error {
  display: block;
  margin-top: 0.35rem;
  font-size: 0.75rem;
  color: #f87171;
}

.dealers-detail__topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.dealers-detail__save-top {
  flex-shrink: 0;
}

.dealers-detail-page--dirty {
  padding-bottom: 4.5rem;
}

.dealers-detail__save-float {
  position: fixed;
  right: max(0.75rem, env(safe-area-inset-right, 0px));
  left: auto;
  bottom: max(1rem, env(safe-area-inset-bottom, 0px));
  z-index: 45;
  display: flex;
  justify-content: flex-end;
  padding: 0;
  pointer-events: none;
  animation: dealers-save-float-in 0.2s ease-out;
}

.dealers-detail__save-float-actions {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  pointer-events: auto;
}

.dealers-detail__save-float-btn {
  pointer-events: auto;
  width: 2.5rem;
  height: 2.5rem;
  min-width: 0;
  padding: 0;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow:
    0 4px 14px rgba(0, 0, 0, 0.28),
    0 2px 8px rgba(0, 0, 0, 0.18);
}

.dealers-detail__save-float-btn--revert {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--border-glass);
  color: var(--text-main);
}

.dealers-detail__save-float-btn:not(:disabled):hover {
  transform: translateY(-1px);
}

@keyframes dealers-save-float-in {
  from {
    opacity: 0;
    transform: translateY(0.75rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 640px) {
  .dealers-detail-page--dirty {
    padding-bottom: 5rem;
  }

  .dealers-detail__save-float {
    bottom: max(4.75rem, calc(4.75rem + env(safe-area-inset-bottom, 0px)));
    right: max(0.65rem, env(safe-area-inset-right, 0px));
  }
}

.dealers-detail__hero {
  display: block;
}

.dealers-detail__hero-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.65rem;
  min-width: 0;
}

.dealers-detail__hero-main {
  display: flex;
  align-items: flex-start;
  gap: 0.85rem;
  flex: 1;
  min-width: 0;
}

.dealers-detail__avatar {
  position: relative;
  width: 3.25rem;
  height: 3.25rem;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 800;
  color: #fff;
  background: linear-gradient(145deg, #1e3a5f, #2563eb);
}

.dealers-detail__avatar-badge {
  position: absolute;
  right: -0.1rem;
  bottom: -0.1rem;
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 999px;
  background: #059669;
  color: #fff;
  font-size: 0.625rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid rgba(15, 23, 42, 0.9);
}

.dealers-detail__hero-body {
  min-width: 0;
}

.dealers-detail__hero-title {
  margin: 0;
  font-size: 1rem;
  font-weight: 800;
  line-height: 1.25;
  word-break: break-word;
}

.dealers-detail__hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-top: 0.35rem;
}

.dealers-detail__badge {
  display: inline-flex;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
  font-size: 0.5625rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.dealers-detail__badge--auth {
  background: rgba(16, 185, 129, 0.15);
  color: #6ee7b7;
  border: 1px solid rgba(16, 185, 129, 0.35);
}

.dealers-detail__badge--active {
  background: rgba(59, 130, 246, 0.12);
  color: #93c5fd;
}

.dealers-detail__badge--inactive {
  background: rgba(148, 163, 184, 0.15);
  color: #cbd5e1;
}

.dealers-detail__hero-id {
  margin: 0.35rem 0 0;
  font-size: 0.6875rem;
  color: var(--text-muted);
}

.dealers-detail__hero-meta {
  margin: 0.2rem 0 0;
  font-size: 0.75rem;
  color: var(--text-secondary);
  line-height: 1.35;
}

.dealers-detail__hero-status {
  flex-shrink: 0;
  margin-top: 0.05rem;
}

.dealers-detail__hero-status.dealers-status-indicator {
  justify-content: flex-end;
}

.dealers-detail__hero-status .dealers-status-indicator__text {
  align-items: flex-end;
  text-align: right;
}

.dealers-detail__zoho-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.55rem 0.85rem;
}

.dealers-detail__zoho-field {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}

.dealers-detail__zoho-label {
  font-size: 0.625rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.dealers-detail__zoho-value {
  font-size: 0.8125rem;
  color: var(--text-primary);
  word-break: break-word;
}

.dealers-detail__zoho-readout {
  margin: 0.15rem 0 0;
  font-size: 0.9375rem;
  font-weight: 700;
  color: #fca5a5;
}

.dealers-detail__section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 0.75rem;
}

.dealers-detail__section-head .dealers-detail__section-title {
  margin: 0;
}

.dealers-detail__section-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.dealers-detail__zoho-field--block {
  grid-column: 1 / -1;
}

.dealers-detail__zoho-block {
  margin: 0.15rem 0 0;
  font-size: 0.8125rem;
  color: var(--text-primary);
  line-height: 1.45;
  white-space: pre-wrap;
  word-break: break-word;
}

.dealers-detail__zoho-addresses {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
  margin-top: 0.85rem;
  padding-top: 0.85rem;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
}

.dealers-detail__zoho-notes {
  margin-top: 0.75rem;
  padding-top: 0.75rem;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
}

.dealers-detail__zoho-grid--compact {
  margin-top: 0.35rem;
}

.dealers-detail__contact-persons {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.dealers-detail__contact-person {
  padding: 0.65rem 0.75rem;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.35);
  border: 1px solid rgba(148, 163, 184, 0.12);
}

.dealers-detail__contact-person-head {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.35rem;
  font-size: 0.875rem;
}

.dealers-detail__tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.dealers-detail__tag {
  font-size: 0.6875rem;
  padding: 0.2rem 0.5rem;
  border-radius: 999px;
  background: rgba(59, 130, 246, 0.12);
  color: #93c5fd;
  border: 1px solid rgba(59, 130, 246, 0.25);
}

.dealers-detail__textarea {
  resize: vertical;
  min-height: 4.5rem;
}

.dealers-detail__link-field {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.dealers-detail__link-field .input-field {
  flex: 1;
  min-width: 0;
}

.dealers-detail__link-open {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 8px;
  color: var(--accent-primary-light);
  background: rgba(59, 130, 246, 0.12);
}

.dealers-detail__portal {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.55rem;
}

.dealers-detail__portal-empty {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.55rem;
}

.dealers-detail__toggles {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  margin-bottom: 0.75rem;
}

.dealers-detail__toggle {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.8125rem;
}

.dealers-detail__toggle-btn {
  position: relative;
  width: 2.5rem;
  height: 1.35rem;
  border-radius: 999px;
  border: 1px solid var(--border-glass);
  background: rgba(255, 255, 255, 0.08);
  cursor: pointer;
  transition: background 0.15s ease;
  flex-shrink: 0;
}

.dealers-detail__toggle-btn--on {
  background: rgba(245, 130, 32, 0.55);
  border-color: rgba(245, 130, 32, 0.65);
}

.dealers-detail__toggle-knob {
  position: absolute;
  top: 0.12rem;
  left: 0.12rem;
  width: 1rem;
  height: 1rem;
  border-radius: 999px;
  background: #fff;
  transition: transform 0.15s ease;
}

.dealers-detail__toggle-btn--on .dealers-detail__toggle-knob {
  transform: translateX(1.1rem);
}

.dealers-detail__field--limit {
  max-width: 14rem;
}

.dealers-detail__action-stack {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.dealers-detail__action--warn {
  border-color: rgba(251, 146, 60, 0.45);
  color: #fdba74;
}

.dealers-detail__action--delete {
  width: 100%;
  flex: none;
  min-height: 0;
  padding: 0.7rem 1.2rem;
  font-weight: 700;
  background: var(--accent-primary, #f58220);
  border-color: var(--accent-primary, #f58220);
  color: #111827;
}

.dealers-detail__actions-row .dealers-detail__action--delete {
  flex: none;
}

.dealers-detail__pager {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  position: sticky;
  bottom: 0.5rem;
  z-index: 5;
}

@media (max-width: 640px) {
  .dealers-detail__form {
    grid-template-columns: 1fr;
  }

  .dealers-detail__hero-top {
    gap: 0.45rem;
  }

  .dealers-detail__zoho-grid,
  .dealers-detail__portal {
    grid-template-columns: 1fr;
  }

  .dealers-detail__data-row {
    grid-template-columns: 1fr;
    gap: 0.35rem;
  }
}

.dealers-bulk-bar {
  position: fixed;
  bottom: 1.25rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 40;
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.65rem 0.85rem;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.28);
}

.dealers-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(4px);
}

.dealers-modal {
  width: min(100%, 420px);
  padding: 1.1rem;
}

.dealers-modal__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.dealers-modal__header h2 {
  margin: 0;
  font-size: 1.05rem;
}

.dealers-modal__close {
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
}

.mark-invoiced-guide-dialog {
  max-width: 32rem;
}

.mark-invoiced-guide-dialog__title-row {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
}

.mark-invoiced-guide-dialog__icon {
  flex-shrink: 0;
  color: #fcd34d;
  margin-top: 0.1rem;
}

.mark-invoiced-guide-dialog__body {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.mark-invoiced-guide-dialog__error {
  margin: 0;
  padding: 0.65rem 0.75rem;
  border-radius: 8px;
  background: rgba(248, 113, 113, 0.12);
  color: #fca5a5;
  font-size: 0.875rem;
}

.mark-invoiced-guide-dialog__lead {
  margin: 0;
  font-size: 0.875rem;
}

.mark-invoiced-guide-dialog__steps {
  margin: 0;
  padding-left: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  font-size: 0.875rem;
}

.mark-invoiced-guide-dialog__actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 0.25rem;
}

.dealers-modal__form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.dealers-modal__field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  font-size: 0.8125rem;
}

.dealers-modal__field > span {
  color: #fdba74;
  font-weight: 650;
}

.dealers-modal__field input {
  padding: 0.5rem 0.65rem;
  border-radius: 8px;
  border: 1px solid var(--border-glass);
  background: var(--bg-input, rgba(15, 23, 42, 0.4));
  color: #fff;
}

.dealers-modal__pw {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.dealers-modal__pw input {
  flex: 1;
}

.dealers-modal__pw-toggle {
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
}

.dealers-modal__error {
  margin: 0;
  font-size: 0.8125rem;
  color: #fca5a5;
}

.dealer-create-public {
  min-height: 100vh;
