.dealers-create-phone-hint {
  margin: -0.15rem 0 0;
  font-size: 0.75rem;
  color: var(--text-muted);
}

.dealers-create-phone {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.dealers-create-phone input {
  flex: 1;
  min-width: 0;
}

.dealers-create-phone__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.05rem;
  height: 2.05rem;
