}

.invoices-page__scroll {
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  overflow-x: hidden;
  overflow-y: auto;
  overflow-anchor: none;
  overscroll-behavior: contain;
  /* Overlay scrollbar: invisible at rest, thin thumb only while scrolling / hover */
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
  -ms-overflow-style: auto;
}

.invoices-page__scroll::-webkit-scrollbar {
  width: 4px;
  height: 4px;
  background: transparent;
}

.invoices-page__scroll::-webkit-scrollbar-track {
