  scrollbar-color: rgba(255, 255, 255, 0.28) transparent;
}

.invoices-page__scroll.is-scrolling::-webkit-scrollbar-thumb,
.invoices-page__scroll:hover::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.28);
}

