}

.invoices-pagination--sticky {
  position: sticky;
  bottom: 0;
  z-index: 28;
  margin-bottom: 0;
  background: #0f1319;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: none;
}

.invoices-pagination--top {
  margin-bottom: 0.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.invoices-pagination__btns {
