}

@media (max-width: 768px) {
  .main-content:has(.invoices-page) {
    display: flex;
    flex-direction: column;
    height: 100dvh;
    max-height: 100dvh;
    overflow: hidden;
  }

  .main-content:has(.invoices-page):has(.top-bar--compact-search) {
    --header-height: 52px;
  }

  .main-content:has(.invoices-page):has(.top-bar--compact-search) .top-bar--compact-search {
    height: var(--header-height);
    min-height: var(--header-height);
    padding-top: 0;
    padding-bottom: 0;
  }

  .content-area:has(.invoices-page) {
    display: flex;
    flex-direction: column;
    flex: 1 1 auto;
    min-height: 0;
    overflow: hidden;
    padding: 0 0 max(0.5rem, env(safe-area-inset-bottom, 0px));
  }

  .content-area:has(.invoices-page) > .page-content.invoices-page {
    display: flex;
    flex-direction: column;
    flex: 1 1 auto;
    min-height: 0;
    overflow: hidden;
  }

  .invoices-page {
    --invoices-pad: max(0.85rem, env(safe-area-inset-left, 0px));
    padding-right: 0;
  }

  .invoices-summary {
    margin-top: 0;
    margin-bottom: 0.35rem;
    margin-right: max(0.85rem, env(safe-area-inset-right, 0px));
    padding-top: 0.25rem;
  }

  .invoices-page__scroll {
    overflow-x: hidden;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;
    padding-bottom: 0.5rem;
    padding-left: 0;
    padding-right: 0;
  }

  .invoices-page:has(.invoices-pagination--sticky) .invoices-page__scroll {
    padding-bottom: calc(var(--invoices-pagination-height) + env(safe-area-inset-bottom, 0px));
  }

  .invoices-page__body {
    padding-top: 0.15rem;
    padding-left: 0;
    padding-right: 0;
    padding-bottom: 0.5rem;
  }

  .invoices-page__error {
    margin: 0.35rem var(--invoices-pad) 0;
  }

  .invoices-table-wrap--desktop {
    display: none;
  }

  .invoices-mobile-list {
    display: flex;
  }

  .invoices-pagination--top {
    display: none;
  }

  .invoices-pagination--sticky {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    margin: 0;
    padding: 0.45rem var(--invoices-pad) max(0.45rem, env(safe-area-inset-bottom, 0px));
    padding-right: max(0.75rem, env(safe-area-inset-right, 0px));
    background: #0f1319;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: none;
  }

  .invoices-page:has(.invoices-pagination--sticky) .invoices-page__body {
    padding-bottom: calc(var(--invoices-pagination-height) + env(safe-area-inset-bottom, 0px));
  }

  .invoices-pagination__info {
    font-size: 0.72rem;
  }

  .invoices-pagination .btn-sm {
    padding: 0.35rem 0.65rem;
    font-size: 0.75rem;
  }
}

@media (max-width: 380px) {
  .invoices-mobile-row__amount {
    max-width: 46%;
  }

  .invoices-mobile-row__amount strong {
    font-size: 0.75rem;
  }
}

@media (min-width: 769px) {
  .invoices-summary {
    margin-bottom: 1rem;
  }

  .invoices-summary__kpis {
    max-width: 36rem;
  }

  .invoices-summary__controls {
    max-width: 36rem;
  }

  .invoices-mobile-list {
    display: none;
  }

  .invoices-page__body {
    padding: 0.625rem var(--invoices-pad) 1rem;
  }

  .invoices-pagination--sticky {
    position: static;
    box-shadow: none;
    border-top: none;
  }

  .invoices-filter-sheet {
    align-items: center;
  }

  .invoices-filter-sheet__panel {
    border-radius: 16px;
    max-height: min(70vh, 28rem);
  }
}

/* Admin invoices reuses mobile list/summary; keep visible until 900px. */
@media (max-width: 900px) {
  .admin-invoices-page .invoices-mobile-list {
    display: flex;
    flex-direction: column;
  }

  .admin-invoices-page .invoices-summary {
    max-width: none;
  }

  .admin-invoices-page .invoices-summary__kpis,
  .admin-invoices-page .invoices-summary__controls {
    max-width: none;
  }
}

