  border: none;
  outline: none;
  background: transparent;
  color: inherit;
  font: inherit;
}

.support-dealer-picker__options {
  list-style: none;
  margin: 0;
  padding: 0.35rem;
  max-height: 14rem;
  overflow-y: auto;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.support-dealer-picker__option {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.5rem 0.55rem;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.support-dealer-picker__option:hover,
.support-dealer-picker__option.is-selected {
  background: rgba(245, 130, 32, 0.1);
  border-color: rgba(245, 130, 32, 0.25);
}

.support-dealer-picker__option-icon {
  width: 2.25rem;
  height: 2.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}

.support-dealer-picker__option-body {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  min-width: 0;
}

.support-dealer-picker__empty {
  padding: 0.65rem 0.75rem;
}

.support-dealer-picker__meta {
  margin: 0;
}

.support-dealer-picker__option-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.45rem;
  min-width: 0;
}

.support-dealer-picker__option-head strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.support-dealer-picker__option-badge {
  flex-shrink: 0;
  padding: 0.12rem 0.45rem;
  border-radius: 999px;
  font-size: 0.625rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.support-dealer-picker__option-badge.is-registered {
  color: #86efac;
  background: rgba(34, 197, 94, 0.12);
  border: 1px solid rgba(34, 197, 94, 0.28);
}

.support-dealer-picker__option-badge.is-unregistered {
  color: rgba(255, 255, 255, 0.55);
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.support-dealer-picker__status {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 0.75rem;
}

.support-dealer-picker__status--registered {
  border-color: rgba(34, 197, 94, 0.22);
  background: rgba(34, 197, 94, 0.05);
}

.support-dealer-picker__status--unregistered {
  border-color: rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.03);
}

.support-dealer-picker__status-head {
  display: flex;
  gap: 0.65rem;
  align-items: flex-start;
}

.support-dealer-picker__status-icon {
  flex-shrink: 0;
  margin-top: 0.1rem;
}

.support-dealer-picker__status--registered .support-dealer-picker__status-icon {
  color: #86efac;
}

.support-dealer-picker__status--unregistered .support-dealer-picker__status-icon {
  color: rgba(255, 255, 255, 0.45);
}

.support-dealer-picker__status-copy strong {
  display: block;
  margin-bottom: 0.15rem;
}

.support-dealer-picker__status-copy p {
  margin: 0;
  line-height: 1.4;
}

.support-dealer-picker__status-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 0.65rem;
}

.support-dealer-picker__status-loading {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.support-wizard__ops-note {
  margin: -0.25rem 0 0.5rem;
}

.support-invoice-detail {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  margin: 0.35rem 0 0.75rem;
}

.support-product-line {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  width: 100%;
  padding: 0.65rem;
  border-radius: 14px;
  border: 1px solid var(--border-glass, rgba(255, 255, 255, 0.12));
  background: rgba(255, 255, 255, 0.03);
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.support-invoice-field__menu .support-product-line {
  margin-top: 0.35rem;
  background: rgba(255, 255, 255, 0.04);
}

.support-product-line.is-static {
  cursor: default;
  margin-bottom: 0.75rem;
}

.support-product-line:hover:not(.is-static),
.support-product-line.is-selected {
  border-color: rgba(245, 130, 32, 0.55);
  background: rgba(245, 130, 32, 0.08);
}

.support-product-line__doc {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
}

.support-product-line__doc strong {
  font-size: 0.875rem;
  letter-spacing: 0.01em;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.support-product-line__row {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  width: 100%;
}

.support-product-line__thumb {
  flex-shrink: 0;
  width: 4.5rem;
  height: 4.5rem;
  border-radius: 12px;
  overflow: hidden;
  background: rgba(0, 0, 0, 0.25);
  display: flex;
  align-items: center;
  justify-content: center;
}

.support-product-line__image {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
}

.support-product-line__placeholder {
  color: var(--text-muted);
  opacity: 0.7;
  display: flex;
}

.support-product-line__body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.support-product-line__name {
  font-size: 0.875rem;
  font-weight: 700;
  line-height: 1.3;
}

.support-product-line__sku,
.support-product-line__qty,
.support-product-line__serials,
.support-product-line__hint,
.support-product-line__note {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.support-product-line__note {
  font-weight: 600;
  color: var(--text);
}

.support-product-line__serials,
.support-product-line__hint {
  line-height: 1.35;
}

.support-product-line__chevron {
  flex-shrink: 0;
  color: var(--text-muted);
  opacity: 0.85;
  align-self: center;
}

.support-product-line__next {
  flex-shrink: 0;
  align-self: center;
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}

.support-invoice-detail .invoice-detail-item__body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  column-gap: 0.75rem;
  row-gap: 0.15rem;
  align-items: baseline;
}

.support-invoice-detail .invoice-detail-item__name {
  grid-column: 1 / -1;
}

.support-invoice-detail .invoice-detail-item__sku::before {
  content: 'SKU ';
}

.support-invoice-detail .invoice-detail-item__pricing {
  margin-top: 0;
  justify-content: flex-end;
}

.support-invoice-detail .invoice-detail-item__next,
.support-invoice-detail .invoice-detail-item__freight-alert {
  grid-column: 1 / -1;
}

.support-invoice-detail .invoice-detail-item__desc {
  display: none;
}

.support-wizard__error {
  margin: 0;
  padding: 0.55rem 0.75rem;
  border-radius: 10px;
  background: rgba(239, 68, 68, 0.12);
  color: #fca5a5;
  font-size: 0.8125rem;
}

.support-wizard__upload-progress {
  flex: 1 1 100%;
  width: 100%;
  margin: 0 0 0.15rem;
  padding: 0.75rem 0.85rem !important;
  border: 1px solid rgba(245, 130, 32, 0.22);
  background: rgba(245, 130, 32, 0.06);
}

.support-wizard__upload-progress-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.55rem;
  font-size: 0.8125rem;
}

.support-wizard__upload-progress-label {
  color: var(--text-main);
  font-weight: 600;
}

.support-wizard__upload-progress-pct {
  color: var(--accent-primary-light);
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.support-wizard__upload-progress-track {
  height: 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.support-wizard__upload-progress-bar {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #f58220, #f5a623);
  transition: width 0.2s ease;
}

.support-wizard__upload-progress-bar.is-indeterminate {
  width: 42% !important;
  animation: support-upload-indeterminate 1.2s ease-in-out infinite;
}

@keyframes support-upload-indeterminate {
  0% {
    transform: translateX(-120%);
  }
  100% {
    transform: translateX(320%);
  }
}

.support-wizard__success-wrap {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.support-wizard__success-ticket {
  padding: 0 !important;
  overflow: hidden;
}

.support-wizard__success-ticket .support-request-ticket-info {
  border: none;
  border-radius: 0;
  background: transparent;
}

.support-wizard__success-ticket-error {
  margin: 0.75rem 0.85rem 0;
}

.support-wizard__success {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.65rem;
  padding: 1.5rem 1rem !important;
}

.support-wizard__request-number {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--accent-primary-light);
}

.support-courier-instructions {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.support-courier-instructions__approval {
  padding: 0.65rem 0.75rem;
  border-radius: 12px;
  border: 1px solid rgba(245, 130, 32, 0.25);
  background: rgba(245, 130, 32, 0.06);
}

.support-courier-instructions__approval strong {
  display: block;
  margin-bottom: 0.25rem;
}

.support-courier-instructions__address {
  padding: 0.85rem !important;
}

.support-courier-instructions__address-head {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin-bottom: 0.5rem;
}

.support-courier-instructions__address-head strong {
  flex: 1;
}

.support-courier-instructions__copy {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.25rem 0.5rem;
  border-radius: 8px;
  border: 1px solid var(--border-glass);
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-muted);
  font-size: 0.6875rem;
  font-weight: 600;
  cursor: pointer;
}

.support-courier-instructions__company {
  margin: 0;
  font-weight: 700;
}

.support-courier-instructions__dept {
  margin: 0.1rem 0 0.35rem;
}

.support-courier-instructions__line {
  margin: 0;
  font-size: 0.875rem;
  line-height: 1.45;
}

.support-courier-instructions__contact {
  margin: 0.45rem 0 0;
}

.support-courier-instructions__checklist-head {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin-bottom: 0.45rem;
}

.support-courier-instructions__list {
  margin: 0;
  padding-left: 1.15rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.4;
}

.support-courier-instructions--compact .support-courier-instructions__approval {
  font-size: 0.875rem;
}

/* -- Support chat ----------------------------------------------- */
.support-detail-page {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  max-width: 960px;
  margin: 0 auto;
}

.support-detail-page--chat {
  flex: 1;
  min-height: 0;
  height: 100%;
  overflow: hidden;
  gap: 0;
  max-width: none;
  margin: 0;
}

.support-detail-page--chat .support-detail-page__error,
.support-detail-page--chat .support-courier-instructions {
  flex-shrink: 0;
  margin-left: max(1rem, env(safe-area-inset-left, 0px));
  margin-right: max(1rem, env(safe-area-inset-right, 0px));
}

.support-detail-page--chat .support-detail-page__error {
  margin-top: max(0.75rem, env(safe-area-inset-top, 0px));
}

.support-detail-page--chat .support-courier-instructions {
  margin-top: 0.75rem;
  margin-bottom: 0.75rem;
}

.support-detail-page--chat .support-chat {
  flex: 1 1 auto;
  min-height: 0;
  height: auto;
  overflow: hidden;
}

.support-detail-page--with-tabs {
  --support-detail-tabs-height: 3.15rem;
  --support-detail-content-offset: var(--header-height);
}

.main-content:has(.top-bar .page-subtitle) .support-detail-page--with-tabs {
  --support-detail-content-offset: calc(var(--header-height) + 0.35rem);
}

.support-detail-page--with-tabs .support-detail-page__tab-panel {
  padding-top: calc(
    var(--support-detail-tabs-top, var(--header-height))
    + var(--support-detail-tabs-height)
    - var(--support-detail-content-offset)
  );
}

.support-detail-tabs {
  position: fixed;
  top: var(--support-detail-tabs-top, var(--header-height));
  left: var(--sidebar-width);
  right: 0;
  z-index: 35;
  display: flex;
  align-items: stretch;
  box-sizing: border-box;
  height: var(--support-detail-tabs-height);
  min-height: var(--support-detail-tabs-height);
  margin: 0;
  padding: 0.4rem max(0.75rem, env(safe-area-inset-left, 0px)) 0.45rem;
  padding-right: max(0.75rem, env(safe-area-inset-right, 0px));
  background: var(--bg-app);
  border-bottom: 1px solid var(--border-glass);
}

.main-content.expanded .support-detail-tabs {
  left: var(--sidebar-collapsed);
}

.support-detail-tabs__track {
  display: flex;
  align-items: stretch;
  width: 100%;
  gap: 0.35rem;
  padding: 0.2rem;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-glass);
}

.support-detail-tabs__btn {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  appearance: none;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: var(--text-muted);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 1.2;
  white-space: nowrap;
  padding: 0.5rem 0.75rem;
  margin: 0;
  cursor: pointer;
  outline: none;
  box-shadow: none;
  -webkit-tap-highlight-color: transparent;
  transition: color 0.15s ease, background 0.15s ease, border-color 0.15s ease;
}

.support-detail-tabs__btn:hover {
  color: var(--text-secondary);
}

.support-detail-tabs__btn.is-active {
  color: var(--accent-primary-light);
  background: rgba(245, 130, 32, 0.14);
  border-color: rgba(245, 130, 32, 0.38);
}

.support-detail-tabs__btn:focus-visible {
  outline: 2px solid rgba(245, 130, 32, 0.45);
  outline-offset: 1px;
}

.support-detail-tabs__track--three .support-detail-tabs__btn {
  font-size: 0.75rem;
  padding: 0.48rem 0.35rem;
}

.support-detail-page__tab-panel {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.support-detail-page__tab-panel--flow {
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
}

.support-detail-page--with-tabs .support-chat {
  flex: 1 1 auto;
  min-height: 0;
  height: auto;
  overflow: hidden;
}

.support-detail-page--with-tabs .support-chat__body {
  flex: 1 1 auto;
  min-height: 12rem;
}

.support-detail-page--with-tabs .support-chat__thread {
  min-height: 10rem;
}

.support-detail-page--with-tabs .support-detail-page__error,
.support-detail-page--with-tabs .support-courier-instructions {
  flex-shrink: 0;
  margin-left: max(1rem, env(safe-area-inset-left, 0px));
  margin-right: max(1rem, env(safe-area-inset-right, 0px));
}

.support-detail-page--with-tabs .support-courier-instructions {
  margin-top: 0.75rem;
  margin-bottom: 0.75rem;
}

.support-ticket-flow {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0.85rem max(1rem, env(safe-area-inset-left, 0px)) 1.25rem;
  padding-right: max(1rem, env(safe-area-inset-right, 0px));
  padding-bottom: max(1.25rem, env(safe-area-inset-bottom, 0px));
}

.support-ticket-flow__progress-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.15rem 0.1rem 0.35rem;
}

.support-ticket-flow__progress-title {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  color: rgba(255, 255, 255, 0.92);
}

.support-ticket-flow__progress-title h3 {
  margin: 0;
  font-size: 1rem;
  font-weight: 700;
}

.support-ticket-flow__reopen-count {
  display: inline-flex;
  align-items: center;
  min-height: 1.35rem;
  padding: 0.12rem 0.45rem;
  border-radius: 999px;
  border: 1px solid rgba(251, 146, 60, 0.35);
  background: rgba(245, 130, 32, 0.14);
  color: #fdba74;
  font-size: 0.66rem;
  font-weight: 750;
  letter-spacing: 0.02em;
}

.support-ticket-flow__current {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.25rem;
  text-align: right;
}

.support-ticket-flow__current-label {
  margin: 0;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.support-ticket-flow__current-badge {
  display: inline-flex;
  align-items: center;
  max-width: 11rem;
  padding: 0.2rem 0.55rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  line-height: 1.25;
  color: var(--accent-primary-light);
  background: rgba(245, 130, 32, 0.14);
  border: 1px solid rgba(245, 130, 32, 0.38);
}

.support-ticket-flow__timeline {
  list-style: none;
  margin: 0;
  padding: 0.85rem 0.95rem 0.95rem;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.support-ticket-flow__step {
  display: grid;
  grid-template-columns: 2.5rem minmax(0, 1fr) auto;
  gap: 0.55rem 0.75rem;
  padding-bottom: 1.25rem;
}

.support-ticket-flow__step--last {
  padding-bottom: 0;
}

.support-ticket-flow__rail {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100%;
}

.support-ticket-flow__icon {
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  border: 2px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.04);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: rgba(255, 255, 255, 0.55);
}

.support-ticket-flow__line {
  flex: 1;
  width: 0;
  min-height: 1.35rem;
  margin-top: 0.35rem;
  border-left: 2px dashed rgba(255, 255, 255, 0.14);
}

.support-ticket-flow__step--tone-green.support-ticket-flow__step--complete .support-ticket-flow__icon,
.support-ticket-flow__step--tone-green.support-ticket-flow__step--current .support-ticket-flow__icon {
  border-color: #22c55e;
  background: rgba(34, 197, 94, 0.18);
  color: #4ade80;
}

.support-ticket-flow__step--tone-blue.support-ticket-flow__step--complete .support-ticket-flow__icon,
.support-ticket-flow__step--tone-blue.support-ticket-flow__step--current .support-ticket-flow__icon {
  border-color: #3b82f6;
  background: rgba(59, 130, 246, 0.18);
  color: #60a5fa;
}

.support-ticket-flow__step--tone-purple.support-ticket-flow__step--complete .support-ticket-flow__icon,
.support-ticket-flow__step--tone-purple.support-ticket-flow__step--current .support-ticket-flow__icon {
  border-color: #a855f7;
  background: rgba(168, 85, 247, 0.18);
  color: #c084fc;
}

.support-ticket-flow__step--tone-orange.support-ticket-flow__step--complete .support-ticket-flow__icon,
.support-ticket-flow__step--tone-orange.support-ticket-flow__step--current .support-ticket-flow__icon {
  border-color: #f97316;
  background: rgba(249, 115, 22, 0.18);
  color: #fb923c;
}

.support-ticket-flow__step--tone-teal.support-ticket-flow__step--complete .support-ticket-flow__icon,
.support-ticket-flow__step--tone-teal.support-ticket-flow__step--current .support-ticket-flow__icon {
  border-color: #14b8a6;
  background: rgba(20, 184, 166, 0.18);
  color: #2dd4bf;
}

.support-ticket-flow__step--tone-amber.support-ticket-flow__step--complete .support-ticket-flow__icon,
.support-ticket-flow__step--tone-amber.support-ticket-flow__step--current .support-ticket-flow__icon {
  border-color: #eab308;
  background: rgba(234, 179, 8, 0.18);
  color: #facc15;
}

.support-ticket-flow__step--tone-green.support-ticket-flow__step--complete .support-ticket-flow__icon {
  background: #22c55e;
  color: #fff;
}

.support-ticket-flow__step--tone-blue.support-ticket-flow__step--complete .support-ticket-flow__icon,
.support-ticket-flow__step--tone-purple.support-ticket-flow__step--complete .support-ticket-flow__icon,
