  overflow: hidden;
  background: #0a0f1a;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.evidence-media-slot--active .evidence-media-slot__frame {
  border-color: rgba(59, 130, 246, 0.45);
  box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.15);
}

.evidence-media-slot__media {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: #000;
}

.evidence-media-slot__placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.85rem;
  width: 100%;
  height: 100%;
  padding: 1rem;
  text-align: center;
}

.evidence-media-slot__open-camera {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 0.95rem;
  border: 1px solid rgba(59, 130, 246, 0.45);
  border-radius: 999px;
  background: rgba(59, 130, 246, 0.12);
  color: #93c5fd;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.evidence-media-slot__open-camera:hover:not(:disabled) {
  background: rgba(59, 130, 246, 0.2);
  border-color: rgba(96, 165, 250, 0.55);
}

.evidence-media-slot__open-camera:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.evidence-media-slot__toolbar {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: 4.5rem;
  padding: 0.75rem;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.72), transparent);
  pointer-events: none;
}

.evidence-media-slot__toolbar > * {
  pointer-events: auto;
}

.evidence-media-slot__pick {
  position: absolute;
  left: 0.75rem;
  bottom: 0.75rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.65rem;
  height: 2.65rem;
  border: none;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  cursor: pointer;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: background 0.15s ease, transform 0.15s ease;
}

.evidence-media-slot__pick:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.24);
}

.evidence-media-slot__pick--solo {
  position: static;
}

.evidence-media-slot__shutter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  cursor: pointer;
  transition: transform 0.12s ease;
}

.evidence-media-slot__shutter:active:not(:disabled) {
  transform: scale(0.94);
}

.evidence-media-slot__shutter--record {
  width: 3.35rem;
  height: 3.35rem;
  border-radius: 999px;
  border: 3px solid rgba(255, 255, 255, 0.92);
  background: transparent;
  padding: 0.2rem;
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.25);
}

.evidence-media-slot__shutter--record::after {
  content: '';
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 999px;
  background: #ef4444;
}

.evidence-media-slot__shutter--stop {
  width: 3.35rem;
  height: 3.35rem;
  border-radius: 999px;
  border: 3px solid rgba(255, 255, 255, 0.92);
  background: rgba(239, 68, 68, 0.92);
  color: #fff;
}

.evidence-media-slot__shutter--photo {
  width: 3.35rem;
  height: 3.35rem;
  border-radius: 999px;
  border: 3px solid rgba(255, 255, 255, 0.92);
  background: #fff;
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.25);
}

.evidence-media-slot__recording-badge {
  position: absolute;
  top: 0.65rem;
  left: 0.65rem;
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.25rem 0.55rem;
  border-radius: 999px;
  background: rgba(239, 68, 68, 0.92);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  z-index: 2;
}

.evidence-media-slot__remove {
  position: absolute;
  top: 0.55rem;
  right: 0.55rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.85rem;
  height: 1.85rem;
  border: none;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.68);
  color: #fff;
  cursor: pointer;
  z-index: 2;
}

.evidence-media-slot__gps {
  position: absolute;
  left: 0.55rem;
  bottom: 0.55rem;
