  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
}

.staff-management-page__dept-badge--blue { background: rgba(96, 165, 250, 0.15); color: #93c5fd; }
.staff-management-page__dept-badge--green { background: rgba(52, 211, 153, 0.15); color: #6ee7b7; }
.staff-management-page__dept-badge--orange { background: rgba(251, 146, 60, 0.15); color: #fdba74; }
.staff-management-page__dept-badge--purple { background: rgba(167, 139, 250, 0.15); color: #c4b5fd; }

.staff-management-page__status {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  color: #34d399;
}

.staff-management-page__status.is-inactive {
  color: #f87171;
}

.staff-management-page__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 0.65rem;
  color: var(--text-muted, #94a3b8);
}

.staff-management-page__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.staff-management-page__chip {
  font-size: 0.6875rem;
  padding: 0.2rem 0.45rem;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.12);
  color: var(--text-muted, #94a3b8);
  text-transform: capitalize;
}

.staff-management-page__card-actions {
  display: flex;
  gap: 0.35rem;
  margin-top: 0.25rem;
  flex-wrap: wrap;
}

.staff-management-page__delete {
  color: #f87171;
}

.staff-role-editor {
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}

.staff-role-editor__section {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.staff-role-editor__heading {
  margin: 0;
  font-size: 0.9rem;
}

.staff-role-editor__hint {
  margin: 0;
}

.staff-role-editor__optional {
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 12px;
  padding: 0.65rem 0.85rem;
  background: rgba(15, 23, 42, 0.28);
}

.staff-role-editor__optional > summary {
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted, #94a3b8);
  list-style: none;
}

.staff-role-editor__optional > summary::-webkit-details-marker {
  display: none;
}

.staff-role-editor__optional[open] > summary {
  margin-bottom: 0.65rem;
}

.staff-role-editor__zoho-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  gap: 0.75rem;
  margin-bottom: 0.5rem;
}

.staff-role-editor__zoho-picker {
  position: relative;
  margin-bottom: 0.5rem;
}

.staff-role-editor__zoho-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  list-style: none;
  margin: 0 0 0.65rem;
  padding: 0;
}

.staff-role-editor__zoho-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  max-width: 100%;
  padding: 0.3rem 0.45rem 0.3rem 0.65rem;
  border-radius: 999px;
  border: 1px solid rgba(249, 115, 22, 0.35);
  background: rgba(249, 115, 22, 0.12);
  font-size: 0.82rem;
}

.staff-role-editor__zoho-chip-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 600;
}

.staff-role-editor__zoho-chip-remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.25rem;
  height: 1.25rem;
  border: 0;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.35);
  color: inherit;
  cursor: pointer;
  flex-shrink: 0;
}

.staff-role-editor__zoho-chip-remove:hover {
  background: rgba(15, 23, 42, 0.55);
}

.staff-role-editor__zoho-search {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.45);
  padding: 0 0.55rem;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.staff-role-editor__zoho-search.is-open,
.staff-role-editor__zoho-search:focus-within {
  border-color: rgba(249, 115, 22, 0.55);
  box-shadow: 0 0 0 2px rgba(249, 115, 22, 0.12);
}

.staff-role-editor__zoho-search-icon,
.staff-role-editor__zoho-spinner {
  flex-shrink: 0;
  color: rgba(148, 163, 184, 0.85);
}

.staff-role-editor__zoho-search-input {
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  padding-left: 0.15rem !important;
  padding-right: 0.15rem !important;
}

.staff-role-editor__zoho-clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgba(148, 163, 184, 0.9);
  cursor: pointer;
}

.staff-role-editor__zoho-clear:hover {
  color: #f8fafc;
  background: rgba(148, 163, 184, 0.15);
}

.staff-role-editor__zoho-options {
  position: absolute;
  z-index: 20;
  left: 0;
  right: 0;
  top: calc(100% + 0.3rem);
  max-height: 16rem;
  overflow: auto;
  margin: 0;
  padding: 0.35rem;
  list-style: none;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.96);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.35);
}

.staff-role-editor__zoho-option-empty {
  padding: 0.65rem 0.75rem;
}

.staff-role-editor__zoho-option {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.1rem;
  width: 100%;
  padding: 0.55rem 0.7rem;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.staff-role-editor__zoho-option.is-active,
.staff-role-editor__zoho-option:hover {
  background: rgba(249, 115, 22, 0.12);
}

.staff-role-editor__zoho-option.is-selected {
  background: rgba(249, 115, 22, 0.18);
}

.staff-role-editor__zoho-option.is-inactive .staff-role-editor__zoho-option-name {
  opacity: 0.75;
}

.staff-role-editor__zoho-option.is-claimed {
  opacity: 0.72;
  cursor: not-allowed;
}

.staff-role-editor__zoho-option-name {
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  flex-wrap: wrap;
}

.staff-role-editor__zoho-option-badge {
  display: inline-block;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  padding: 0.1rem 0.35rem;
  border-radius: 0.25rem;
  background: rgba(34, 197, 94, 0.18);
  color: #86efac;
}

.staff-role-editor__zoho-option.is-claimed .staff-role-editor__zoho-option-badge {
  background: rgba(148, 163, 184, 0.2);
  color: #cbd5e1;
}

.staff-role-editor__zoho-option-meta {
  display: block;
  margin-top: 0.15rem;
}

.staff-role-editor__zoho-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 0.75rem;
  margin-top: 0.35rem;
}

.staff-role-editor__zoho-footer .staff-role-editor__hint {
  margin: 0;
}

.staff-role-editor__zoho-refresh {
  border: 0;
  background: transparent;
  color: rgba(251, 146, 60, 0.95);
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  padding: 0.15rem 0;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.staff-role-editor__zoho-refresh:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}


.staff-role-editor__departments {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr));
  gap: 0.65rem;
}

.staff-role-editor__dept {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.35rem;
  padding: 0.85rem 0.9rem;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(15, 23, 42, 0.35);
  cursor: pointer;
  text-align: left;
  transition: border-color 0.15s, background 0.15s;
}

.staff-role-editor__dept:hover {
  border-color: rgba(148, 163, 184, 0.35);
}

.staff-role-editor__dept.is-active {
  border-color: rgba(99, 102, 241, 0.55);
  background: rgba(99, 102, 241, 0.08);
}

.staff-role-editor__dept--blue.is-active { border-color: rgba(96, 165, 250, 0.55); background: rgba(96, 165, 250, 0.08); }
.staff-role-editor__dept--green.is-active { border-color: rgba(52, 211, 153, 0.55); background: rgba(52, 211, 153, 0.08); }
.staff-role-editor__dept--orange.is-active { border-color: rgba(251, 146, 60, 0.55); background: rgba(251, 146, 60, 0.08); }
.staff-role-editor__dept--purple.is-active { border-color: rgba(167, 139, 250, 0.55); background: rgba(167, 139, 250, 0.08); }

.staff-role-editor__dept-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 10px;
  background: rgba(148, 163, 184, 0.1);
}

.staff-role-editor__dept-label {
  font-weight: 600;
  font-size: 0.875rem;
}

.staff-role-editor__dept-desc {
  font-size: 0.75rem;
  color: var(--text-muted, #94a3b8);
  line-height: 1.35;
}

.staff-role-editor__field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.staff-role-editor__field span {
  font-size: 0.8125rem;
  color: var(--text-muted, #94a3b8);
}

.staff-role-editor__perm-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.staff-role-editor__customize {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.8125rem;
  white-space: nowrap;
  cursor: pointer;
}

.staff-role-editor__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.staff-role-editor__chip {
  font-size: 0.75rem;
  padding: 0.3rem 0.55rem;
  border-radius: 999px;
  background: rgba(99, 102, 241, 0.12);
  color: #c7d2fe;
}

.staff-role-editor__groups {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  gap: 0.65rem;
}

.staff-role-editor__group {
  padding: 0.75rem 0.85rem;
}

.staff-role-editor__group h5 {
  margin: 0 0 0.5rem;
  font-size: 0.8125rem;
  color: var(--text-muted, #94a3b8);
}

.staff-role-editor__perm-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.staff-role-editor__perm {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.45rem 0.55rem;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.12);
  background: transparent;
  cursor: pointer;
  text-align: left;
  font-size: 0.8125rem;
  transition: background 0.12s, border-color 0.12s;
}

.staff-role-editor__perm:hover {
  background: rgba(148, 163, 184, 0.06);
}

.staff-role-editor__perm.is-on {
  border-color: rgba(99, 102, 241, 0.35);
  background: rgba(99, 102, 241, 0.08);
}

.staff-role-editor__perm-check {
  width: 0.95rem;
  height: 0.95rem;
  border-radius: 4px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  flex-shrink: 0;
}

.staff-role-editor__perm.is-on .staff-role-editor__perm-check {
  background: #6366f1;
  border-color: #6366f1;
  box-shadow: inset 0 0 0 2px rgba(15, 23, 42, 0.85);
}

.staff-role-editor__perm-label {
  flex: 1;
}

.staff-role-editor__perm-badge {
  font-size: 0.625rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted, #94a3b8);
}

.staff-role-editor__preview {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.65rem 0.85rem;
  font-size: 0.8125rem;
  color: var(--text-muted, #94a3b8);
}

.staff-kam-scope-banner {
  padding: 0.65rem 1rem;
  border-left: 3px solid #60a5fa;
}

@media (max-width: 900px) {
  .staff-management-page__form-grid {
    grid-template-columns: 1fr;
  }

  .staff-role-editor__departments {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 560px) {
  .staff-role-editor__departments {
    grid-template-columns: 1fr;
  }
}

/* Dealer portal access editor */
.dealer-role-editor,
.user-management__access {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.user-management__access {
  padding: 1rem 1.15rem;
}

.user-management__access-title {
  margin: 0 0 0.25rem;
  font-size: 0.95rem;
}

.user-management__tier {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
}

.user-management__tier--standard {
  background: rgba(96, 165, 250, 0.15);
  color: #93c5fd;
}

.user-management__tier--director {
  background: rgba(167, 139, 250, 0.15);
  color: #c4b5fd;
}

.user-management__editor .inline-form-panel {
  margin-bottom: 0;
}

.user-management__save-notice {
  padding: 0.65rem 0.9rem;
  border-radius: 0.5rem;
  border: 1px solid rgba(16, 185, 129, 0.35);
  background: rgba(16, 185, 129, 0.12);
  color: #6ee7b7;
  font-size: 0.875rem;
}

.user-management__row--clickable {
  cursor: pointer;
}

.user-management__row--clickable:hover td {
  background: rgba(255, 255, 255, 0.04);
}

.user-management__row--highlighted td {
  animation: user-management-row-highlight 4.5s ease-out forwards;
}

@keyframes user-management-row-highlight {
  0% {
    background: rgba(16, 185, 129, 0.28);
    box-shadow: inset 3px 0 0 #10b981;
  }
  70% {
    background: rgba(16, 185, 129, 0.12);
    box-shadow: inset 3px 0 0 #10b981;
  }
  100% {
    background: transparent;
    box-shadow: none;
  }
}

.dealer-team {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 0.75rem 0.9rem 1.25rem;
}

.dealer-team__add-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin-left: 0;
  white-space: nowrap;
}

.dealer-team__form {
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 0.9rem;
  max-width: 26.5rem;
  width: 100%;
  margin: 0 auto;
  padding: 0;
  min-height: 0;
  overflow: auto;
  -webkit-overflow-scrolling: touch;
}

.dealer-team__backdrop {
  align-items: stretch;
  justify-content: stretch;
  padding: 0;
  z-index: 80;
  background: var(--bg-app);
  backdrop-filter: none;
}

.dealer-team__dialog.dealers-modal {
  width: 100%;
  max-width: none;
  height: 100%;
  max-height: none;
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: calc(0.55rem + env(safe-area-inset-top, 0px)) 1rem calc(0.7rem + env(safe-area-inset-bottom, 0px));
  border-radius: 0;
  border: none;
  background: var(--bg-app);
  box-shadow: none;
}

.dealer-team__dialog .dealers-modal__header {
  margin: 0 auto 0.85rem;
  padding-bottom: 0.7rem;
  max-width: 26.5rem;
  width: 100%;
  border-bottom: 1px solid rgba(148, 163, 184, 0.12);
  flex-shrink: 0;
  align-items: center;
}

.dealer-team__dialog .dealers-modal__header h2 {
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.dealer-team__subtitle {
  margin: 0.15rem 0 0;
  font-size: 0.78rem;
  font-weight: 600;
  color: #94a3b8;
}

.dealer-team__dialog .dealers-modal__close {
  width: 2.15rem;
  height: 2.15rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
}

.dealer-team__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  padding: 2rem 1rem;
  text-align: center;
  color: var(--text-muted);
}

.dealer-team__empty p {
  margin: 0;
  font-size: 0.9rem;
}

.dealer-team__avatar {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4rem;
  margin: 0.1rem 0 0.25rem;
  cursor: pointer;
}

.dealer-team__avatar-img,
.dealer-team__avatar-empty {
  width: 5.5rem;
  height: 5.5rem;
  border-radius: 50%;
  display: block;
}

.dealer-team__avatar-img {
  object-fit: cover;
  border: 2px solid rgba(245, 130, 32, 0.45);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

.dealer-team__avatar-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  color: #94a3b8;
  background:
    radial-gradient(circle at 30% 20%, rgba(245, 130, 32, 0.16), transparent 55%),
    rgba(15, 23, 42, 0.75);
  border: 1.5px dashed rgba(148, 163, 184, 0.38);
}

.dealer-team__avatar-cam {
  position: absolute;
  top: 3.85rem;
  left: calc(50% + 1.35rem);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-primary), var(--accent-primary-light));
  color: #1a0a00;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
  pointer-events: none;
}

.dealer-team__avatar-hint {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #94a3b8;
}

.dealer-team__levels {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.dealer-team__level {
  margin: 0;
  min-height: 2.55rem;
  padding: 0.45rem 0.5rem;
  border-radius: 0.75rem;
  border: 1px solid var(--border-glass);
  background: rgba(0, 0, 0, 0.25);
  color: #e2e8f0;
  font-size: 0.875rem;
  font-weight: 750;
  cursor: pointer;
}

.dealer-team__level:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.dealer-team__level.is-on {
  border-color: var(--accent-primary);
  background: linear-gradient(135deg, var(--accent-primary), var(--accent-primary-light));
  color: #1a0a00;
}

.dealer-team__field-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
}

.dealer-team__age {
  min-width: 3.2rem;
  padding: 0.12rem 0.4rem;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.12);
  color: #94a3b8;
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  text-align: center;
  text-transform: none;
}

.dealer-team__age.is-on {
  background: rgba(245, 130, 32, 0.18);
  color: #fdba74;
}

.dealer-team__field {
  display: flex;
  flex-direction: column;
  gap: 0.32rem;
  min-width: 0;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #94a3b8;
}

.dealer-team__field .input-field {
  min-width: 0;
  min-height: 2.55rem;
  padding: 0.5rem 0.72rem;
  border-radius: 0.75rem;
  font-size: 0.875rem;
  font-weight: 650;
  letter-spacing: 0;
  text-transform: none;
  color: #f8fafc;
}

.dealer-team__field .input-field::placeholder {
  color: #64748b;
  font-weight: 550;
}

.dealer-team__field select.input-field,
.dealer-team__field input[type='date'] {
  color-scheme: dark;
}

.dealer-team__error {
  margin: 0;
  padding: 0.55rem 0.7rem;
  border-radius: 0.7rem;
  background: rgba(248, 113, 113, 0.1);
  font-size: 0.8125rem;
  font-weight: 650;
  letter-spacing: 0;
  text-transform: none;
  color: #fca5a5;
}

.dealer-team__footer {
  position: sticky;
  bottom: 0;
  z-index: 1;
  margin-top: auto;
  padding-top: 0.85rem;
  background: linear-gradient(180deg, rgba(3, 7, 18, 0), var(--bg-app) 32%);
}

.dealer-team__footer--split {
  display: flex;
  gap: 0.6rem;
}

.dealer-team__footer--split .dealer-team__create,
.dealer-team__footer--split .dealer-team__delete {
  width: auto;
  flex: 1;
}

.dealer-team__create,
.dealer-team__delete {
  width: 100%;
  justify-content: center;
  min-height: 2.85rem;
  border-radius: 0.85rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.dealer-team__delete {
  color: #fecaca;
  border-color: rgba(248, 113, 113, 0.45);
  background: rgba(127, 29, 29, 0.35);
}

.dealer-team__list {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.dealer-team__card {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.8rem 0.9rem;
}

.dealer-team__card-photo {
  width: 3.1rem;
  height: 3.1rem;
  border-radius: 0.7rem;
  object-fit: cover;
  flex-shrink: 0;
  background: rgba(15, 23, 42, 0.5);
}

.dealer-team__card-photo--placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
}

.dealer-team__card-body {
  min-width: 0;
  flex: 1;
}

.dealer-team__card p {
  margin: 0.2rem 0 0;
  font-size: 0.8125rem;
  color: #cbd5e1;
}

.dealer-team__card p span {
  margin-right: 0.35rem;
  color: #94a3b8;
  font-weight: 650;
}

.dealer-team__card-top {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.dealer-team__card-top strong {
  font-size: 0.95rem;
}

.dealer-team__card-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.4rem;
  flex-shrink: 0;
}

.dealer-team__badge {
  flex-shrink: 0;
  padding: 0.12rem 0.5rem;
  border-radius: 999px;
  font-size: 0.6875rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.dealer-team__badge--sales {
  color: #fff;
  background: var(--accent-primary);
  border: 1px solid var(--accent-primary);
}

.dealer-team__badge--service {
  color: #fdba74;
  background: rgba(245, 130, 32, 0.14);
  border: 1px solid rgba(245, 130, 32, 0.45);
}

.dealer-team__badge--admin {
  color: #93c5fd;
  background: rgba(59, 130, 246, 0.16);
  border: 1px solid rgba(96, 165, 250, 0.45);
}

.dealer-team__card-actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.dealer-team__card-edit {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.85rem;
  height: 1.85rem;
  margin: 0;
  padding: 0;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(15, 23, 42, 0.45);
  color: #e2e8f0;
  cursor: pointer;
}

.dealer-team__card-edit:hover {
  border-color: var(--accent-primary);
  color: var(--accent-primary);
}

.dealer-team__card-edit--danger:hover {
  border-color: #f87171;
  color: #fca5a5;
}

.dealer-team__card-edit:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.dealer-role-editor__section {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.dealer-role-editor__heading {
  margin: 0;
  font-size: 0.9rem;
}

.dealer-role-editor__hint {
  margin: 0;
}

.dealer-role-editor__tiers {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  gap: 0.65rem;
}

.dealer-role-editor__tier {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.35rem;
  padding: 0.85rem 0.9rem;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(15, 23, 42, 0.35);
  cursor: pointer;
  text-align: left;
  transition: border-color 0.15s, background 0.15s;
}

.dealer-role-editor__tier:hover {
  border-color: rgba(148, 163, 184, 0.35);
}

.dealer-role-editor__tier.is-active {
  border-color: rgba(99, 102, 241, 0.55);
  background: rgba(99, 102, 241, 0.08);
}

.dealer-role-editor__tier--blue.is-active {
  border-color: rgba(96, 165, 250, 0.55);
  background: rgba(96, 165, 250, 0.08);
}

.dealer-role-editor__tier--purple.is-active {
  border-color: rgba(167, 139, 250, 0.55);
  background: rgba(167, 139, 250, 0.08);
}

.dealer-role-editor__tier-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 10px;
  background: rgba(148, 163, 184, 0.1);
}

.dealer-role-editor__tier-label {
  font-weight: 600;
  font-size: 0.875rem;
}

.dealer-role-editor__tier-desc {
  font-size: 0.75rem;
  color: var(--text-muted, #94a3b8);
  line-height: 1.35;
}

.dealer-role-editor__perm-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.dealer-role-editor__customize {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.8125rem;
  white-space: nowrap;
  cursor: pointer;
}

.dealer-role-editor__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.dealer-role-editor__chip {
  font-size: 0.75rem;
  padding: 0.3rem 0.55rem;
  border-radius: 999px;
  background: rgba(99, 102, 241, 0.12);
  color: #c7d2fe;
}

.dealer-role-editor__chip--muted {
  background: rgba(148, 163, 184, 0.12);
  color: var(--text-muted, #94a3b8);
}

.dealer-role-editor__groups {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  gap: 0.65rem;
}

.dealer-role-editor__group {
  padding: 0.75rem 0.85rem;
}

.dealer-role-editor__group h5 {
  margin: 0 0 0.5rem;
  font-size: 0.8125rem;
  color: var(--text-muted, #94a3b8);
}

.dealer-role-editor__perm-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.dealer-role-editor__perm {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.45rem 0.55rem;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.12);
  background: transparent;
  cursor: pointer;
  text-align: left;
  font-size: 0.8125rem;
}

.dealer-role-editor__perm.is-on {
  border-color: rgba(99, 102, 241, 0.35);
  background: rgba(99, 102, 241, 0.08);
}

.dealer-role-editor__perm-check {
  width: 0.95rem;
  height: 0.95rem;
  border-radius: 4px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  flex-shrink: 0;
}

.dealer-role-editor__perm.is-on .dealer-role-editor__perm-check {
  background: #6366f1;
  border-color: #6366f1;
  box-shadow: inset 0 0 0 2px rgba(15, 23, 42, 0.85);
}

.dealer-role-editor__perm-label {
  flex: 1;
}

.dealer-role-editor__perm-badge {
  font-size: 0.625rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted, #94a3b8);
}

.dealer-role-editor__preview {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.65rem 0.85rem;
  font-size: 0.8125rem;
  color: var(--text-muted, #94a3b8);
}

/* Spare grouping (catalog tab) */
.spare-grouping {
  padding: 0.85rem 1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.spare-grouping__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
}

.spare-grouping__head-main { min-width: 0; }

.spare-grouping__title {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: -0.01em;
}

.spare-grouping__stats {
  margin: 0.2rem 0 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 600;
}

.spare-grouping__mode {
  display: inline-flex;
  padding: 0.2rem;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.08);
  gap: 0.15rem;
}

.spare-grouping__mode-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--text-muted);
  padding: 0.4rem 0.75rem;
  font: inherit;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
}

.spare-grouping__mode-btn.is-active {
  background: rgba(251, 146, 60, 0.22);
  color: #fdba74;
}

.spare-grouping__dirty-pill {
  color: #fdba74;
  font-weight: 800;
}

.spare-grouping__lead {
  margin: -0.15rem 0 0;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.spare-grouping__select-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(15, 23, 42, 0.45);
  color: var(--text-muted);
  padding: 0.45rem 0.75rem;
  font: inherit;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
}

.spare-grouping__select-toggle.is-active {
  background: rgba(251, 146, 60, 0.22);
  border-color: rgba(251, 146, 60, 0.65);
  color: #fdba74;
}

.spare-grouping__collapsed {
  position: relative;
}

.spare-grouping__collapsed-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  width: 100%;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(15, 23, 42, 0.45);
  color: #e2e8f0;
  padding: 0.7rem 0.85rem;
  font: inherit;
  font-size: 0.85rem;
  cursor: pointer;
  text-align: left;
}

.spare-grouping__collapsed-btn strong {
  color: #fdba74;
}

.spare-grouping__collapsed-meta {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: var(--text-muted);
  font-size: 0.8rem;
  font-weight: 700;
}

.spare-grouping__collapsed-btn.is-open .spare-grouping__collapsed-meta svg {
  transform: rotate(180deg);
}

.spare-grouping__collapsed-panel {
  margin-top: 0.4rem;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(15, 23, 42, 0.95);
  overflow: hidden;
  max-height: 14rem;
  overflow-y: auto;
}

.spare-grouping__collapsed-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  width: 100%;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  background: transparent;
  color: #e2e8f0;
  padding: 0.75rem 0.85rem;
  font: inherit;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  text-align: left;
}

.spare-grouping__collapsed-option:last-child {
  border-bottom: 0;
}

.spare-grouping__collapsed-option.is-active {
  background: rgba(251, 146, 60, 0.16);
  color: #fdba74;
}

.spare-grouping--mobile {
  padding-bottom: 5.5rem;
}

.spare-grouping-sheet {
  position: fixed;
  inset: 0;
  z-index: 5200;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.spare-grouping-sheet__backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  background: rgba(2, 6, 23, 0.62);
  cursor: pointer;
}

.spare-grouping-sheet__panel {
  position: relative;
  z-index: 1;
  width: min(100%, 28rem);
  max-height: min(78vh, 36rem);
  display: flex;
  flex-direction: column;
  border-radius: 18px 18px 0 0;
  background: #111827;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 0;
  box-shadow: 0 -12px 40px rgba(0, 0, 0, 0.45);
  padding: 0.45rem 0.85rem calc(0.85rem + env(safe-area-inset-bottom, 0px));
}

.spare-grouping-sheet__handle {
  width: 2.5rem;
  height: 0.28rem;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.45);
  margin: 0.2rem auto 0.65rem;
}

.spare-grouping-sheet__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.55rem;
}

.spare-grouping-sheet__eyebrow {
  margin: 0;
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #fdba74;
}

.spare-grouping-sheet__title {
  margin: 0.2rem 0 0;
  font-size: 1rem;
  font-weight: 800;
  color: #f8fafc;
  line-height: 1.25;
}

.spare-grouping-sheet__close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.04);
  color: #e2e8f0;
  cursor: pointer;
}

.spare-grouping-sheet__list {
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  padding: 0.15rem 0 0.5rem;
}

.spare-grouping-sheet__option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  width: 100%;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(15, 23, 42, 0.55);
  color: #f1f5f9;
  padding: 0.85rem 0.9rem;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
  text-align: left;
}

.spare-grouping-sheet__option.is-active {
  border-color: rgba(251, 146, 60, 0.7);
  background: rgba(251, 146, 60, 0.16);
  color: #fdba74;
}

.spare-grouping-sheet__option-meta {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 700;
}

.spare-grouping-sheet__option.is-active .spare-grouping-sheet__option-meta {
  color: #fdba74;
}

.spare-grouping-sheet__remove {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  width: 100%;
  margin-top: 0.35rem;
  min-height: 2.75rem;
  border-radius: 12px;
  border: 1px solid rgba(248, 113, 113, 0.4);
  background: rgba(248, 113, 113, 0.1);
  color: #fca5a5;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
}

.spare-grouping-fixed-save {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 5100;
  padding: 0.65rem 0.85rem calc(0.65rem + env(safe-area-inset-bottom, 0px));
  pointer-events: none;
}

@media (min-width: 961px) {
  .spare-grouping-fixed-save {
    left: var(--sidebar-width, 16rem);
  }

  .main-content.expanded ~ * .spare-grouping-fixed-save,
  body:has(.main-content.expanded) .spare-grouping-fixed-save {
    left: var(--sidebar-collapsed, 4.5rem);
  }
}

.spare-grouping-fixed-save__inner {
  pointer-events: auto;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.55rem;
  max-width: 42rem;
  margin: 0 auto;
  padding: 0.7rem 0.8rem;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(15, 23, 42, 0.96);
  backdrop-filter: blur(12px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
}

.spare-grouping-fixed-save.is-dirty .spare-grouping-fixed-save__inner {
  border-color: rgba(251, 146, 60, 0.5);
}

.spare-grouping-fixed-save__note {
  margin: 0;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-muted);
}

.spare-grouping-fixed-save.is-dirty .spare-grouping-fixed-save__note {
  color: #fdba74;
}

.spare-grouping-fixed-save__actions {
  display: flex;
  gap: 0.4rem;
}

.spare-grouping__mode-btn.is-active {
  background: rgba(251, 146, 60, 0.22);
  color: #fdba74;
}

.spare-grouping__workspace {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 0.7rem 0.75rem;
  border-radius: 14px;
  border: 1px solid rgba(251, 146, 60, 0.28);
  background: linear-gradient(135deg, rgba(251, 146, 60, 0.1), rgba(15, 23, 42, 0.28));
}

.spare-grouping__target-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem 0.75rem;
}

.spare-grouping__target-copy {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.4rem 0.5rem;
}

.spare-grouping__target-label {
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #fdba74;
}

.spare-grouping__target-name {
  font-size: 0.95rem;
  font-weight: 800;
  color: #fff7ed;
}

.spare-grouping__target-count {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 0.12rem 0.45rem;
  border-radius: 999px;
  background: rgba(251, 146, 60, 0.22);
  color: #fdba74;
}

.spare-grouping__hint {
  margin: 0;
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 500;
}

.spare-grouping__loading,
.spare-grouping__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  min-height: 12rem;
  text-align: center;
  color: var(--text-muted);
}

.spare-grouping__empty h2 {
  margin: 0;
  color: var(--text-main);
  font-size: 1.05rem;
}

.spare-grouping__feedback { min-height: 0; }

.spare-grouping__error {
  margin: 0;
  color: #fca5a5;
  font-size: 0.8rem;
  font-weight: 600;
}

.spare-grouping__toast {
  margin: 0;
  color: #fdba74;
  font-size: 0.8rem;
  font-weight: 700;
}

.spare-grouping__groups {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.spare-grouping__group-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(15, 23, 42, 0.35);
  color: var(--text-muted);
  padding: 0.42rem 0.8rem;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
}

.spare-grouping__group-chip.is-active {
  background: rgba(251, 146, 60, 0.22);
  border-color: rgba(251, 146, 60, 0.75);
  color: #fdba74;
  box-shadow: 0 0 0 3px rgba(251, 146, 60, 0.16);
}

.spare-grouping__group-count {
  font-size: 0.68rem;
  opacity: 0.85;
  font-variant-numeric: tabular-nums;
}

.spare-grouping__toolbar {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.spare-grouping__views {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.35rem;
  padding: 0.2rem;
  border-radius: 12px;
  background: rgba(15, 23, 42, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.spare-grouping__view {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--text-muted);
  padding: 0.45rem 0.4rem;
  font: inherit;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
}

.spare-grouping__view span {
  font-size: 0.68rem;
  font-variant-numeric: tabular-nums;
  opacity: 0.85;
}

.spare-grouping__view.is-active {
  background: rgba(251, 146, 60, 0.2);
  color: #fdba74;
}

.spare-grouping__search {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(15, 23, 42, 0.45);
  padding: 0.45rem 0.65rem;
  color: var(--text-muted);
}

.spare-grouping__search input {
  flex: 1;
  border: 0;
  background: transparent;
  color: #f8fafc;
  font: inherit;
  outline: none;
}

.spare-grouping__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.spare-grouping__empty-list {
  margin: 0.35rem 0 0;
  font-size: 0.85rem;
}

.spare-grouping__grid { max-height: none; }

.spare-grouping__card-wrap {
  position: relative;
  border-radius: 14px;
}

.spare-grouping__card-wrap.is-selected {
  outline: 2px solid rgba(251, 146, 60, 0.8);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px rgba(251, 146, 60, 0.16);
}

.spare-grouping__card-wrap.is-clickable { cursor: pointer; }

.spare-grouping__card-wrap.is-clickable:hover {
  outline: 2px solid rgba(251, 146, 60, 0.45);
  outline-offset: 2px;
}

.spare-grouping__card-wrap.is-remove:hover {
  outline-color: rgba(248, 113, 113, 0.55);
}

.spare-grouping.is-tap-mode .spare-grouping__group-chip.is-active {
  box-shadow: 0 0 0 3px rgba(251, 146, 60, 0.2);
}

.spare-grouping__flight {
  position: fixed;
  z-index: 4000;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.65rem;
  border-radius: 14px;
  border: 1px solid rgba(251, 146, 60, 0.55);
  background: linear-gradient(160deg, rgba(30, 41, 59, 0.96), rgba(15, 23, 42, 0.98));
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.35), 0 0 0 1px rgba(251, 146, 60, 0.2);
  color: #fdba74;
  font-size: 0.8rem;
  font-weight: 700;
  text-align: center;
  opacity: 1;
  transform: translate(0, 0) scale(1);
  transform-origin: top left;
  transition:
    transform 0.5s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.5s ease;
  will-change: transform, opacity;
}

.spare-grouping__flight.is-flying {
  border-color: rgba(251, 146, 60, 0.9);
}

.spare-grouping__flight-label {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  line-height: 1.25;
}

.spare-grouping__card-wrap .catalog-product-card { height: 100%; }

.spare-grouping__card-check {
  position: absolute;
  top: 0.45rem;
  left: 0.45rem;
  z-index: 4;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.78);
  color: #e2e8f0;
  border: 1px solid rgba(255, 255, 255, 0.22);
  cursor: pointer;
  padding: 0;
}

.spare-grouping__card-check.is-selected {
  background: rgba(251, 146, 60, 0.95);
  border-color: rgba(251, 146, 60, 1);
  color: #1a0a00;
}

.spare-grouping__card-group-badge {
  position: absolute;
  top: 0.45rem;
  left: 0.45rem;
  bottom: auto;
  z-index: 4;
  max-width: min(7.5rem, calc(100% - 4.5rem));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border-radius: 999px;
  padding: 0.18rem 0.5rem;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  background: rgba(15, 23, 42, 0.88);
  color: #fdba74;
  border: 1px solid rgba(251, 146, 60, 0.4);
  pointer-events: none;
}

.spare-grouping.is-select-mode .spare-grouping__card-group-badge {
  top: 2.35rem;
  left: 0.45rem;
}

.spare-grouping__card-group-badge.is-unassigned {
  color: #cbd5e1;
  border-color: rgba(148, 163, 184, 0.4);
}

.spare-grouping__card-group-badge.is-remove {
  border-color: rgba(248, 113, 113, 0.45);
  color: #fca5a5;
}

.spare-grouping__card-group-badge.is-queued {
  border-color: rgba(251, 146, 60, 0.65);
  color: #fdba74;
  background: rgba(251, 146, 60, 0.16);
}

.spare-grouping__card-wrap.is-queued {
  outline: 1px dashed rgba(251, 146, 60, 0.55);
  outline-offset: 2px;
}

.spare-grouping__savebar {
  position: sticky;
  bottom: 0.5rem;
  z-index: 5;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
  margin-top: 0.35rem;
  padding: 0.7rem 0.8rem;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(15, 23, 42, 0.92);
  backdrop-filter: blur(10px);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.35);
}

.spare-grouping.is-dirty .spare-grouping__savebar {
  border-color: rgba(251, 146, 60, 0.45);
}

.spare-grouping__savebar-note {
  margin: 0;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-muted);
}

.spare-grouping.is-dirty .spare-grouping__savebar-note {
  color: #fdba74;
}

.spare-grouping__savebar-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.spare-grouping__save-btn:disabled {
  opacity: 0.55;
}

.spare-grouping__card-wrap .catalog-product-card__sku-badge {
  left: auto;
  right: 0.45rem;
}


/* Audit cycles â€“ premium hub */
.audit-cycles-hub {
  --ac-ink: var(--text-primary, #f8fafc);
  --ac-mute: var(--text-muted, #94a3b8);
  --ac-line: color-mix(in srgb, var(--border-glass, rgba(148, 163, 184, 0.35)) 85%, transparent);
  --ac-open: #34d399;
  --ac-over: #4ade80;
  --ac-under: #f87171;
  position: relative;
  overflow: hidden;
  padding: 1.35rem 1.4rem 1.5rem;
}

.audit-cycles-hub::before {
  content: '';
  position: absolute;
  inset: 0 0 auto 0;
  height: 7.5rem;
  pointer-events: none;
  background:
    radial-gradient(ellipse 55% 120% at 0% 0%, color-mix(in srgb, var(--accent-primary) 22%, transparent), transparent 70%),
    radial-gradient(ellipse 40% 100% at 100% 0%, rgba(56, 189, 248, 0.1), transparent 65%);
}

.audit-cycles-hub__header {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.15rem;
}

.audit-cycles-hub__eyebrow {
  margin: 0 0 0.35rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--accent-primary) 85%, var(--ac-mute));
}

.audit-cycles-hub__intro h3 {
  margin: 0;
  font-size: 1.55rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.15;
  color: var(--ac-ink);
}

.audit-cycles-hub__lede {
  margin: 0.45rem 0 0;
  max-width: 36rem;
  font-size: 0.9rem;
  line-height: 1.45;
  color: var(--ac-mute);
}

.audit-cycles-hub__new {
  flex-shrink: 0;
  margin-top: 0.15rem;
}

.audit-cycles-site-strip {
  position: relative;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
  margin-bottom: 1.15rem;
}

.audit-cycles-site-strip__tile {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.85rem 0.95rem;
  border-radius: 0.85rem;
  border: 1px solid var(--ac-line);
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.04), transparent 55%),
    color-mix(in srgb, var(--bg-glass, rgba(15, 23, 42, 0.55)) 92%, transparent);
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.audit-cycles-site-strip__tile.is-open {
  border-color: color-mix(in srgb, var(--ac-open) 45%, var(--ac-line));
}

.audit-cycles-site-strip__icon {
  display: grid;
  place-items: center;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 0.65rem;
  color: var(--ac-mute);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--ac-line);
}

.audit-cycles-site-strip__tile.is-open .audit-cycles-site-strip__icon {
  color: var(--ac-open);
  border-color: color-mix(in srgb, var(--ac-open) 35%, transparent);
  background: color-mix(in srgb, var(--ac-open) 12%, transparent);
}

.audit-cycles-site-strip__copy {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  min-width: 0;
  flex: 1;
}

.audit-cycles-site-strip__site {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ac-mute);
}

.audit-cycles-site-strip__status {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ac-ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.audit-cycles-site-strip__badge {
  flex-shrink: 0;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.28rem 0.5rem;
  border-radius: 0.4rem;
  color: var(--ac-mute);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--ac-line);
}

.audit-cycles-site-strip__tile.is-open .audit-cycles-site-strip__badge {
  color: #052e1b;
  background: var(--ac-open);
  border-color: transparent;
}

.audit-cycles-create {
  position: relative;
  margin-bottom: 1.15rem;
  padding: 1rem 1.05rem;
  border-radius: 0.9rem;
  border: 1px solid color-mix(in srgb, var(--accent-primary) 35%, var(--ac-line));
  background:
    linear-gradient(160deg, color-mix(in srgb, var(--accent-primary) 12%, transparent), transparent 55%),
    rgba(0, 0, 0, 0.18);
  animation: auditCycleRise 0.28s ease-out;
}

.audit-cycles-create__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.85rem;
}

.audit-cycles-create__fields {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: flex-end;
}

.audit-cycles-create__field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  min-width: 8rem;
}

.audit-cycles-create__field--grow {
  flex: 1 1 14rem;
}

.audit-cycles-create__field span,
.audit-cycles-create__check span {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ac-mute);
}

.audit-cycles-create__field input,
.audit-cycles-create__field select {
  min-height: 2.35rem;
  padding: 0.45rem 0.65rem;
  border-radius: 0.5rem;
  border: 1px solid var(--ac-line);
  background: rgba(0, 0, 0, 0.25);
  color: var(--ac-ink);
}

.audit-cycles-create__check {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  min-height: 2.35rem;
  padding-bottom: 0.15rem;
}

.audit-cycles-create__actions {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.9rem;
}

.audit-cycles-hub__loading,
.audit-cycles-hub__empty {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  min-height: 12rem;
  text-align: center;
  color: var(--ac-mute);
}

.audit-cycles-hub__empty strong {
  color: var(--ac-ink);
  font-size: 1.05rem;
}

.audit-cycles-hub__empty p {
  margin: 0;
  max-width: 22rem;
  font-size: 0.875rem;
}

.audit-cycles-list {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
}

@keyframes auditCycleRise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.audit-cycle-card {
  position: relative;
  border-radius: 1rem;
  padding: 1.05rem 1.1rem 1rem;
  border: 1px solid var(--ac-line);
  background:
    linear-gradient(155deg, rgba(255, 255, 255, 0.045), transparent 42%),
    color-mix(in srgb, var(--bg-glass, rgba(15, 23, 42, 0.65)) 94%, transparent);
  overflow: hidden;
  animation: auditCycleRise 0.4s ease-out both;
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.audit-cycle-card::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: color-mix(in srgb, var(--ac-mute) 55%, transparent);
}

.audit-cycle-card.is-open::before {
  background: linear-gradient(180deg, var(--ac-open), color-mix(in srgb, var(--ac-open) 35%, transparent));
}

.audit-cycle-card.is-site-ho.is-open::before {
  background: linear-gradient(180deg, var(--accent-primary), color-mix(in srgb, var(--accent-primary) 30%, transparent));
}

.audit-cycle-card.is-open {
  border-color: color-mix(in srgb, var(--ac-open) 28%, var(--ac-line));
}

.audit-cycle-card.is-expanded {
  border-color: color-mix(in srgb, var(--accent-primary) 40%, var(--ac-line));
}

.audit-cycle-card__hit {
  cursor: pointer;
  border-radius: 0.65rem;
  outline: none;
  transition: background 0.15s ease;
}

.audit-cycle-card__hit:hover {
  background: rgba(255, 255, 255, 0.02);
}

.audit-cycle-card__hit:focus-visible {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent-primary) 55%, transparent);
}

.audit-cycle-card__head {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  min-width: 0;
}

.audit-cycle-card__hit:hover .audit-cycle-card__title {
  color: color-mix(in srgb, var(--accent-primary-light) 70%, var(--ac-ink));
}

.audit-cycle-card__site-mark {
  display: grid;
  place-items: center;
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 0.7rem;
  flex-shrink: 0;
  color: var(--ac-mute);
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--ac-line);
}

.audit-cycle-card.is-open .audit-cycle-card__site-mark {
  color: var(--ac-open);
  border-color: color-mix(in srgb, var(--ac-open) 30%, transparent);
  background: color-mix(in srgb, var(--ac-open) 10%, transparent);
}

.audit-cycle-card.is-site-ho.is-open .audit-cycle-card__site-mark {
  color: var(--accent-primary-light);
  border-color: color-mix(in srgb, var(--accent-primary) 35%, transparent);
  background: color-mix(in srgb, var(--accent-primary) 12%, transparent);
}

.audit-cycle-card__title-wrap {
  min-width: 0;
  flex: 1;
}

.audit-cycle-card__title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.45rem 0.55rem;
}

.audit-cycle-card__title {
  font-size: 1.12rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--ac-ink);
  transition: color 0.15s ease;
}

.audit-cycle-card__status {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.22rem 0.45rem;
  border-radius: 0.35rem;
  border: 1px solid var(--ac-line);
  color: var(--ac-mute);
}

.audit-cycle-card__status.is-open {
  color: #052e1b;
  background: var(--ac-open);
  border-color: transparent;
}

.audit-cycle-card__status.is-closed,
.audit-cycle-card__status.is-scheduled {
  background: rgba(255, 255, 255, 0.04);
}

.audit-cycle-card__meta {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin-top: 0.3rem;
  font-size: 0.78rem;
  color: var(--ac-mute);
}

.audit-cycle-card__meta-sep {
  opacity: 0.55;
}

.audit-cycle-card__chevron {
  flex-shrink: 0;
  color: var(--ac-mute);
  transition: transform 0.22s ease;
}

.audit-cycle-card__chevron.is-open {
  transform: rotate(180deg);
  color: var(--accent-primary-light);
}

.audit-cycle-card__footer {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  margin-top: 0.85rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--ac-line);
}

.audit-cycle-card__close-btn.btn-danger {
  background: color-mix(in srgb, var(--accent-red) 88%, #7f1d1d);
  border-color: color-mix(in srgb, var(--accent-red) 70%, transparent);
  color: #fff;
}

.audit-cycle-card__close-btn.btn-danger:hover:not(:disabled) {
  background: var(--accent-red);
  border-color: var(--accent-red);
}

.audit-cycle-card__stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.55rem;
  margin-top: 1rem;
}

.audit-cycle-card__stat {
  padding: 0.7rem 0.75rem;
  border-radius: 0.7rem;
  border: 1px solid var(--ac-line);
  background: rgba(0, 0, 0, 0.16);
}

.audit-cycle-card__stat-label {
  display: block;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ac-mute);
  margin-bottom: 0.3rem;
}

.audit-cycle-card__stat-value {
  display: block;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
  color: var(--ac-ink);
}

.audit-cycle-card__stat-value.is-over {
  color: var(--ac-over);
}

.audit-cycle-card__stat-value.is-under {
  color: var(--ac-under);
}

.audit-cycle-card__timeline {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
  margin-top: 0.85rem;
  padding-top: 0.85rem;
  border-top: 1px solid color-mix(in srgb, var(--ac-line) 80%, transparent);
}

.audit-cycle-card__timeline span {
  display: block;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--ac-mute);
  margin-bottom: 0.2rem;
}

.audit-cycle-card__timeline strong {
  display: block;
  font-size: 0.8rem;
  font-weight: 550;
  color: color-mix(in srgb, var(--ac-ink) 88%, var(--ac-mute));
}

.audit-cycle-card__drawer {
  margin-top: 0;
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, opacity 0.25s ease, margin-top 0.25s ease;
}

.audit-cycle-card__drawer.is-open {
  margin-top: 0.95rem;
  max-height: 42rem;
  opacity: 1;
}

.audit-cycle-card__columns {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.55rem 0.85rem;
  margin-bottom: 0.75rem;
  padding: 0.65rem 0.75rem;
  border-radius: 0.7rem;
  border: 1px solid var(--ac-line);
  background: rgba(0, 0, 0, 0.16);
}

.audit-cycle-card__columns-label {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ac-mute);
}

.audit-cycle-card__columns-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 0.75rem;
}

.audit-cycle-card__column-check {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.78rem;
  color: color-mix(in srgb, var(--ac-ink) 90%, var(--ac-mute));
  cursor: pointer;
  user-select: none;
}

.audit-cycle-card__column-check input {
  width: 0.9rem;
  height: 0.9rem;
  accent-color: var(--accent-primary);
  cursor: pointer;
}

.audit-cycle-card__table-panel {
  border-radius: 0.75rem;
  border: 1px solid var(--ac-line);
  background: rgba(0, 0, 0, 0.22);
  overflow: hidden;
}

.audit-cycle-card__table-wrap {
  overflow: auto;
  max-height: 20rem;
}

.audit-cycle-card__empty-table {
  margin: 0;
  padding: 1rem;
  text-align: center;
  color: var(--ac-mute);
  font-size: 0.875rem;
  border-radius: 0.75rem;
  border: 1px dashed var(--ac-line);
}

.audit-cycle-card__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8rem;
}

.audit-cycle-card__table th,
.audit-cycle-card__table td {
  padding: 0.55rem 0.7rem;
  border-bottom: 1px solid color-mix(in srgb, var(--ac-line) 80%, transparent);
  text-align: left;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.audit-cycle-card__name-cell {
  white-space: normal;
  min-width: 10rem;
  max-width: 18rem;
}

.audit-cycle-card__table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ac-mute);
  font-weight: 700;
  background: color-mix(in srgb, #0b1220 88%, transparent);
  backdrop-filter: blur(8px);
}

.audit-cycle-card__table tbody tr {
  transition: background 0.12s ease;
}

