  font-variant-numeric: tabular-nums lining-nums;
  color: #fecaca;
}

.agm-audit-report__site-card footer {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem 0.85rem;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--agm-mute);
}

.agm-audit-report__spotlight {
  margin-bottom: 1rem;
  border-radius: 0.95rem;
  border: 1px solid var(--agm-line);
  background: rgba(2, 6, 23, 0.35);
  overflow: hidden;
}

.agm-audit-report__spotlight-head,
.agm-audit-report__table-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.85rem 1.05rem;
  border-bottom: 1px solid var(--agm-line);
}

.agm-audit-report__table-head-copy {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}

.agm-audit-report__spotlight-head h4,
.agm-audit-report__table-head h4 {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--agm-ink);
}

.agm-audit-report__spotlight-head span,
.agm-audit-report__table-head-copy span {
  font-size: 0.75rem;
  font-weight: 400;
  color: var(--agm-mute);
}

.agm-audit-report__view-toggle {
  display: inline-flex;
  flex-shrink: 0;
  gap: 0.2rem;
  padding: 0.18rem;
  border-radius: 0.65rem;
  border: 1px solid var(--agm-line);
  background: rgba(2, 6, 23, 0.4);
}

.agm-audit-report__view-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border: none;
  background: transparent;
  color: var(--agm-mute);
  font: inherit;
  font-size: 0.78rem;
  font-weight: 500;
  padding: 0.4rem 0.65rem;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.agm-audit-report__view-btn:hover {
  color: var(--agm-ink);
  background: rgba(255, 255, 255, 0.04);
}

.agm-audit-report__view-btn.is-active {
  color: var(--agm-gold);
  background: var(--agm-gold-dim);
}

.agm-audit-report__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(232, 192, 122, 0.35) transparent;
}

.agm-audit-report__scroll::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.agm-audit-report__scroll::-webkit-scrollbar-track {
  background: transparent;
}

.agm-audit-report__scroll::-webkit-scrollbar-thumb {
  background: rgba(232, 192, 122, 0.28);
  border-radius: 999px;
  border: 1px solid transparent;
  background-clip: padding-box;
}

.agm-audit-report__scroll::-webkit-scrollbar-thumb:hover {
  background: rgba(232, 192, 122, 0.5);
  background-clip: padding-box;
}

.agm-audit-report__scroll::-webkit-scrollbar-corner {
  background: transparent;
}

.agm-audit-report__tiles-wrap {
  max-height: min(52vh, 40rem);
  padding: 0.45rem 0.55rem;
}

.agm-audit-report__tiles {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.agm-audit-report__table-head-actions {
  display: flex;
  flex-shrink: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.45rem;
}

.agm-audit-report__tile {
  display: grid;
  grid-template-columns: 1.6rem minmax(0, 1.5fr) auto auto;
  align-items: center;
  gap: 0.55rem 0.65rem;
  width: 100%;
  padding: 0.45rem 0.65rem;
  border-radius: 0.6rem;
  border: 1px solid var(--agm-line);
  background: rgba(2, 6, 23, 0.4);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.agm-audit-report__tile:hover {
  border-color: color-mix(in srgb, var(--agm-gold) 28%, var(--agm-line));
  background: rgba(232, 192, 122, 0.05);
}

.agm-audit-report.highlight-uncounted .agm-audit-report__tile.is-uncounted {
  border-color: color-mix(in srgb, var(--agm-gold) 28%, var(--agm-line));
  background: rgba(232, 192, 122, 0.045);
}

.agm-audit-report.is-editing .agm-audit-report__tile {
  grid-template-columns: 1.6rem minmax(0, 1.5fr) auto auto 1.85rem;
  padding-right: 0.55rem;
}

.agm-audit-report.is-editing .agm-audit-report__table-panel {
  border-color: color-mix(in srgb, var(--agm-gold) 35%, var(--agm-line));
}

.agm-audit-report__tile .agm-audit-report__rank {
  width: 1.45rem;
  height: 1.45rem;
  font-size: 0.65rem;
}

.agm-audit-report__tile-main {
  min-width: 0;
}

.agm-audit-report__tile-title {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  min-width: 0;
}

.agm-audit-report__tile-title strong {
  min-width: 0;
  font-size: 0.86rem;
  font-weight: 500;
  letter-spacing: -0.015em;
  color: var(--agm-ink);
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.agm-audit-report__tile .agm-audit-report__badge {
  flex-shrink: 0;
  padding: 0.1rem 0.4rem;
  font-size: 0.62rem;
}

.agm-audit-report__tile-sku {
  font-weight: 500;
  color: var(--agm-gold);
  font-variant-numeric: tabular-nums;
}

.agm-audit-report__tile-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  margin: 0.12rem 0 0;
  font-size: 0.7rem;
  font-weight: 400;
  color: var(--agm-mute);
  line-height: 1.2;
}

.agm-audit-report__tile-stats {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  font-size: 0.84rem;
  font-weight: 400;
  letter-spacing: -0.015em;
  font-variant-numeric: tabular-nums lining-nums;
  color: var(--agm-ink);
  white-space: nowrap;
}

.agm-audit-report__tile-stats em,
.agm-audit-report__tile-value em {
  display: block;
  margin-bottom: 0.08rem;
  font-style: normal;
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--agm-mute);
}

.agm-audit-report__tile-stats .is-under,
.agm-audit-report__tile-value strong.is-under {
  color: var(--agm-under);
  font-weight: 500;
}

.agm-audit-report__tile-stats .is-over,
.agm-audit-report__tile-value strong.is-over,
.agm-audit-report__table .is-over,
.agm-audit-report__totals-metrics .is-over {
  color: #86efac;
  font-weight: 500;
}

.agm-audit-report__tile-value {
  text-align: right;
  white-space: nowrap;
  min-width: 7.5rem;
}

.agm-audit-report__tile-value strong {
  display: block;
  font-size: 0.95rem;
  font-weight: 400;
  letter-spacing: -0.025em;
  font-variant-numeric: tabular-nums lining-nums;
}

.agm-audit-report__spotlight-list {
  list-style: none;
  margin: 0;
  padding: 0.35rem 0;
}

.agm-audit-report__spotlight-list li {
  display: grid;
  grid-template-columns: 2rem minmax(0, 1fr) auto;
  gap: 0.75rem;
  align-items: center;
  padding: 0.7rem 1.05rem;
}

.agm-audit-report__spotlight-list li + li {
  border-top: 1px solid rgba(148, 163, 184, 0.1);
}

.agm-audit-report__rank {
  display: grid;
  place-items: center;
  width: 1.65rem;
  height: 1.65rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--agm-gold);
  background: var(--agm-gold-dim);
  border: 1px solid color-mix(in srgb, var(--agm-gold) 35%, transparent);
}

.agm-audit-report__spotlight-copy {
  min-width: 0;
}

.agm-audit-report__spotlight-copy strong {
  display: block;
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--agm-ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.agm-audit-report__spotlight-copy span {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.75rem;
  font-weight: 400;
  color: var(--agm-mute);
}

.agm-audit-report__spotlight-nums {
  text-align: right;
  font-variant-numeric: tabular-nums lining-nums;
}

.agm-audit-report__spotlight-nums strong {
  display: block;
  font-size: 0.98rem;
  font-weight: 400;
  letter-spacing: -0.02em;
  color: #fecaca;
}

.agm-audit-report__spotlight-nums span {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.72rem;
  font-weight: 400;
  color: var(--agm-mute);
}

.agm-audit-report__table-panel {
  border-radius: 0.95rem;
  border: 1px solid var(--agm-line);
  background: rgba(2, 6, 23, 0.35);
  overflow: hidden;
}

.agm-audit-report__table-wrap {
  max-height: min(52vh, 40rem);
}

.agm-audit-report__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.82rem;
  font-variant-numeric: tabular-nums lining-nums;
}

.agm-audit-report__table th,
.agm-audit-report__table td {
  padding: 0.45rem 0.7rem;
  border-bottom: 1px solid rgba(148, 163, 184, 0.1);
  text-align: left;
  vertical-align: middle;
}

.agm-audit-report__table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--agm-mute);
  background: rgba(3, 7, 18, 0.96);
  backdrop-filter: blur(8px);
}

.agm-audit-report__table tbody tr:hover {
  background: rgba(255, 255, 255, 0.025);
}

.agm-audit-report.highlight-uncounted .agm-audit-report__table tbody tr.is-uncounted {
  background: rgba(232, 192, 122, 0.04);
}

.agm-audit-report__table .is-action {
  width: 2.5rem;
  text-align: right;
  padding-right: 0.45rem;
}

.agm-audit-report__table .is-rank {
  width: 2.5rem;
  color: var(--agm-mute);
  font-variant-numeric: tabular-nums;
}

.agm-audit-report__table .is-sku {
  color: var(--agm-gold);
  font-weight: 500;
}

.agm-audit-report__table .is-name {
  max-width: 18rem;
  font-weight: 400;
  color: var(--agm-ink);
}

.agm-audit-report__table .is-num {
  text-align: right;
  font-weight: 400;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.agm-audit-report__table .is-under,
.agm-audit-report__totals-metrics .is-under {
  color: var(--agm-under);
  font-weight: 500;
}

.agm-audit-report__badge {
  display: inline-flex;
  align-items: center;
  padding: 0.18rem 0.5rem;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.agm-audit-report__badge.is-counted {
  color: #86efac;
  background: rgba(52, 211, 153, 0.12);
  border: 1px solid rgba(52, 211, 153, 0.28);
}

.agm-audit-report__badge.is-uncounted {
  color: var(--agm-gold);
  background: var(--agm-gold-dim);
  border: 1px solid color-mix(in srgb, var(--agm-gold) 35%, transparent);
}

.agm-audit-report__totals {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.85rem 1.05rem;
  border-top: 1px solid var(--agm-line);
  background: rgba(0, 0, 0, 0.22);
  font-size: 0.8rem;
  color: var(--agm-mute);
}

.agm-audit-report__totals-metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem 1.25rem;
  font-weight: 400;
  font-variant-numeric: tabular-nums lining-nums;
  letter-spacing: -0.015em;
  color: var(--agm-ink);
}

.agm-audit-report__totals-metrics em {
  display: block;
  margin-bottom: 0.15rem;
  font-style: normal;
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--agm-mute);
}

.agm-audit-report__placeholder {
  min-height: 12rem;
}

.agm-audit-report--maximized {
  position: fixed;
  inset: 0;
  z-index: 90;
  width: 100%;
  height: 100%;
  max-height: 100dvh;
  margin: 0;
  border-radius: 0;
  display: block;
  overflow: auto;
  padding: 1.25rem 1.5rem 1.5rem;
  background: #030712;
  box-shadow: none;
}

.agm-audit-report--maximized .agm-audit-report__table-wrap,
.agm-audit-report--maximized .agm-audit-report__tiles-wrap {
  max-height: none;
  overflow: visible;
}

.agm-audit-report--maximized .agm-audit-report__masthead {
  margin-bottom: 0.85rem;
  padding-bottom: 0.85rem;
}

@media (max-width: 720px) {
  .agm-audit-report {
    padding: 1.15rem 1rem 1.25rem;
  }

  .agm-audit-report__masthead {
    flex-direction: column;
  }

  .agm-audit-report__controls {
    flex-direction: column;
    align-items: stretch;
  }

  .agm-audit-report__segment {
    width: 100%;
  }

  .agm-audit-report__seg-btn {
    flex: 1;
    justify-content: center;
  }

  .agm-audit-report__actions {
    width: auto;
  }

  .agm-audit-report__spotlight-list li {
    grid-template-columns: 2rem minmax(0, 1fr);
  }

  .agm-audit-report__spotlight-nums {
    grid-column: 2;
    text-align: left;
  }

  .agm-audit-report__table-head {
    flex-wrap: wrap;
  }

  .agm-audit-report__view-toggle {
    width: 100%;
  }

  .agm-audit-report__view-btn {
    flex: 1;
    justify-content: center;
  }

  .agm-audit-report__tile {
    grid-template-columns: 1.45rem minmax(0, 1fr);
    gap: 0.4rem 0.55rem;
  }

  .agm-audit-report.is-editing .agm-audit-report__tile {
    grid-template-columns: 1.45rem minmax(0, 1fr) 1.85rem;
  }

  .agm-audit-report__tile-stats {
    grid-column: 2;
    gap: 0.65rem;
  }

  .agm-audit-report__tile-value {
    grid-column: 2;
    text-align: left;
    min-width: 0;
  }

  .agm-audit-report.is-editing .agm-audit-report__tile .agm-audit-report__hide-btn {
    grid-column: 3;
    grid-row: 1;
  }
}


/* Zoho warehouse location transfer (long-press on catalog cards) */
.warehouse-location-dialog__backdrop {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 1rem;
  background: rgba(15, 23, 42, 0.45);
}

.warehouse-location-dialog {
  width: min(420px, 100%);
  max-height: min(85vh, 560px);
  overflow: auto;
  padding: 1rem 1.1rem 1.15rem;
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.warehouse-location-dialog__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.warehouse-location-dialog__heading {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
}

.warehouse-location-dialog__heading h2 {
  margin: 0;
  font-size: 1.05rem;
  line-height: 1.25;
}

.warehouse-location-dialog__sub {
  margin: 0.2rem 0 0;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.warehouse-location-dialog__audit-note {
  margin: 0;
  font-size: 0.8rem;
  line-height: 1.4;
  color: var(--text-muted);
  padding: 0.55rem 0.7rem;
  border-radius: 10px;
  background: rgba(148, 163, 184, 0.12);
}

.warehouse-location-dialog__label,
.warehouse-location-dialog__hint {
  margin: 0;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.warehouse-location-dialog__hint {
  text-transform: none;
  font-weight: 500;
  letter-spacing: 0;
}

.warehouse-location-dialog__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.warehouse-location-dialog__option {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.75rem 0.85rem;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.warehouse-location-dialog__option:disabled {
  opacity: 0.7;
  cursor: default;
}

.warehouse-location-dialog__option.is-current {
  border-color: rgba(34, 197, 94, 0.45);
  background: rgba(34, 197, 94, 0.08);
}

.warehouse-location-dialog__option.is-selected {
  border-color: var(--accent, #ea580c);
  background: rgba(234, 88, 12, 0.1);
}

.warehouse-location-dialog__option-name {
  font-weight: 650;
  font-size: 0.95rem;
}

.warehouse-location-dialog__option-stock {
  font-size: 0.85rem;
  font-variant-numeric: tabular-nums;
  color: var(--text-muted);
}

.warehouse-location-dialog__error {
  margin: 0;
  font-size: 0.85rem;
  color: #b91c1c;
}

.warehouse-location-dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  margin-top: 0.25rem;
}

@media (min-width: 640px) {
  .warehouse-location-dialog__backdrop {
    align-items: center;
  }
}

.catalog-product-card--long-press {
  -webkit-touch-callout: none;
  user-select: none;
  touch-action: manipulation;
}

/* Sales order draft line editor */
/* Sales order detail — fewer surfaces, denser hierarchy */
.so-detail {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding-bottom: 0.5rem;
}

.so-detail--with-actions {
  padding-bottom: 6.25rem;
}

.so-detail__header {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.so-detail__header .so-detail__party + .doc-kam-strip {
  margin-top: 0.85rem;
}

.so-detail__salesperson-banner {
  margin: 0 0 0.85rem;
}

.so-detail__salesperson-banner-copy {
  display: grid;
  gap: 0.75rem;
  flex: 1;
}

.so-detail__salesperson-assign,
.so-detail__actions-staff {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.55rem;
}

.so-detail__salesperson-assign .theme-select,
.so-detail__actions-staff .theme-select {
  min-width: 12rem;
  flex: 1 1 12rem;
}

.invoice-detail-page .document-party + .doc-kam-strip {
  margin-top: 0.85rem;
}

.doc-kam-strip {
  display: flex;
  align-items: stretch;
  gap: 0.75rem;
  min-height: 4.5rem;
  padding: 0;
  overflow: hidden;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.16);
  background: rgba(15, 23, 42, 0.35);
}

.doc-kam-strip--missing {
  border-color: rgba(248, 113, 113, 0.35);
  background: rgba(127, 29, 29, 0.22);
}

.doc-kam-strip__media {
  flex: 0 0 4.5rem;
  align-self: stretch;
  min-height: 4.5rem;
}

.doc-kam-strip__photo {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 4.5rem;
  object-fit: cover;
  border-radius: 0;
}

.doc-kam-strip__photo--placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(148, 163, 184, 0.16);
  color: #94a3b8;
}

.doc-kam-strip__body {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.15rem;
  min-width: 0;
  flex: 1 1 auto;
  padding: 0.55rem 0;
}

.doc-kam-strip__name {
  font-size: 0.95rem;
  font-weight: 700;
  line-height: 1.2;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.doc-kam-strip__role {
  font-size: 0.72rem;
  font-weight: 500;
  line-height: 1.25;
  color: var(--text-muted, #94a3b8);
  text-transform: lowercase;
}

.doc-kam-strip__hint {
  font-size: 0.72rem;
  margin-top: 0.1rem;
}

.doc-kam-strip--assign {
  flex-wrap: wrap;
}

.doc-kam-strip--assign .doc-kam-strip__body {
  padding-right: 0.75rem;
}

.doc-kam-strip__assign {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.45rem;
  margin-top: 0.45rem;
}

.doc-kam-strip__assign .theme-select {
  min-width: 10.5rem;
  flex: 1 1 10.5rem;
}

.doc-kam-strip__actions {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: stretch;
  gap: 0.35rem;
