  fill: none;
  stroke: currentColor;
  stroke-width: 2.6;
  stroke-linecap: round;
  stroke-dasharray: 81.7;
  stroke-dashoffset: 81.7;
  transform-origin: 50% 50%;
  transform-box: fill-box;
  transform: rotate(-90deg);
  animation: so-verify-countdown 8s linear infinite;
}

