  gap: 0.4rem;
}

.kotak-feeds-sheet__select--busy {
  opacity: 1;
  cursor: wait;
}

@keyframes kotak-uncat-backdrop-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes kotak-uncat-card-in {
  from {
    opacity: 0;
    transform: translateY(28px) scale(0.94);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.dealers-modal-backdrop.kotak-uncat-popup {
  z-index: 92;
  background: rgba(0, 0, 0, 0.78);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  animation: kotak-uncat-backdrop-in 0.22s ease-out;
}

.kotak-uncat-popup__modal {
  width: min(100%, 36rem);
  max-height: calc(100dvh - 1.5rem);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 0.85rem 0.9rem 0.9rem;
  background: #0b1220;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.55);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  animation: kotak-uncat-card-in 0.38s cubic-bezier(0.22, 1, 0.36, 1);
}

.kotak-uncat-popup__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  flex-shrink: 0;
  margin-bottom: 0.55rem;
}

.kotak-uncat-popup__brand {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  min-width: 0;
}

.kotak-uncat-popup__logo {
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 12px;
  object-fit: cover;
  flex-shrink: 0;
}

.kotak-uncat-popup__modal h2 {
  margin: 0 0 0.18rem;
  font-size: 1.02rem;
}

.kotak-uncat-popup__fetched {
  margin: 0;
  font-size: 0.8rem;
  color: var(--text-secondary);
  line-height: 1.35;
}

.kotak-uncat-popup__fetched strong {
  color: var(--text-primary);
  font-weight: 750;
}

.kotak-uncat-popup__refresh {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0 0 0.35rem;
  padding: 0.15rem 0 0.55rem;
  border: none;
  background: none;
  color: #60a5fa;
  font-size: 0.95rem;
  font-weight: 750;
  cursor: pointer;
}

.kotak-uncat-popup__refresh:hover:not(:disabled) {
  color: #93c5fd;
}

.kotak-uncat-popup__refresh:disabled {
  cursor: wait;
  opacity: 0.85;
}

.kotak-uncat-popup__refresh.is-busy {
  color: #93c5fd;
}

.kotak-uncat-popup__hint {
  margin: 0 0 0.45rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}

.kotak-uncat-popup__hint.is-fail {
  color: #fca5a5;
}

.kotak-uncat-popup__close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 2.1rem;
  height: 2.1rem;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: #f58220;
  color: #111;
  cursor: pointer;
}

.kotak-uncat-popup__close:hover {
  background: #ff9a3d;
}

.kotak-uncat-popup__loading,
.kotak-uncat-popup__empty {
  display: grid;
  justify-items: center;
  gap: 0.65rem;
  margin: 1.4rem 0 0.8rem;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.88rem;
}

.kotak-uncat-popup__loading .spin-icon {
  color: #ed1c24;
}

.kotak-uncat-popup__cols {
  display: grid;
  grid-template-columns: 4.4rem minmax(0, 1fr) auto;
  gap: 0.55rem;
  flex-shrink: 0;
  padding: 0.35rem 0.15rem 0.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  font-size: 0.68rem;
  font-weight: 750;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.kotak-uncat-popup__cols span:last-child {
  text-align: right;
}

.kotak-uncat-popup__list {
  list-style: none;
  margin: 0;
  padding: 0.25rem 0 0.1rem;
  flex: 1;
  min-height: 0;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.kotak-uncat-popup__row {
  display: grid;
  grid-template-columns: 4.4rem minmax(0, 1fr) auto;
  gap: 0.55rem;
  align-items: start;
  padding: 0.5rem 0.35rem;
  border-radius: 10px;
}

.kotak-uncat-popup__row .kotak-feeds-sheet__details {
  min-width: 0;
}

.kotak-uncat-popup__row .kotak-feeds-sheet__details strong {
  overflow-wrap: anywhere;
  word-break: break-word;
}

.kotak-uncat-popup__amount {
  display: grid;
  justify-items: end;
  gap: 0.12rem;
  text-align: right;
  font-size: 0.92rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.kotak-uncat-popup__amount small {
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.kotak-uncat-popup__amount.is-in {
  color: #4ade80;
}

.kotak-uncat-popup__amount.is-out {
  color: #fca5a5;
}

.kotak-uncat-popup__footer {
  display: flex;
  justify-content: flex-end;
  flex-shrink: 0;
  margin-top: 0.65rem;
  padding-top: 0.7rem;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
}

.kotak-uncat-popup__close-btn {
  min-width: 7.5rem;
}

@media (max-width: 40rem) {
  .kotak-uncat-popup__cols {
    grid-template-columns: 4.4rem minmax(0, 1fr);
  }

  .kotak-uncat-popup__cols span:last-child {
    display: none;
  }

  .kotak-uncat-popup__row {
    grid-template-columns: 4.4rem minmax(0, 1fr);
    grid-template-areas:
      "date details"
      ". amount";
    row-gap: 0.28rem;
  }

  .kotak-uncat-popup__row > :nth-child(1) {
    grid-area: date;
  }

  .kotak-uncat-popup__row > :nth-child(2) {
    grid-area: details;
  }

  .kotak-uncat-popup__row > :nth-child(3) {
    grid-area: amount;
  }

  .kotak-uncat-popup__amount {
    justify-items: start;
    text-align: left;
    grid-auto-flow: column;
    align-items: baseline;
    gap: 0.4rem;
  }
}

.so-detail__selected-bank-feed {
  flex: 1 0 100%;
  width: 100%;
  margin: 0.35rem 0 0;
  padding: 0.45rem 0.6rem;
  border-radius: 8px;
  background: rgba(245, 130, 32, 0.14);
  color: var(--text-secondary);
  font-size: 0.78rem;
  line-height: 1.35;
}

.so-detail__selected-bank-feed strong {
  color: var(--text);
}

.so-detail__actions .so-detail__delete-btn {
  color: #fecaca;
  border-color: rgba(248, 113, 113, 0.45);
  background: rgba(127, 29, 29, 0.35);
}

.so-detail__actions .so-detail__delete-btn:hover:not(:disabled) {
  background: rgba(153, 27, 27, 0.5);
}

@media (min-width: 768px) {
  .so-detail__actions {
    position: static;
    padding: 0;
    background: transparent;
    border: 0;
    backdrop-filter: none;
  }

  .so-detail--with-actions {
    padding-bottom: 0.5rem;
  }

  .so-detail__actions .btn {
    flex: 1 1 0;
    min-width: 5.5rem;
    max-width: 10rem;
    font-size: 0.72rem;
  }

  .so-detail__actions--edit-dock .btn {
    flex: 0 0 auto;
    max-width: none;
    font-size: 0.875rem;
  }
}

.so-draft-editor {
  position: relative;
  z-index: 5;
  padding: 1rem 1.15rem 1.15rem;
  overflow: visible;
}

.so-draft-editor--embedded {
  padding: 0.85rem 1rem 0.5rem;
  background: transparent;
  border: 0;
}

.so-draft-editor__header {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1rem;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 0.85rem;
}

.so-draft-editor__title {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 650;
}

.so-draft-editor__subtitle {
  margin: 0.2rem 0 0;
}

.so-draft-editor__stamp-reminder {
  margin-top: -0.25rem;
}

.so-draft-editor__actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.so-draft-editor__lines {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.so-draft-editor__empty {
  padding: 0.85rem 0.25rem;
}

.so-draft-editor__line {
  display: grid;
  grid-template-columns: 3.25rem minmax(0, 1fr) auto auto auto;
  gap: 0.65rem;
  align-items: start;
  padding: 0.65rem 0.7rem;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.so-draft-editor__line-media,
.so-draft-editor__line-placeholder,
.so-draft-editor__option-media,
.so-draft-editor__option-placeholder {
  width: 3.25rem;
  height: 3.25rem;
  border-radius: 10px;
  overflow: hidden;
  background: rgba(0, 0, 0, 0.25);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}

.so-draft-editor__line-media .catalog-category-card__img,
.so-draft-editor__option-media .catalog-category-card__img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.so-draft-editor__line-placeholder,
.so-draft-editor__option-placeholder {
  color: rgba(255, 255, 255, 0.45);
}

.so-draft-editor__line-info {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.so-draft-editor__line-info strong {
  font-size: 0.95rem;
  line-height: 1.25;
}

.so-draft-editor__qty {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  padding: 0.15rem;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.so-draft-editor__qty-btn {
  width: 2rem;
  height: 2rem;
  border: 0;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.08);
  color: inherit;
  cursor: pointer;
}

.so-draft-editor__qty-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.so-draft-editor__qty-input {
  width: 2.6rem;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: center;
  font-weight: 650;
  font-size: 0.95rem;
  -moz-appearance: textfield;
}

.so-draft-editor__qty-input:focus {
  outline: none;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 6px;
}

.so-draft-editor__qty-input::-webkit-outer-spin-button,
.so-draft-editor__qty-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.so-draft-editor__line-total {
  min-width: 4.5rem;
  text-align: right;
  font-weight: 650;
  color: #fb923c;
  font-variant-numeric: tabular-nums;
}

.so-draft-editor__remove {
  width: 2.15rem;
  height: 2.15rem;
  border: 0;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: rgba(248, 113, 113, 0.12);
  color: #fca5a5;
  cursor: pointer;
}

.so-draft-editor__remove:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.so-draft-editor__picker {
  position: relative;
  z-index: 20;
  margin-top: 1rem;
}

.so-draft-editor__picker-label {
  display: block;
  font-size: 0.8rem;
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 0.35rem;
}

.so-draft-editor__search {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.55rem 0.75rem;
  border-radius: 12px;
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.so-draft-editor__search.is-open,
.so-draft-editor__search:focus-within {
  border-color: rgba(251, 146, 60, 0.55);
  box-shadow: 0 0 0 3px rgba(251, 146, 60, 0.12);
}

.so-draft-editor__search-icon,
.so-draft-editor__spinner {
  color: rgba(255, 255, 255, 0.45);
  flex-shrink: 0;
}

.so-draft-editor__search-input {
  flex: 1;
  min-width: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font-size: 0.95rem;
  outline: none;
}

.so-draft-editor__search-input::placeholder {
  color: rgba(255, 255, 255, 0.35);
}

.so-draft-editor__options {
  position: absolute;
  z-index: 40;
  left: 0;
  right: 0;
  top: calc(100% + 0.35rem);
  max-height: min(18rem, 50vh);
  overflow: auto;
  margin: 0;
  padding: 0.35rem;
  list-style: none;
  border-radius: 14px;
  background: #1a1d24;
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45);
}

/* Keep totals / item cards below the open product dropdown. */
.invoice-detail-page .invoice-detail-footer,
.invoice-detail-page .invoice-detail-items {
  position: relative;
  z-index: 1;
}

.so-draft-editor__option-empty {
  padding: 0.75rem 0.65rem;
}

.so-draft-editor__option {
  width: 100%;
  display: grid;
  grid-template-columns: 3.25rem minmax(0, 1fr) auto;
  gap: 0.65rem;
  align-items: center;
  padding: 0.5rem 0.55rem;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.so-draft-editor__option:hover,
.so-draft-editor__option.is-active,
.so-draft-editor__option.is-selected {
  background: rgba(251, 146, 60, 0.12);
}

.so-draft-editor__option-body {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.so-draft-editor__option-body strong {
  font-size: 0.92rem;
  line-height: 1.25;
}

.so-draft-editor__option-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.1rem;
  font-variant-numeric: tabular-nums;
}

.so-draft-editor__freight {
  margin-top: 1rem;
  padding-top: 0.85rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.so-draft-editor__freight-title {
  margin: 0 0 0.5rem;
  font-size: 0.95rem;
  font-weight: 700;
}

.so-draft-editor__freight-amount {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-top: 0.75rem;
  max-width: 14rem;
}

.so-draft-editor__footer {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  margin-top: 0.95rem;
  padding-top: 0.75rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

@media (max-width: 640px) {
  .so-draft-editor__line {
    grid-template-columns: 3rem minmax(0, 1fr) auto;
    grid-template-areas:
      "media info remove"
      "media qty total";
  }

  .so-draft-editor__line-media { grid-area: media; }
  .so-draft-editor__line-info { grid-area: info; }
  .so-draft-editor__qty { grid-area: qty; justify-self: start; }
  .so-draft-editor__line-total { grid-area: total; }
  .so-draft-editor__remove { grid-area: remove; justify-self: end; }
}
